def smart_convert_columns_for_comparison(df, columns_to_check=None):
    """
    Smart type conversion utility for comparison operations.
    Converts numeric-looking string columns to numeric to prevent type comparison errors.
    Optimized for performance with sampling-based detection.

    Args:
       df: DataFrame to process
       columns_to_check: List of column names to check. If None, checks all object-type columns.

    Returns:
       Modified DataFrame with numeric-looking columns converted to numeric.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return _mark_alteryx_dataframe(df)

    # Default to checking all object columns if none specified
    if columns_to_check is None:
        columns_to_check = df.select_dtypes(include=['object']).columns

    for col in columns_to_check:
        if col not in df.columns:
            continue

        # Skip if already numeric
        if pd.api.types.is_numeric_dtype(df[col]):
            continue

        # Sample-based detection (check first 100 non-null values)
        sample = df[col].dropna().head(100)
        if len(sample) == 0:
            continue

        # Count numeric values in sample
        numeric_count = 0
        for val in sample:
            try:
                float(str(val))
                numeric_count += 1
            except (ValueError, TypeError):
                pass

        # If >80% of sample is numeric, convert the entire column
        if numeric_count / len(sample) > 0.8:
            try:
                df[col] = pd.to_numeric(df[col], errors='coerce')
            except Exception:
                # Silent fail - column stays as-is
                pass

    return df


def normalize_dataframe_alignment(df):
    """
    Normalize DataFrame to ensure columns are properly aligned with data.
    CRITICAL for Alteryx files and any DataFrame that has been filtered/manipulated.
    """
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df

    try:
        normalized_df = df.copy(deep=True)
        normalized_df.columns = [str(col).strip() for col in normalized_df.columns]
        normalized_df = normalized_df.reset_index(drop=True)
        return normalized_df
    except Exception:
        # Fall back to a best-effort rebuild only when a direct copy path fails.
        try:
            return pd.DataFrame(
                data=df.to_numpy(copy=True),
                columns=[str(col).strip() for col in df.columns],
                index=range(len(df))
            )
        except Exception:
            return df


def read_alteryx_yxdb(file_obj):
    """Read Alteryx .yxdb into a pandas DataFrame."""
    if file_obj is None:
        return None

    try:
        file_obj.seek(0)
    except Exception:
        pass

    raw_bytes = file_obj.read()

    try:
        file_obj.seek(0)
    except Exception:
        pass

    if not raw_bytes:
        raise RuntimeError("Unable to read .yxdb: file is empty or could not be read.")

    # Validate magic bytes before passing to a reader.
    MAGIC_STANDARD = b"Alteryx Database File"  # 21 bytes
    lowered = raw_bytes[:64].lower()

    # Newer Alteryx e2/AMP format.
    if lowered.startswith(b"alteryx e2 database file"):
        try:
            import openyxdb
        except ImportError as import_error:
            raise RuntimeError(
                "Unable to read .yxdb: this file uses Alteryx e2 format and requires the 'openyxdb' package. "
                "Install it with: pip install openyxdb"
            ) from import_error

        temp_e2_path = None
        try:
            with tempfile.NamedTemporaryFile(delete=False, suffix=".yxdb") as temp_e2_file:
                temp_e2_file.write(raw_bytes)
                temp_e2_path = temp_e2_file.name
            df = openyxdb.to_pandas(temp_e2_path)
            # CRITICAL: Ensure columns have no leading/trailing spaces and data is properly aligned
            if isinstance(df, pd.DataFrame):
                df.columns = df.columns.str.strip()
                df = _mark_alteryx_dataframe(df)
            return df
        except Exception as e2_error:
            raise RuntimeError(f"Unable to read .yxdb (e2 format): {e2_error}") from e2_error
        finally:
            if temp_e2_path and os.path.exists(temp_e2_path):
                os.remove(temp_e2_path)

    if raw_bytes[:len(MAGIC_STANDARD)] != MAGIC_STANDARD:
        raise RuntimeError(
            "Unable to read .yxdb: file does not appear to be a valid Alteryx Database File. "
            f"Got header: {raw_bytes[:24]!r}"
        )

    try:
        from yxdb.yxdb_reader import YxdbReader
    except ImportError as import_error:
        raise RuntimeError(
            "Alteryx (.yxdb) reading requires the 'yxdb' package. Install it with: pip install yxdb"
        ) from import_error

    from io import BytesIO
    stream = BytesIO(raw_bytes)

    # Try top-level convenience functions first (older API versions)
    try:
        import yxdb as _yxdb_mod
        if hasattr(_yxdb_mod, "read_pandas"):
            df = _yxdb_mod.read_pandas(stream)
            # CRITICAL: Ensure columns have no leading/trailing spaces
            if isinstance(df, pd.DataFrame):
                df.columns = df.columns.str.strip()
                df = _mark_alteryx_dataframe(df)
            return df
        if hasattr(_yxdb_mod, "read_yxdb"):
            df = _yxdb_mod.read_yxdb(stream)
            if isinstance(df, pd.DataFrame):
                df.columns = df.columns.str.strip()
                df = _mark_alteryx_dataframe(df)
            return df
    except Exception:
        pass

    # yxdb >= 1.x: use YxdbReader with stream= kwarg
    try:
        reader = YxdbReader(stream=stream)
        fields = reader.list_fields()
        field_names = [f.name.strip() for f in fields]
        field_types = [f.type if hasattr(f, 'type') else 'Unknown' for f in fields]

        rows = []
        row_count = 0
        while reader.next():
            row_data = []
            for i in range(len(field_names)):
                try:
                    val = reader.read_index(i)
                    row_data.append(val)
                except Exception as field_err:
                    # If we can't read a field, append None
                    row_data.append(None)
            rows.append(row_data)
            row_count += 1

        reader.close()

        # Create DataFrame with proper column ordering
        df = pd.DataFrame(rows, columns=field_names)

        # Remove completely empty columns
        df = df.dropna(how='all', axis=1)

        # Verify data integrity: check if any columns are completely None (misread columns)
        # This helps identify if the Alteryx reader misaligned any fields
        all_none_cols = [col for col in df.columns if df[col].isna().all()]
        if all_none_cols:
            # Log warning but continue - user needs to see data to diagnose
            pass

        return df
    except Exception as e:
        raise RuntimeError(f"Unable to read .yxdb: {e}") from e


def _mark_alteryx_dataframe(df):
    """Attach YXDB source metadata so downstream steps can preserve column mapping."""
    if not isinstance(df, pd.DataFrame):
        return df
    try:
        df.attrs["source_file_format"] = "yxdb"
        df.attrs["yxdb_column_order"] = [str(col).strip() for col in df.columns]
    except Exception:
        pass
    return df


def stabilize_alteryx_mapping(df):
    """Keep original YXDB column order stable; no-op for non-Alteryx dataframes."""
    if not isinstance(df, pd.DataFrame):
        return df

    source_format = str(df.attrs.get("source_file_format", "")).strip().lower()
    if source_format != "yxdb":
        return df

    stabilized = df.copy(deep=True)
    stabilized.columns = [str(col).strip() for col in stabilized.columns]

    baseline_columns = df.attrs.get("yxdb_column_order")
    if isinstance(baseline_columns, list):
        normalized_baseline = [str(col).strip() for col in baseline_columns]
        if len(normalized_baseline) == len(stabilized.columns):
            # Reorder only; do not coerce values. This preserves original mapping.
            stabilized = stabilized.reindex(columns=normalized_baseline)

    stabilized = stabilized.reset_index(drop=True)
    stabilized.attrs.update(df.attrs)
    return stabilized


def load_csv_excel_with_row_options(
        file_obj,
        file_format,
        start_row=1,
        header_row=1,
        max_records=0,
        sheet_name=None):
    """Load CSV/Excel with configurable header row and record window."""
    if file_obj is None:
        return None

    normalized_format = str(file_format or "").lower()

    try:
        file_obj.seek(0)
    except Exception:
        pass

    start_row = int(start_row or 1)
    header_row = int(header_row if header_row is not None else 1)
    max_records = int(max_records or 0)

    if start_row < 1:
        start_row = 1
    if header_row < 0:
        header_row = 0
    if max_records < 0:
        max_records = 0

    header_arg = None if header_row == 0 else max(0, header_row - 1)

    if normalized_format == "csv":
        df = pd.read_csv(file_obj, header=header_arg)
    elif normalized_format in ["xlsx", "xls", "excel"]:
        read_sheet = sheet_name if sheet_name else 0
        df = pd.read_excel(file_obj, sheet_name=read_sheet, header=header_arg)
    else:
        return None

    if header_row == 0:
        start_index = max(0, start_row - 1)
    else:
        # Data begins right after the header row in the source file.
        first_data_row = header_row + 1
        start_index = max(0, start_row - first_data_row)

    df = df.iloc[start_index:]

    if max_records > 0:
        df = df.head(max_records)

    df = df.reset_index(drop=True)
    df.columns = [str(col).strip() for col in df.columns]
    return df


def _read_uploaded_file_bytes(file_obj):
    """Safely read uploaded file bytes without leaving the stream consumed."""
    if file_obj is None:
        return None
    try:
        file_obj.seek(0)
    except Exception:
        pass
    file_bytes = file_obj.read()
    try:
        file_obj.seek(0)
    except Exception:
        pass
    return file_bytes


def trim_text_columns_inplace(df):
    """Trim leading/trailing spaces only for string cells (avoids expensive full-column cast)."""
    if not isinstance(df, pd.DataFrame) or df.empty:
        return df

    text_like_cols = df.select_dtypes(include=["object", "string"]).columns
    for col in text_like_cols:
        series = df[col]
        if pd.api.types.is_string_dtype(series):
            df[col] = series.str.strip()
            continue
        string_mask = series.map(lambda v: isinstance(v, str))
        if bool(string_mask.any()):
            df.loc[string_mask, col] = series.loc[string_mask].str.strip()
    return df


@st.cache_data(ttl=_CACHE_TTL, show_spinner=False)
def _get_excel_sheet_names_cached(file_bytes):
    if not file_bytes:
        return []
    return pd.ExcelFile(BytesIO(file_bytes)).sheet_names


@st.cache_data(ttl=_CACHE_TTL, show_spinner=False)
def _load_file_from_bytes_cached(
        file_bytes,
        file_name,
        file_format,
        start_row=1,
        header_row=1,
        max_records=0,
        sheet_name=None):
    """Cached parser for uploaded bytes to avoid repeated expensive re-reads on rerun."""
    if not file_bytes:
        return None

    normalized_format = normalize_file_format(file_format)
    read_buffer = BytesIO(file_bytes)

    if normalized_format == "csv" or str(file_name).lower().endswith(".csv"):
        return load_csv_excel_with_row_options(
            file_obj=read_buffer,
            file_format="csv",
            start_row=start_row,
            header_row=header_row,
            max_records=max_records
        )

    if normalized_format in ["xlsx", "xls", "excel"] or str(file_name).lower().endswith(".xlsx") or str(
            file_name).lower().endswith(".xls"):
        return load_csv_excel_with_row_options(
            file_obj=read_buffer,
            file_format=normalized_format,
            start_row=start_row,
            header_row=header_row,
            max_records=max_records,
            sheet_name=sheet_name
        )

    if normalized_format == "parquet" or str(file_name).lower().endswith(".parquet"):
        return pd.read_parquet(read_buffer)

    if normalized_format == "json" or str(file_name).lower().endswith(".json"):
        return pd.read_json(read_buffer)

    if normalized_format == "yxdb" or str(file_name).lower().endswith(".yxdb"):
        df = read_alteryx_yxdb(read_buffer)
        if isinstance(df, pd.DataFrame) and not df.empty:
            df = stabilize_alteryx_mapping(normalize_dataframe_alignment(df))
        return df

    return None


def normalize_file_format(file_format, default_value="csv"):
    """Return lowercase file format safely even when config value is non-string."""
    if file_format is None:
        return str(default_value).lower()
    return str(file_format).strip().lower()


