def apply_saved_configuration():
    # -----------------------------------------------------
    # USE MAIN_DF (APP DATAFRAME)
    # -----------------------------------------------------

    df = st.session_state.get("main_df")

    if df is None:
        return

    df = df.copy()

    pipeline_steps = st.session_state.get(
        "pipeline_steps",
        []
    )

    if not pipeline_steps:
        return

    for step in pipeline_steps:

        try:

            if not isinstance(step, dict):
                continue

            step_type = step.get("type", "")

            # =================================================
            # DROP DUPLICATES
            # =================================================

            if step_type == "drop_duplicates":

                df = df.drop_duplicates()

            # =================================================
            # DROP NULLS
            # =================================================

            elif step_type == "drop_nulls":

                df = df.dropna()

            # =================================================
            # UPPERCASE
            # =================================================

            elif step_type == "uppercase":

                col = step.get("column")

                if col in df.columns:
                    df[col] = (
                        df[col]
                        .astype(str)
                        .str.upper()
                    )

            # =================================================
            # LOWERCASE
            # =================================================

            elif step_type == "lowercase":

                col = step.get("column")

                if col in df.columns:
                    df[col] = (
                        df[col]
                        .astype(str)
                        .str.lower()
                    )

            # =================================================
            # TRIM
            # =================================================

            elif step_type == "trim":

                col = step.get("column")

                if col in df.columns:
                    df[col] = (
                        df[col]
                        .astype(str)
                        .str.strip()
                    )

        except Exception as e:

            st.warning(
                f"Pipeline step failed: {e}"
            )


