def detect_primary_tool_from_prompt(prompt_lower):
    """
    Detects the primary intended tool from a lower-cased prompt string.

    Strategy:
      1. Collect all tool-name occurrences and keyword occurrences with their
         positions in the prompt.
      2. Tool-name exact matches are preferred over keyword matches.
      3. When multiple tools are found, the one whose earliest mention appears
         first in the prompt wins — so "Add Formula Tool … on output of Filter
         Tool" correctly resolves to Formula Tool.

    Returns (tool_name, match_type) or (None, None).
    """
    candidates = []  # list of (position, tool_name, match_type)

    # 1. Exact tool-name matches — record earliest position of each
    for tool_name in DATA_PREP_TOOL_NAMES:
        pos = prompt_lower.find(tool_name.lower())
        if pos != -1:
            candidates.append((pos, tool_name, "tool_name"))

    # 2. Synonym matches
    for alias_text, alias_tool in DATA_PREP_TOOL_SYNONYMS.items():
        pos = prompt_lower.find(alias_text)
        if pos != -1:
            candidates.append((pos, alias_tool, "synonym"))

    # 3. Keyword matches (lower priority than explicit tool names)
    for kw, kw_tool in DATA_PREP_TOOL_KEYWORDS.items():
        pos = prompt_lower.find(kw)
        if pos != -1:
            candidates.append((pos, kw_tool, "keyword"))

    if not candidates:
        return None, None

    # Sort: tool_name matches beat synonyms beat keywords; ties broken by
    # earliest position in the prompt.
    priority = {"tool_name": 0, "synonym": 1, "keyword": 2}
    candidates.sort(key=lambda c: (priority[c[2]], c[0]))
    return candidates[0][1], candidates[0][2]


