def extract_tool_config_from_prompt(tool_name, prompt_text, available_columns=None):
    """
    Best-effort extraction of tool config values from free-text prompt.
    Returns a dict of {field_key: prefilled_value}.
    All values are strings or None.
    """
    p = prompt_text.strip()
    pl = p.lower()
    extracted = {}
    cols = [c.lower() for c in (available_columns or [])]

    if tool_name == "Formula Tool":
        # Column name: after 'name', 'named', 'column named', 'called', or quotes
        col_match = re.search(
            r"""(?:column\s+(?:name[d]?|called)|name[d]?\s+(?:as\s+)?|new\s+column\s+)[\'\"]?([A-Za-z0-9_\s]+?)[\'\"]?(?:\s+such|\s+as|\s+that|\s*=|\s+where|$)""",
            p, re.IGNORECASE
        )
        if not col_match:
            col_match = re.search(r"""[\'\"]([A-Za-z0-9_ ]+?)[\'\"]""", p)
        if col_match:
            extracted["output_column"] = col_match.group(1).strip()

        # Expression: after 'such that', '=', 'as', 'that', 'where'
        expr_match = re.search(
            r"""(?:such\s+that|expression\s+is|formula\s*[:=]|equals?\s*)(.+)$""",
            p, re.IGNORECASE
        )
        if not expr_match:
            # try after '='
            expr_match = re.search(r"""=\s*(.+)$""", p)
        if expr_match:
            raw_expr = expr_match.group(1).strip().rstrip(".")
            # wrap bare column references in []
            for col in sorted((available_columns or []), key=len, reverse=True):
                pattern = re.compile(r'\b' + re.escape(col) + r'\b', re.IGNORECASE)
                if pattern.search(raw_expr) and f'[{col}]' not in raw_expr:
                    raw_expr = pattern.sub(f'[{col}]', raw_expr)
            extracted["expression"] = raw_expr

    elif tool_name == "Filter Tool":
        cond_match = re.search(
            r"""(?:where|condition|filter\s+(?:by|with)?|that\s+)(.+)$""",
            p, re.IGNORECASE
        )
        if cond_match:
            extracted["expression"] = cond_match.group(1).strip().rstrip(".")

    elif tool_name == "Sort Tool":
        col_match = re.search(r"""(?:sort|order)\s+by\s+([A-Za-z0-9_,\s]+?)(?:\s+(asc|desc|ascending|descending)|$)""",
                              pl)
        if col_match:
            extracted["columns"] = col_match.group(1).strip()
            order_raw = (col_match.group(2) or "ascending").lower()
            extracted["sort_orders"] = "descending" if "desc" in order_raw else "ascending"

    elif tool_name == "Aggregate Tool":
        gb_match = re.search(r"""group\s+by\s+([A-Za-z0-9_,\s]+?)(?:\s+and|\s+sum|\s+count|\s+compute|$)""", pl)
        if gb_match:
            extracted["group_cols"] = gb_match.group(1).strip()
        agg_match = re.search(r"""(sum|count|mean|average|min|max|median)\s+(?:of\s+)?([A-Za-z0-9_]+)""", pl)
        if agg_match:
            fn_raw = agg_match.group(1).lower()
            extracted["agg_col"] = agg_match.group(2).strip()
            extracted["agg_function"] = "mean" if fn_raw in ("average", "avg") else fn_raw

    elif tool_name == "Select Tool":
        col_match = re.search(r"""(?:keep|select|choose)\s+(?:columns?\s+)?(.+)$""", p, re.IGNORECASE)
        if col_match:
            extracted["columns"] = col_match.group(1).strip().rstrip(".")

    elif tool_name == "Unique Tool":
        col_match = re.search(r"""(?:based\s+on|on|using)\s+(.+)$""", p, re.IGNORECASE)
        if col_match:
            extracted["columns"] = col_match.group(1).strip().rstrip(".")

    elif tool_name == "Sampling Tool":
        pct_match = re.search(r"""(\d+(?:\.\d+)?)\s*%""", p)
        if pct_match:
            extracted["sample_pct"] = pct_match.group(1)
        row_match = re.search(r"""(\d+)\s*rows?""", pl)
        if row_match:
            extracted["sample_size"] = row_match.group(1)

    elif tool_name == "Random Sampling Tool":
        pct_match = re.search(r"""(\d+(?:\.\d+)?)\s*%""", p)
        row_match = re.search(r"""(\d+)\s*rows?""", pl)
        n_match = re.search(r"""(\d+)\s*records?""", pl)
        if pct_match:
            extracted["sample_mode"] = "N Percent"
            extracted["n_value"] = pct_match.group(1)
        elif row_match:
            extracted["sample_mode"] = "N Records"
            extracted["n_value"] = row_match.group(1)
        elif n_match:
            extracted["sample_mode"] = "N Records"
            extracted["n_value"] = n_match.group(1)
        if "without replacement" in pl:
            extracted["replacement"] = "False"
        elif "with replacement" in pl:
            extracted["replacement"] = "True"
        seed_match = re.search(r"""seed\s+(\d+)""", pl)
        if seed_match:
            extracted["seed"] = seed_match.group(1)
        group_match = re.search(r"""group\s+by\s+([A-Za-z0-9_,\s]+?)(?:\.|$)""", pl)
        if group_match:
            extracted["group_cols"] = group_match.group(1).strip()

    elif tool_name == "Tile Tool":
        num_match = re.search(r"""(\d+)\s*(?:tile|bucket|quantile|quartile)""", pl)
        if num_match:
            extracted["num_tiles"] = num_match.group(1)
        col_match = re.search(r"""(?:based\s+on|on|using|for\s+column)\s+([A-Za-z0-9_]+)""", pl)
        if col_match:
            extracted["tile_column"] = col_match.group(1).strip()

    elif tool_name == "Multi Row Formula Tool":
        col_match = re.search(r"""(?:create|new column|output)\s+([A-Za-z0-9_]+)""", pl)
        if col_match:
            extracted["output_column"] = col_match.group(1)
        expr_match = re.search(r"""(?:formula|expression|=)\s*(.+?)(?:\.\s*group|$)""", p, re.IGNORECASE)
        if expr_match:
            extracted["expression"] = expr_match.group(1).strip()
        group_match = re.search(r"""group\s+by\s+([A-Za-z0-9_,\s]+?)(?:\.|$)""", pl)
        if group_match:
            extracted["group_cols"] = group_match.group(1).strip()

    elif tool_name == "Multi Field Formula Tool":
        fields_match = re.search(r"""(?:to fields?|fields?|columns?)\s+([A-Za-z0-9_,\s]+?)(?:\.\s*create|$)""", pl)
        if fields_match:
            extracted["fields"] = fields_match.group(1).strip()
        expr_match = re.search(r"""(?:apply formula|formula)[:\s]+(.+?)(?:\s+to fields?|$)""", p, re.IGNORECASE)
        if expr_match:
            extracted["expression"] = expr_match.group(1).strip()
        suffix_match = re.search(r"""suffix\s+([A-Za-z0-9_]+)""", pl)
        if suffix_match:
            extracted["output_suffix"] = suffix_match.group(1)

    elif tool_name == "RecordID Tool":
        col_match = re.search(r"""(?:column|field|name)\s+([A-Za-z0-9_]+)""", pl)
        if col_match:
            extracted["id_column"] = col_match.group(1)
        start_match = re.search(r"""start(?:ing)?\s+(?:at|from|value)?\s*(\d+)""", pl)
        if start_match:
            extracted["start_value"] = start_match.group(1)
        group_match = re.search(r"""group\s+by\s+([A-Za-z0-9_,\s]+?)(?:\.|$)""", pl)
        if group_match:
            extracted["group_cols"] = group_match.group(1).strip()

    elif tool_name == "Join Tool":
        jtype_match = re.search(r"""\b(inner|left|right|outer)\s+join\b""", pl)
        if jtype_match:
            extracted["join_type"] = jtype_match.group(1)
        key_match = re.search(r"""(?:on\s+(?:key\s+)?column\s+|on\s+)([A-Za-z0-9_,\s]+?)(?:\s+join|\s*$|\.)""", pl)
        if key_match:
            extracted["join_keys"] = key_match.group(1).strip()

    elif tool_name == "Parse Tool":
        col_match = re.search(r"""(?:split|parse)\s+([A-Za-z0-9_]+)""", pl)
        if col_match:
            extracted["parse_column"] = col_match.group(1)
        delim_match = re.search(r"""(?:delimiter|on|by)\s+[\"\']?([^\"\']+?)[\"\']?(?:\s+into|$|\.)""", p,
                                re.IGNORECASE)
        if delim_match:
            extracted["delimiter"] = delim_match.group(1).strip()

    elif tool_name == "Report Tool":
        fn_match = re.search(r"""(?:file|name(?:d)?|called?)\s+[\"\']?([A-Za-z0-9_\-\s]+?)[\"\']?(?:\.|$)""", p,
                             re.IGNORECASE)
        if fn_match:
            extracted["filename"] = fn_match.group(1).strip()
        sheet_match = re.search(r"""sheet\s+[\"\']?([A-Za-z0-9_\s]+?)[\"\']?(?:\s+from|\.|$)""", p, re.IGNORECASE)
        if sheet_match:
            extracted["sheet_name"] = sheet_match.group(1).strip()
        title_match = re.search(r"""title\s+[\"\']([^\"\']+)[\"\']""", p, re.IGNORECASE)
        if title_match:
            extracted["title"] = title_match.group(1).strip()

    return extracted


PAGE_WIDGET_STATE_RULES = {
    "profile": {
        "exact": {"custom_metrics_count"},
        "prefixes": ["cust_name_", "cust_expr_", "edit_f_"]
    }
}


def sanitize_dataset_id(name):
    safe_name = re.sub(r"[^a-zA-Z0-9_]+", "_", str(name)).strip("_").lower()
    return safe_name or "dataset"


def coerce_iterable_to_list(values):
    if values is None:
        return []

    if isinstance(values, (pd.Index, pd.Series)):
        return list(values.tolist())

    if isinstance(values, np.ndarray):
        return list(values.tolist())

    if isinstance(values, (list, tuple, set)):
        return list(values)

    try:
        return list(values)
    except Exception:
        return [values]


def normalize_scalar_column(saved_value, available_columns, fallback=None):
    available_columns = coerce_iterable_to_list(available_columns)
    if saved_value in available_columns:
        return saved_value

    lookup = {str(col).lower(): col for col in available_columns}
    matched = lookup.get(str(saved_value).lower()) if saved_value else None
    if matched:
        return matched

    if fallback in available_columns:
        return fallback

    return fallback if fallback is not None else (available_columns[0] if available_columns else None)


def normalize_column_list(saved_values, available_columns, fallback=None, exclude=None, default_to_all=False):
    available_columns = coerce_iterable_to_list(available_columns)
    exclude = set(coerce_iterable_to_list(exclude))
    candidate_columns = [col for col in available_columns if col not in exclude]
    lookup = {str(col).lower(): col for col in candidate_columns}

    normalized = []
    for value in coerce_iterable_to_list(saved_values):
        if value in candidate_columns and value not in normalized:
            normalized.append(value)
            continue

        matched = lookup.get(str(value).lower())
        if matched and matched not in normalized:
            normalized.append(matched)

    if normalized:
        return normalized

    fallback = coerce_iterable_to_list(fallback)
    normalized_fallback = []
    for value in fallback:
        matched = value if value in candidate_columns else lookup.get(str(value).lower())
        if matched and matched not in normalized_fallback:
            normalized_fallback.append(matched)

    if normalized_fallback:
        return normalized_fallback

    if default_to_all:
        return candidate_columns

    return []


def extract_used_columns_from_config(config):
    used_columns = []

    def _walk(value):
        if isinstance(value, dict):
            for nested_value in value.values():
                _walk(nested_value)
        elif isinstance(value, list):
            for item in value:
                _walk(item)
        elif isinstance(value, str):
            used_columns.append(value)

    _walk(config or {})
    return used_columns


def migrate_runtime_config(runtime_config, available_columns):
    normalized_columns = coerce_iterable_to_list(available_columns)
    if not runtime_config or len(normalized_columns) == 0:
        return copy.deepcopy(runtime_config or {})

    from page_configuration_manager import ConfigColumnMatcher

    migrated_runtime = copy.deepcopy(runtime_config)
    saved_columns = runtime_config.get("used_columns")
    if saved_columns is None:
        saved_columns = extract_used_columns_from_config(runtime_config.get("config", {}))
    saved_columns = coerce_iterable_to_list(saved_columns)

    matched, unmatched, extra = ConfigColumnMatcher.find_matching_columns(saved_columns, list(normalized_columns))
    migrated_config, report = ConfigColumnMatcher.migrate_config(
        runtime_config.get("config", {}),
        matched,
        list(normalized_columns)
    )
    migrated_runtime["config"] = migrated_config
    migrated_runtime["used_columns"] = [col for col in saved_columns if
                                        str(col).lower() in {str(c).lower() for c in normalized_columns}]
    migrated_runtime["migration_report"] = {
        "matched": matched,
        "unmatched": unmatched,
        "extra": extra,
        "details": report
    }
    return migrated_runtime


def get_saved_page_runtime(page_key, available_columns=None):
    runtime_config = copy.deepcopy(st.session_state.page_runtime_configs.get(page_key, {}))
    if available_columns is not None:
        return migrate_runtime_config(runtime_config, available_columns)
    return runtime_config


def sanitize_widget_state_value(value):
    if value is None or isinstance(value, (str, int, float, bool)):
        return value

    if isinstance(value, list):
        return [sanitize_widget_state_value(item) for item in value]

    if isinstance(value, tuple):
        return [sanitize_widget_state_value(item) for item in value]

    if isinstance(value, dict):
        sanitized = {}
        for key, nested_value in value.items():
            sanitized[str(key)] = sanitize_widget_state_value(nested_value)
        return sanitized

    return str(value)


def collect_page_widget_state(page_key):
    rules = PAGE_WIDGET_STATE_RULES.get(page_key, {})
    exact_keys = set(rules.get("exact", set()))
    prefixes = list(rules.get("prefixes", []))
    captured_state = {}

    for key, value in st.session_state.items():
        if key in exact_keys or any(str(key).startswith(prefix) for prefix in prefixes):
            captured_state[key] = sanitize_widget_state_value(copy.deepcopy(value))

    return captured_state


def restore_saved_page_widget_states():
    core_profile_metrics = {
        "Completeness": "completeness",
        "Consistency": "uniqueness * 0.95",
        "Validity": "completeness * 0.95",
        "Uniqueness": "uniqueness",
        "Accuracy": "90.0"
    }

    for page_key, runtime in st.session_state.get("page_runtime_configs", {}).items():
        widget_state = runtime.get("widget_state") or {}
        for key, value in widget_state.items():
            if value is None or isinstance(value, (str, int, float, bool)):
                st.session_state[key] = value
            elif isinstance(value, list):
                st.session_state[key] = list(value)
            elif isinstance(value, dict):
                st.session_state[key] = dict(value)
            else:
                st.session_state[key] = copy.deepcopy(value)

        if page_key == "profile":
            dq_rules = runtime.get("config", {}).get("dq_rules_config", {})
            if isinstance(dq_rules, dict) and dq_rules:
                profile_metric_keys = {
                    "Completeness": "edit_f_comp",
                    "Consistency": "edit_f_cons",
                    "Validity": "edit_f_val",
                    "Uniqueness": "edit_f_uniq",
                    "Accuracy": "edit_f_acc"
                }
                for metric_name, widget_key in profile_metric_keys.items():
                    st.session_state[widget_key] = dq_rules.get(metric_name, core_profile_metrics[metric_name])

                custom_metric_items = [
                    (metric_name, metric_formula)
                    for metric_name, metric_formula in dq_rules.items()
                    if metric_name not in core_profile_metrics
                ]
                st.session_state["custom_metrics_count"] = len(custom_metric_items)
                for idx, (metric_name, metric_formula) in enumerate(custom_metric_items):
                    st.session_state[f"cust_name_{idx}"] = metric_name
                    st.session_state[f"cust_expr_{idx}"] = metric_formula


