def ensure_workflow_step_identity(step, step_index):
    if not isinstance(step, dict):
        return step

    # Avoid deepcopy on JSON load — configs are already fresh dicts from json.loads.
    if not step.get("id"):
        step["id"] = f"workflow_step_{step_index}_{sanitize_dataset_id(step.get('tool', 'tool'))}"
    return step


def remember_page_runtime(page_key, config, used_columns=None, dataset_id=None, widget_state=None):
    page_name, tool_name = PAGE_TOOL_MAP.get(page_key, (page_key, page_key))
    runtime_payload = {
        "page_name": page_name,
        "tool_name": tool_name,
        "config": copy.deepcopy(config or {}),
        "used_columns": coerce_iterable_to_list(used_columns),
        "dataset_id": dataset_id,
        "widget_state": copy.deepcopy(
            widget_state if widget_state is not None else collect_page_widget_state(page_key)),
        "saved_at": dt_datetime.now().isoformat()
    }
    st.session_state.page_runtime_configs[page_key] = runtime_payload


def extract_json_object(text):
    if not text:
        return None

    stripped = text.strip()
    if stripped.startswith("```"):
        stripped = re.sub(r"^```(?:json)?", "", stripped).strip()
        stripped = re.sub(r"```$", "", stripped).strip()

    try:
        return json.loads(stripped)
    except Exception:
        pass

    start_idx = stripped.find("{")
    end_idx = stripped.rfind("}")
    if start_idx >= 0 and end_idx > start_idx:
        try:
            return json.loads(stripped[start_idx:end_idx + 1])
        except Exception:
            return None
    return None


def normalize_text_choice(requested_value, allowed_values, default_value=None):
    allowed_values = coerce_iterable_to_list(allowed_values)
    if requested_value in allowed_values:
        return requested_value

    requested_text = str(requested_value or "").strip().lower()
    for option in allowed_values:
        if str(option).strip().lower() == requested_text:
            return option

    if default_value in allowed_values:
        return default_value

    return allowed_values[0] if allowed_values else default_value


