def _localize_step_guide_text(text, language="English"):
    """Return Step Guide text in the user-selected language."""
    raw = "" if text is None else str(text)
    if str(language or "English").strip().lower() != "arabic":
        return raw
    return STEP_GUIDE_TEXT_AR.get(raw, raw)


def get_simple_step_text(steps, stage_index, language="English"):
    current_step = _localize_step_guide_text(steps[stage_index], language)
    if stage_index + 1 < len(steps):
        next_step = _localize_step_guide_text(steps[stage_index + 1], language)
    else:
        next_step = _localize_step_guide_text("Finish and review the result.", language)
    if str(language or "English").strip().lower() == "arabic":
        return (
            f"الآن: {current_step}.\n"
            f"التالي: {next_step}."
        )
    return (
        f"Now: {current_step}.\n"
        f"Next: {next_step}."
    )


def stage_copilot_prompt_text(page_name, new_text, append=True):
    prompt_key = f"copilot_prompt_text_{page_name}"
    stage_key = f"dp_prompt_stage_{page_name}"
    incoming_text = str(new_text or "").strip()
    if not incoming_text:
        return

    existing_text = str(
        st.session_state.get(stage_key, st.session_state.get(prompt_key, ""))
    ).strip()

    if append and existing_text:
        if incoming_text in existing_text:
            combined_text = existing_text
        else:
            combined_text = f"{existing_text}\n{incoming_text}"
    else:
        combined_text = incoming_text

    st.session_state[stage_key] = combined_text


def transcribe_voice_prompt(audio_file):
    if audio_file is None:
        return None, "Record or upload a voice prompt first."

    audio_name = str(getattr(audio_file, "name", "voice_prompt.wav") or "voice_prompt.wav")
    audio_type = str(getattr(audio_file, "type", "") or "").lower()
    is_wav_audio = (
            audio_name.lower().endswith(".wav")
            or audio_type in {"audio/wav", "audio/x-wav", "audio/wave"}
            or audio_type.startswith("audio/wav")
            or audio_type.startswith("audio/x-wav")
            or audio_type.startswith("audio/wave")
    )
    if not is_wav_audio:
        return None, "Voice-to-text currently supports WAV audio so the transcript stays on your machine."

    temp_audio_path = None
    try:
        if hasattr(audio_file, "seek"):
            audio_file.seek(0)

        audio_bytes = None
        if hasattr(audio_file, "getbuffer"):
            audio_bytes = bytes(audio_file.getbuffer())
        elif hasattr(audio_file, "getvalue"):
            audio_bytes = audio_file.getvalue()
        elif hasattr(audio_file, "read"):
            audio_bytes = audio_file.read()
        if hasattr(audio_file, "seek"):
            audio_file.seek(0)

        if not isinstance(audio_bytes, (bytes, bytearray)) or not audio_bytes:
            return None, "Voice prompt could not be read. Please record again or upload a WAV file."

        with tempfile.NamedTemporaryFile(delete=False, suffix=".wav") as temp_audio:
            temp_audio.write(audio_bytes)
            temp_audio_path = temp_audio.name

        escaped_audio_path = temp_audio_path.replace("'", "''")
        powershell_script = f"""
Add-Type -AssemblyName System.Speech
$recognizer = New-Object System.Speech.Recognition.SpeechRecognitionEngine
$recognizer.LoadGrammar((New-Object System.Speech.Recognition.DictationGrammar))
$recognizer.SetInputToWaveFile('{escaped_audio_path}')
$transcriptParts = New-Object System.Collections.Generic.List[string]
while ($true) {{
    $result = $recognizer.Recognize()
    if ($null -eq $result) {{ break }}
    if ($result.Text) {{ [void]$transcriptParts.Add($result.Text) }}
}}
[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
($transcriptParts -join ' ').Trim()
"""
        completed = subprocess.run(
            ["powershell", "-NoProfile", "-Command", powershell_script],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=90,
            check=False
        )
    except subprocess.TimeoutExpired:
        return None, "Voice transcription timed out. Please try a shorter recording."
    except (AttributeError, TypeError, ValueError, OSError, RuntimeError):
        return None, "Voice prompt could not be read. Please record again or upload a WAV file."
    finally:
        if temp_audio_path and os.path.exists(temp_audio_path):
            os.remove(temp_audio_path)

    if completed.returncode != 0:
        error_text = (completed.stderr or completed.stdout or "").strip()
        return None, f"Voice transcription failed: {error_text or 'Local recognizer unavailable.'}"

    transcript = (completed.stdout or "").strip()
    if not transcript:
        return None, "No speech was detected in the recording."

    return transcript, None


def prepare_english_voice_prompt(transcript_text):
    source_text = str(transcript_text or "").strip()
    if not source_text:
        return None, "No speech was detected in the recording."

    translation_prompt = f"""
You are a translation engine.
Convert the provided text to concise, natural English.
If the text is already English, return it unchanged.
Return JSON only using this exact shape:
{{
  "english_text": "translated English text",
  "source_language": "detected language name",
  "translated": true
}}

Text:
{source_text}
"""

    translation_response = ollama_chat(translation_prompt)
    translation_response_text = str(translation_response or "").strip()

    if translation_response_text.startswith("⚠️"):
        return (
            source_text,
            "Voice prompt added to the text box. Translation to English was unavailable, so the original transcript was used. You can edit it before submitting."
        )

    parsed_translation = extract_json_object(translation_response_text)
    if isinstance(parsed_translation, dict):
        english_text = str(parsed_translation.get("english_text", "")).strip()
        detected_language = str(parsed_translation.get("source_language", "")).strip()
        was_translated = bool(parsed_translation.get("translated", False))
        if english_text:
            if was_translated and detected_language and detected_language.lower() not in {"english", "en"}:
                return (
                    english_text,
                    f"Voice prompt translated from {detected_language} to English and added to the text box. You can edit it before submitting."
                )
            return (
                english_text,
                "Voice prompt added to the text box in English. You can edit it before submitting."
            )

    if translation_response_text:
        return (
            translation_response_text,
            "Voice prompt added to the text box in English. You can edit it before submitting."
        )

    return (
        source_text,
        "Voice prompt added to the text box. Translation to English was unavailable, so the original transcript was used. You can edit it before submitting."
    )


def clear_copilot_prompt_inputs(page_name):
    prompt_keys = [
        f"copilot_prompt_text_{page_name}",
        f"copilot_voice_status_{page_name}",
        f"copilot_attachment_{page_name}",
        f"copilot_voice_{page_name}",
        f"copilot_voice_upload_{page_name}",
        f"dp_prompt_stage_{page_name}"
    ]
    for key in prompt_keys:
        if key in st.session_state:
            del st.session_state[key]


def set_nested_value(container, path, value):
    target = container
    for key in path[:-1]:
        target = target[key]
    target[path[-1]] = value


def normalize_column_lookup_key(value):
    return re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())


def resolve_copilot_column_request(requested_value, available_columns):
    requested_text = str(requested_value or "").strip()
    available_columns = coerce_iterable_to_list(available_columns)
    if not requested_text or not available_columns:
        return {
            "resolved_column": None,
            "needs_confirmation": False,
            "options": [],
            "question": ""
        }

    if requested_text in available_columns:
        return {
            "resolved_column": requested_text,
            "needs_confirmation": False,
            "options": [requested_text],
            "question": ""
        }

    requested_lower = requested_text.lower()
    exact_case_matches = [column for column in available_columns if str(column).lower() == requested_lower]
    if exact_case_matches:
        return {
            "resolved_column": exact_case_matches[0],
            "needs_confirmation": False,
            "options": exact_case_matches,
            "question": ""
        }

    normalized_requested = normalize_column_lookup_key(requested_text)
    normalized_matches = [
        column for column in available_columns
        if normalize_column_lookup_key(column) == normalized_requested
    ]
    if normalized_matches:
        return {
            "resolved_column": normalized_matches[0],
            "needs_confirmation": False,
            "options": normalized_matches,
            "question": ""
        }

    contains_matches = [
        column for column in available_columns
        if requested_lower in str(column).lower() or str(column).lower() in requested_lower
    ]
    unique_contains_matches = list(dict.fromkeys(contains_matches))
    if len(unique_contains_matches) == 1:
        return {
            "resolved_column": unique_contains_matches[0],
            "needs_confirmation": False,
            "options": unique_contains_matches,
            "question": ""
        }
    if len(unique_contains_matches) > 1:
        return {
            "resolved_column": None,
            "needs_confirmation": True,
            "options": unique_contains_matches[:5],
            "question": f'I found multiple similar columns for "{requested_text}". Please confirm the correct column.'
        }

    request_tokens = [token for token in re.split(r"[^a-z0-9]+", requested_lower) if token]
    scored_matches = []
    for column in available_columns:
        column_tokens = [token for token in re.split(r"[^a-z0-9]+", str(column).lower()) if token]
        score = sum(1 for token in request_tokens if token in column_tokens)
        if score > 0:
            scored_matches.append((score, column))

    scored_matches.sort(key=lambda item: (-item[0], str(item[1]).lower()))
    candidate_columns = []
    for _, column in scored_matches:
        if column not in candidate_columns:
            candidate_columns.append(column)

    if len(candidate_columns) == 1:
        return {
            "resolved_column": candidate_columns[0],
            "needs_confirmation": False,
            "options": candidate_columns,
            "question": ""
        }
    if candidate_columns:
        return {
            "resolved_column": None,
            "needs_confirmation": True,
            "options": candidate_columns[:5],
            "question": f'I found multiple possible columns for "{requested_text}". Please confirm the one to use.'
        }

    return {
        "resolved_column": None,
        "needs_confirmation": False,
        "options": [],
        "question": ""
    }


def collect_copilot_column_requests(page_key, config_updates):
    requests = []

    def add_list(field_name, values, label_prefix):
        for index, value in enumerate(values or []):
            if isinstance(value, str) and value.strip():
                requests.append({
                    "path": ["config_updates", field_name, index],
                    "requested": value,
                    "label": f"{label_prefix} #{index + 1}"
                })

    def add_scalar(field_name, value, label_text):
        if isinstance(value, str) and value.strip():
            requests.append({
                "path": ["config_updates", field_name],
                "requested": value,
                "label": label_text
            })

    if page_key == "profile":
        add_list("profile_cols", config_updates.get("profile_cols", []), "Profile column")
    elif page_key == "missing":
        add_list("missing_key_identifiers", config_updates.get("missing_key_identifiers", []), "Missing key column")
        add_list("missing_cols", config_updates.get("missing_cols", []), "Missing target column")
    elif page_key == "duplicate":
        add_list("duplicate_key_cols", config_updates.get("duplicate_key_cols", []), "Duplicate key column")
        add_list("duplicate_check_cols", config_updates.get("duplicate_check_cols", []), "Duplicate check column")
    elif page_key == "invalid_format":
        add_list("format_key_cols", config_updates.get("format_key_cols", []), "Format key column")
        add_list("invalid_cols", config_updates.get("invalid_cols", []), "Format check column")
    elif page_key == "outlier":
        add_list("outlier_key_cols", config_updates.get("outlier_key_cols", []), "Outlier key column")
        add_list("outlier_category_cols", config_updates.get("outlier_category_cols", []), "Outlier category column")
        add_list("outlier_cols", config_updates.get("outlier_cols", []), "Outlier numeric column")
    elif page_key == "logical":
        add_list("logical_display_cols", config_updates.get("logical_display_cols", []), "Logical display column")
        add_scalar("single_col", config_updates.get("single_col"), "Single validation column")
        add_list("logic_cols", config_updates.get("logic_cols", []), "Logical calculation column")
        add_scalar("compare_col", config_updates.get("compare_col"), "Logical compare column")
        for index, condition in enumerate(config_updates.get("bool_conditions_list", [])):
            if isinstance(condition, dict):
                condition_column = condition.get("column")
                if isinstance(condition_column, str) and condition_column.strip():
                    requests.append({
                        "path": ["config_updates", "bool_conditions_list", index, "column"],
                        "requested": condition_column,
                        "label": f"Boolean condition column #{index + 1}"
                    })
    elif page_key == "comparison":
        add_list("compare_by_cols", config_updates.get("compare_by_cols", []), "Comparison key column")
        add_list("compare_cols", config_updates.get("compare_cols", []), "Comparison value column")

    return requests


def build_copilot_confirmation_request(page_name, payload, available_columns):
    confirmation_payload = payload.get("confirmation", {})
    if payload.get("needs_confirmation") or confirmation_payload.get("options"):
        return {
            "type": confirmation_payload.get("type", "tool_selection"),
            "question": confirmation_payload.get("question", "Please confirm the requested selection."),
            "options": confirmation_payload.get("options", []),
            "payload": copy.deepcopy(payload)
        }

    page_key = PAGE_NAME_TO_KEY.get(page_name)
    if not page_key or page_key in ["data_preparation", "insights"]:
        return None

    config_updates = payload.get("config_updates", {})
    for request in collect_copilot_column_requests(page_key, config_updates):
        resolution = resolve_copilot_column_request(request.get("requested"), available_columns)
        if resolution.get("needs_confirmation"):
            return {
                "type": "column_selection",
                "question": f'{request.get("label", "Column")} "{request.get("requested")}" matches multiple columns. Please confirm the correct one.',
                "options": resolution.get("options", []),
                "payload": copy.deepcopy(payload),
                "path": request.get("path")
            }
        resolved_column = resolution.get("resolved_column")
        if resolved_column and resolved_column != request.get("requested"):
            set_nested_value(payload, request.get("path"), resolved_column)

    return None


def resolve_data_prep_tool_request(requested_tool):
    requested_tool = str(requested_tool or "").strip()
    if not requested_tool:
        return {
            "resolved_tool": None,
            "needs_confirmation": False,
            "options": [],
            "question": ""
        }

    if requested_tool in DATA_PREP_TOOL_NAMES:
        return {
            "resolved_tool": requested_tool,
            "needs_confirmation": False,
            "options": [requested_tool],
            "question": ""
        }

    requested_lower = requested_tool.lower()
    if requested_lower in DATA_PREP_TOOL_SYNONYMS:
        resolved_tool = DATA_PREP_TOOL_SYNONYMS[requested_lower]
        return {
            "resolved_tool": resolved_tool,
            "needs_confirmation": False,
            "options": [resolved_tool],
            "question": ""
        }

    exact_matches = [tool_name for tool_name in DATA_PREP_TOOL_NAMES if tool_name.lower() == requested_lower]
    if exact_matches:
        return {
            "resolved_tool": exact_matches[0],
            "needs_confirmation": False,
            "options": exact_matches,
            "question": ""
        }

    contains_matches = [tool_name for tool_name in DATA_PREP_TOOL_NAMES if
                        requested_lower and requested_lower in tool_name.lower()]
    if len(contains_matches) == 1:
        return {
            "resolved_tool": contains_matches[0],
            "needs_confirmation": False,
            "options": contains_matches,
            "question": ""
        }

    request_tokens = [token for token in re.split(r"[^a-z0-9]+", requested_lower) if token and token != "tool"]
    token_matches = []
    for tool_name in DATA_PREP_TOOL_NAMES:
        tool_tokens = [token for token in re.split(r"[^a-z0-9]+", tool_name.lower()) if token and token != "tool"]
        score = sum(1 for token in request_tokens if token in tool_tokens)
        if score > 0:
            token_matches.append((score, tool_name))

    token_matches.sort(key=lambda item: (-item[0], item[1]))
    candidate_tools = []
    for _, tool_name in token_matches:
        if tool_name not in candidate_tools:
            candidate_tools.append(tool_name)

    if len(candidate_tools) == 1:
        return {
            "resolved_tool": candidate_tools[0],
            "needs_confirmation": False,
            "options": candidate_tools,
            "question": ""
        }

    if candidate_tools:
        candidate_list = candidate_tools[:3]
        return {
            "resolved_tool": None,
            "needs_confirmation": True,
            "options": candidate_list,
            "question": f'I found multiple possible tools for "{requested_tool}". Please confirm which one to use.'
        }

    return {
        "resolved_tool": None,
        "needs_confirmation": True,
        "options": DATA_PREP_TOOL_NAMES[:5],
        "question": f'I could not confidently map "{requested_tool}" to a tool. Please choose the correct tool to continue.'
    }


def resolve_data_prep_tool_name(requested_tool):
    return resolve_data_prep_tool_request(requested_tool).get("resolved_tool")


def build_filter_expression(raw_expression, available_columns):
    expression_text = str(raw_expression or "").strip()
    if not expression_text:
        return ""

    if "[" in expression_text and "]" in expression_text:
        return expression_text

    simple_match = re.match(r"^\s*([A-Za-z0-9_ ]+?)\s*(==|=|!=|>=|<=|>|<)\s*(.+?)\s*$", expression_text)
    if not simple_match:
        return expression_text

    raw_column, operator, raw_value = simple_match.groups()
    normalized_column = normalize_scalar_column(raw_column.strip(), available_columns, fallback=raw_column.strip())
    operator = "==" if operator == "=" else operator
    value_text = raw_value.strip()

    if re.match(r"^-?\d+(\.\d+)?$", value_text):
        normalized_value = value_text
    elif value_text.lower() in ["true", "false", "none", "null"]:
        normalized_value = value_text.lower().replace("null", "None")
    elif (value_text.startswith("'") and value_text.endswith("'")) or (
            value_text.startswith('"') and value_text.endswith('"')):
        normalized_value = value_text
    else:
        normalized_value = f'"{value_text}"'

    return normalize_frontend_condition_syntax(f"[{normalized_column}] {operator} {normalized_value}",
                                               logical_lowercase=True)


def normalize_frontend_condition_syntax(expression_text, logical_lowercase=True):
    """Convert frontend-style conditions to Python-compatible syntax."""
    normalized_expr = str(expression_text or "").strip()
    if not normalized_expr:
        return ""

    normalized_expr = re.sub(r'<>', '!=', normalized_expr)
    normalized_expr = re.sub(r'(?<![=!<>])=(?!=)', '==', normalized_expr)

    if logical_lowercase:
        normalized_expr = re.sub(r'\bAND\b', 'and', normalized_expr, flags=re.IGNORECASE)
        normalized_expr = re.sub(r'\bOR\b', 'or', normalized_expr, flags=re.IGNORECASE)
        normalized_expr = re.sub(r'\bNOT\b', 'not', normalized_expr, flags=re.IGNORECASE)
    else:
        normalized_expr = re.sub(r'\bAND\b', 'AND', normalized_expr, flags=re.IGNORECASE)
        normalized_expr = re.sub(r'\bOR\b', 'OR', normalized_expr, flags=re.IGNORECASE)
        normalized_expr = re.sub(r'\bNOT\b', 'NOT', normalized_expr, flags=re.IGNORECASE)

    normalized_expr = re.sub(r'\bNULL\b', 'None', normalized_expr, flags=re.IGNORECASE)
    normalized_expr = re.sub(r'\bTRUE\b', 'True', normalized_expr, flags=re.IGNORECASE)
    normalized_expr = re.sub(r'\bFALSE\b', 'False', normalized_expr, flags=re.IGNORECASE)
    return normalized_expr


def _formula_to_series(value):
    if isinstance(value, pd.Series):
        return value
    if isinstance(value, pd.Index):
        return pd.Series(value)
    if isinstance(value, (list, tuple, np.ndarray)):
        return pd.Series(value)
    return pd.Series([value])


def _formula_parse_datetime(value):
    return pd.to_datetime(value, errors="coerce")


def _formula_align_binary_args(left, right):
    left_is_series = isinstance(left, pd.Series)
    right_is_series = isinstance(right, pd.Series)

    if left_is_series and right_is_series:
        return left, right
    if left_is_series:
        return left, pd.Series([right] * len(left), index=left.index)
    if right_is_series:
        return pd.Series([left] * len(right), index=right.index), right
    return left, right


def _formula_datetime_diff(left, right, unit="days"):
    left, right = _formula_align_binary_args(left, right)
    left_dt = pd.to_datetime(left, errors="coerce")
    right_dt = pd.to_datetime(right, errors="coerce")
    delta = left_dt - right_dt
    unit_text = str(unit or "days").strip().lower()

    if not isinstance(delta, pd.Series):
        if unit_text in ["day", "days", "d"]:
            return delta.total_seconds() / 86400.0
        if unit_text in ["hour", "hours", "h"]:
            return delta.total_seconds() / 3600.0
        if unit_text in ["minute", "minutes", "min", "m"]:
            return delta.total_seconds() / 60.0
        if unit_text in ["second", "seconds", "sec", "s"]:
            return delta.total_seconds()
        if unit_text in ["week", "weeks", "w"]:
            return delta.total_seconds() / (86400.0 * 7.0)
        if unit_text in ["month", "months", "mon"]:
            return (left_dt.year - right_dt.year) * 12 + (left_dt.month - right_dt.month)
        if unit_text in ["year", "years", "y"]:
            return left_dt.year - right_dt.year
        return delta.total_seconds() / 86400.0

    if unit_text in ["day", "days", "d"]:
        return delta.dt.total_seconds() / 86400.0
    if unit_text in ["hour", "hours", "h"]:
        return delta.dt.total_seconds() / 3600.0
    if unit_text in ["minute", "minutes", "min", "m"]:
        return delta.dt.total_seconds() / 60.0
    if unit_text in ["second", "seconds", "sec", "s"]:
        return delta.dt.total_seconds()
    if unit_text in ["week", "weeks", "w"]:
        return delta.dt.total_seconds() / (86400.0 * 7.0)
    if unit_text in ["month", "months", "mon"]:
        return (left_dt.dt.year - right_dt.dt.year) * 12 + (left_dt.dt.month - right_dt.dt.month)
    if unit_text in ["year", "years", "y"]:
        return left_dt.dt.year - right_dt.dt.year

    return delta.dt.total_seconds() / 86400.0


def _formula_datetime_add(value, amount, unit="days"):
    dt_value = pd.to_datetime(value, errors="coerce")
    if isinstance(dt_value, pd.Series):
        amt_series = amount if isinstance(amount, pd.Series) else pd.Series([amount] * len(dt_value),
                                                                            index=dt_value.index)
    else:
        amt_series = amount
    unit_text = str(unit or "days").strip().lower()

    if not isinstance(dt_value, pd.Series):
        if unit_text in ["day", "days", "d"]:
            return dt_value + pd.to_timedelta(amt_series, unit="D")
        if unit_text in ["hour", "hours", "h"]:
            return dt_value + pd.to_timedelta(amt_series, unit="h")
        if unit_text in ["minute", "minutes", "min", "m"]:
            return dt_value + pd.to_timedelta(amt_series, unit="m")
        if unit_text in ["second", "seconds", "sec", "s"]:
            return dt_value + pd.to_timedelta(amt_series, unit="s")
        if unit_text in ["week", "weeks", "w"]:
            return dt_value + pd.to_timedelta(amt_series * 7, unit="D")
        if unit_text in ["month", "months", "mon"]:
            return dt_value + pd.to_timedelta(amt_series * 30, unit="D")
        if unit_text in ["year", "years", "y"]:
            return dt_value + pd.to_timedelta(amt_series * 365, unit="D")
        return dt_value + pd.to_timedelta(amt_series, unit="D")

    if unit_text in ["day", "days", "d"]:
        return dt_value + pd.to_timedelta(amt_series, unit="D")
    if unit_text in ["hour", "hours", "h"]:
        return dt_value + pd.to_timedelta(amt_series, unit="h")
    if unit_text in ["minute", "minutes", "min", "m"]:
        return dt_value + pd.to_timedelta(amt_series, unit="m")
    if unit_text in ["second", "seconds", "sec", "s"]:
        return dt_value + pd.to_timedelta(amt_series, unit="s")
    if unit_text in ["week", "weeks", "w"]:
        return dt_value + pd.to_timedelta(amt_series * 7, unit="D")
    if unit_text in ["month", "months", "mon"]:
        return dt_value + pd.to_timedelta(amt_series * 30, unit="D")
    if unit_text in ["year", "years", "y"]:
        return dt_value + pd.to_timedelta(amt_series * 365, unit="D")
    return dt_value + pd.to_timedelta(amt_series, unit="D")


def _formula_datetime_format(value, fmt="%Y-%m-%d"):
    parsed = pd.to_datetime(value, errors="coerce")
    if isinstance(parsed, pd.Series):
        return parsed.dt.strftime(fmt)
    return parsed.strftime(fmt) if pd.notna(parsed) else None


def _formula_replace(value, old, new):
    return pd.Series(value).astype(str).str.replace(str(old), str(new), regex=False)


def _formula_contains(value, needle):
    return pd.Series(value).astype(str).str.contains(str(needle), case=False, na=False)


def _formula_startswith(value, prefix):
    return pd.Series(value).astype(str).str.startswith(str(prefix), na=False)


def _formula_endswith(value, suffix):
    return pd.Series(value).astype(str).str.endswith(str(suffix), na=False)


def _formula_isnull(value):
    return pd.isna(value)


def _formula_isempty(value):
    if isinstance(value, pd.Series):
        return value.isna() | (value.astype(str).str.len() == 0)
    return value is None or str(value).strip() == ""


def _formula_nullif(value, match_value):
    if isinstance(value, pd.Series) or isinstance(match_value, pd.Series):
        left, right = _formula_align_binary_args(value, match_value)
        left_series = left if isinstance(left, pd.Series) else pd.Series([left] * len(right), index=right.index)
        return left_series.where(left_series != right, np.nan)
    return np.nan if value == match_value else value


def _formula_to_number(value):
    return pd.to_numeric(value, errors="coerce")


def _formula_to_int(value):
    converted = pd.to_numeric(value, errors="coerce")
    if isinstance(converted, pd.Series):
        return converted.astype("Int64")
    return int(converted) if pd.notna(converted) else None


def _formula_to_float(value):
    converted = pd.to_numeric(value, errors="coerce")
    if isinstance(converted, pd.Series):
        return converted.astype(float)
    return float(converted) if pd.notna(converted) else np.nan


def _formula_year(value):
    return pd.to_datetime(value, errors="coerce").dt.year


def _formula_month(value):
    return pd.to_datetime(value, errors="coerce").dt.month


def _formula_day(value):
    return pd.to_datetime(value, errors="coerce").dt.day


def _formula_hour(value):
    return pd.to_datetime(value, errors="coerce").dt.hour


def _formula_minute(value):
    return pd.to_datetime(value, errors="coerce").dt.minute


def _formula_second(value):
    return pd.to_datetime(value, errors="coerce").dt.second


def normalize_formula_syntax(expr):
    expr_text = str(expr or "").strip()
    if not expr_text:
        return ""

    replacements = [
        (r"\bDATEDIFF\s*\(", "DateTimeDiff("),
        (r"\bDATEDATE\s*\(", "DateTimeDiff("),
        (r"\bDATEADD\s*\(", "DateTimeAdd("),
        (r"\bDATETIMEDIFF\s*\(", "DateTimeDiff("),
        (r"\bDATETIMEADD\s*\(", "DateTimeAdd("),
        (r"\bDATEPARSE\s*\(", "DateTimeParse("),
        (r"\bDATETIMEPARSE\s*\(", "DateTimeParse("),
        (r"\bDATEFORMAT\s*\(", "DateTimeFormat("),
        (r"\bDATETIMEFORMAT\s*\(", "DateTimeFormat("),
        (r"\bISNULL\s*\(", "IsNull("),
        (r"\bISEMPTY\s*\(", "IsEmpty("),
        (r"\bTOSTRING\s*\(", "ToString("),
        (r"\bTONUMBER\s*\(", "ToNumber("),
        (r"\bTOINT\s*\(", "ToInt("),
        (r"\bTOFLOAT\s*\(", "ToFloat("),
    ]
    for pattern, replacement in replacements:
        expr_text = re.sub(pattern, replacement, expr_text, flags=re.IGNORECASE)
    return expr_text


def build_data_prep_step_config(tool_name, action_payload, dataset_registry, available_columns):
    dataset_id = action_payload.get("dataset_id")
    if dataset_id not in dataset_registry:
        dataset_id = "home" if "home" in dataset_registry else (
            list(dataset_registry.keys())[0] if dataset_registry else "home")

    config = {"dataset_id": dataset_id}

    if tool_name == "Filter Tool":
        expression = action_payload.get("expression") or action_payload.get("condition") or ""
        config["filter_mode"] = "Expression"
        config["expression"] = build_filter_expression(expression, available_columns)

    return config


def infer_data_prep_payload_from_prompt(user_prompt, dataset_registry, available_columns):
    prompt_text = str(user_prompt or "").strip()
    if not prompt_text:
        return None

    prompt_lower = prompt_text.lower()

    # ----------------------------------------------------------------
    # DELETE / REMOVE intent detection — must run BEFORE tool detection
    # so "delete filter tool" is treated as a delete, not an add.
    # ----------------------------------------------------------------
    _DELETE_WORDS = [
        "delete", "remove", "drop", "erase", "wipe", "discard",
        "clear step", "get rid of", "take out", "eliminate",
    ]
    _has_delete_intent = any(kw in prompt_lower for kw in _DELETE_WORDS)

    if _has_delete_intent:
        # Pattern 1: explicit step number — "delete step 3", "remove step 2"
        step_num_match = re.search(r"\bstep\s*(\d+)\b", prompt_lower)
        # Pattern 2: tool name present alongside delete word
        tool_ref, _ = detect_primary_tool_from_prompt(prompt_lower)

        target_step = int(step_num_match.group(1)) if step_num_match else None
        summary_parts = []
        if target_step:
            summary_parts.append(f"step {target_step}")
        if tool_ref:
            summary_parts.append(tool_ref)

        return {
            "dataset_id": "home",
            "workflow_actions": [{
                "action": "delete_tool",
                "step": target_step,  # 1-based; None = use tool name
                "tool": tool_ref,  # resolved tool name, or None
            }],
            "summary": f"Remove {' / '.join(summary_parts) or 'step'} from canvas."
        }

    # ----------------------------------------------------------------
    # MOVE UP / DOWN intent detection — before tool/add detection
    # Patterns: "move filter tool up", "move step 2 down 3",
    #           "move sort tool above aggregate tool",
    #           "move step 3 before step 5", "move formula tool to position 1"
    # ----------------------------------------------------------------
    _MOVE_WORDS = ["move", "reorder", "shift", "push", "bring", "send"]
    _has_move_intent = any(kw in prompt_lower for kw in _MOVE_WORDS) and (
        any(kw in prompt_lower for kw in ["up", "down", "above", "below", "before", "after", "position"])
    )

    if _has_move_intent:
        # Determine direction
        if any(kw in prompt_lower for kw in ["up", "above", "before", "top", "higher"]):
            direction = "up"
        else:
            direction = "down"

        # Number of positions to move (default 1)
        steps_match = re.search(r"\b(\d+)\s*(?:step|position|place|spot)s?\b", prompt_lower)
        # Also catch trailing digit: "move up 2", "move down 3"
        bare_num_match = re.search(
            r"\b(?:up|down)\s+(\d+)\b|\b(\d+)\s+(?:up|down)\b", prompt_lower
        )
        n_positions = 1
        if steps_match:
            n_positions = int(steps_match.group(1))
        elif bare_num_match:
            n_positions = int(bare_num_match.group(1) or bare_num_match.group(2))

        # Source step identification
        step_nums = re.findall(r"\bstep\s*(\d+)\b", prompt_lower)
        source_step = int(step_nums[0]) if step_nums else None
        source_tool, _ = detect_primary_tool_from_prompt(prompt_lower)

        # Target step (for "before/after/above/below <step or tool>")
        target_step = int(step_nums[1]) if len(step_nums) > 1 else None
        target_tool = None
        if any(kw in prompt_lower for kw in ["above", "below", "before", "after"]):
            # Second tool mention is the target
            _all_tools = [t for t in DATA_PREP_TOOL_NAMES if t.lower() in prompt_lower]
            if len(_all_tools) >= 2:
                target_tool = _all_tools[1]
            elif len(_all_tools) == 1 and _all_tools[0] != source_tool:
                target_tool = _all_tools[0]

        # "to position N"
        pos_match = re.search(r"\bto\s+position\s+(\d+)\b", prompt_lower)
        to_position = int(pos_match.group(1)) if pos_match else None

        summary_src = f"step {source_step}" if source_step else (source_tool or "step")
        return {
            "dataset_id": "home",
            "workflow_actions": [{
                "action": "move_step",
                "step": source_step,  # 1-based source step number, or None
                "tool": source_tool,
                "direction": direction,
                "n_positions": n_positions,
                "target_step": target_step,  # 1-based target, or None
                "target_tool": target_tool,
                "to_position": to_position,  # absolute 1-based target position, or None
            }],
            "summary": f"Move {summary_src} {direction}."
        }
    # ----------------------------------------------------------------

    # Use the unified keyword-aware, position-based detector so that when a
    # prompt mentions multiple tools (e.g. "Add Formula Tool on output of
    # Filter Tool"), the one stated earliest / most explicitly wins.
    requested_tool, _match_type = detect_primary_tool_from_prompt(prompt_lower)

    # Fallback: capture any "<word(s)> Tool" pattern not already matched
    if not requested_tool:
        tool_pattern_match = re.search(r"([a-zA-Z][a-zA-Z0-9_ ]+?)\s+tool\b", prompt_text, re.IGNORECASE)
        if tool_pattern_match:
            requested_tool = tool_pattern_match.group(1).strip() + " Tool"

    if requested_tool:
        resolution = resolve_data_prep_tool_request(requested_tool)
        if resolution.get("needs_confirmation"):
            return {
                "dataset_id": "home" if "home" in dataset_registry else (
                    list(dataset_registry.keys())[0] if dataset_registry else "home"),
                "workflow_actions": [],
                "needs_confirmation": True,
                "summary": "Waiting for tool confirmation.",
                "confirmation": {
                    "type": "tool_selection",
                    "requested_tool": requested_tool,
                    "question": resolution.get("question"),
                    "options": resolution.get("options", [])
                }
            }
        requested_tool = resolution.get("resolved_tool")

    if not requested_tool:
        return None

    # Only ask for confirmation if "Filter Tool" was resolved exclusively via a
    # keyword/synonym match AND the primary action word (filter/where/condition)
    # is absent — meaning the user likely referenced it as context, not as the
    # target tool.  When "filter tool" is the earliest tool name in the prompt
    # (_match_type == "tool_name" and it genuinely leads), we trust the match.
    if (
            requested_tool == "Filter Tool"
            and _match_type == "keyword"
            and not re.search(r"\b(filter|where|condition)\b", prompt_lower)
    ):
        return {
            "dataset_id": "home" if "home" in dataset_registry else (
                list(dataset_registry.keys())[0] if dataset_registry else "home"),
            "workflow_actions": [],
            "needs_confirmation": True,
            "summary": "Waiting for tool confirmation.",
            "confirmation": {
                "type": "tool_selection",
                "requested_tool": requested_tool,
                "question": "I need confirmation before using Filter Tool. Please choose the intended tool.",
                "options": ["Select Tool", "Aggregate Tool", "Formula Tool", "Filter Tool"]
            }
        }

    dataset_id = "home" if "home" in dataset_registry else (
        list(dataset_registry.keys())[0] if dataset_registry else "home")
    for candidate_id, meta in dataset_registry.items():
        label_text = str(meta.get("label", "")).lower()
        if candidate_id.lower() in prompt_lower or label_text in prompt_lower:
            dataset_id = candidate_id
            break

    inferred_action = {
        "action": "add_tool",
        "tool": requested_tool,
        "dataset_id": dataset_id,
        "position": "append"
    }

    if requested_tool == "Filter Tool":
        condition_match = re.search(
            r"(?:condition|apply|where|filter(?: by| with)?)(.*)$",
            prompt_text,
            re.IGNORECASE
        )
        condition_text = condition_match.group(1).strip(" .,:") if condition_match else prompt_text
        simple_condition = build_filter_expression(condition_text, available_columns)
        if simple_condition:
            inferred_action["expression"] = simple_condition

    return {
        "dataset_id": dataset_id,
        "workflow_actions": [inferred_action],
        "summary": f"Prepared {requested_tool} in the workflow."
    }


def apply_data_prep_workflow_actions(payload, dataset_registry, available_columns):
    confirmation = payload.get("confirmation", {})
    if payload.get("needs_confirmation") or confirmation.get("options"):
        question_text = confirmation.get(
            "question") or "Please confirm the Data Preparation tool before Copilot continues."
        return False, question_text

    workflow_actions = payload.get("workflow_actions") or payload.get("config_updates", {}).get(
        "workflow_actions") or []
    if not workflow_actions and payload.get("config_updates", {}).get("tool_name"):
        workflow_actions = [{
            "action": "add_tool",
            "tool": payload["config_updates"].get("tool_name"),
            "dataset_id": payload.get("dataset_id"),
            "expression": payload["config_updates"].get("expression") or payload["config_updates"].get("condition", "")
        }]

    if not workflow_actions:
        return False, "No workflow action was generated for Data Preparation."

    if "dp_canvas" not in st.session_state:
        st.session_state.dp_canvas = []
    if "dp_selected_step_index" not in st.session_state:
        st.session_state.dp_selected_step_index = None

    workflow_signature = json.dumps(workflow_actions, sort_keys=True, default=str)
    if workflow_signature and workflow_signature == st.session_state.get("dp_last_copilot_workflow_signature"):
        return False, "This workflow action was already applied."

    def resolve_step_index(step_ref):
        if step_ref is None:
            return None
        if isinstance(step_ref, int):
            candidate_idx = step_ref - 1 if step_ref > 0 else 0
            return candidate_idx if 0 <= candidate_idx < len(st.session_state.dp_canvas) else None

        step_text = str(step_ref).strip().lower()
        if not step_text:
            return None

        match = re.search(r"(\d+)", step_text)
        if match:
            candidate_idx = int(match.group(1)) - 1
            if 0 <= candidate_idx < len(st.session_state.dp_canvas):
                return candidate_idx

        for idx, canvas_step in enumerate(st.session_state.dp_canvas):
            if str(canvas_step.get("tool", "")).strip().lower() == step_text:
                return idx
        return None

    applied_actions = []
    for action in workflow_actions:
        action_name = str(action.get("action", "add_tool")).strip().lower()

        if action_name == "clear_workflow":
            st.session_state.dp_canvas = []
            st.session_state.active_insert_index = None
            st.session_state.dp_selected_step_index = None
            applied_actions.append("workflow cleared")
            continue

        if action_name in ["connect_tools", "connect_steps", "link_tools"]:
            source_idx = resolve_step_index(
                action.get("from_step") or action.get("source_step") or action.get("from")
            )
            target_idx = resolve_step_index(
                action.get("to_step") or action.get("target_step") or action.get("to")
            )
            if source_idx is None or target_idx is None:
                continue
            if source_idx == target_idx:
                continue

            target_step = st.session_state.dp_canvas[target_idx]
            target_step.setdefault("config", {})
            target_step["config"]["dataset_id"] = f"step_index_{source_idx}"
            target_step["connection_string"] = str(action.get("connection_string", "")).strip()
            st.session_state.dp_selected_step_index = target_idx
            applied_actions.append(
                f"connected Step {source_idx + 1} -> Step {target_idx + 1}"
            )
            continue

        if action_name in ["delete_tool", "remove_tool", "delete_step", "remove_step"]:
            target_idx = None

            # Priority 1: explicit step number ("step": 3 → index 2)
            step_ref = action.get("step") or action.get("step_number")
            if step_ref is not None:
                target_idx = resolve_step_index(step_ref)

            # Priority 2: tool name match — remove last occurrence
            if target_idx is None:
                tool_ref = action.get("tool")
                if tool_ref:
                    resolved_t = resolve_data_prep_tool_name(tool_ref)
                    if resolved_t:
                        for idx in reversed(range(len(st.session_state.dp_canvas))):
                            if st.session_state.dp_canvas[idx].get("tool") == resolved_t:
                                target_idx = idx
                                break

            if target_idx is not None and 0 <= target_idx < len(st.session_state.dp_canvas):
                deleted_tool = st.session_state.dp_canvas[target_idx].get("tool", "Unknown")
                st.session_state.dp_canvas.pop(target_idx)

                # Re-index dp_edges, removing any edge that referenced this step
                new_edges = []
                for edge in st.session_state.get("dp_edges", []):
                    f, t = edge.get("from_idx", -1), edge.get("to_idx", -1)
                    if f == target_idx or t == target_idx:
                        continue  # drop edge touching the deleted step
                    new_edge = dict(edge)
                    if new_edge["from_idx"] > target_idx:
                        new_edge["from_idx"] -= 1
                    if new_edge["to_idx"] > target_idx:
                        new_edge["to_idx"] -= 1
                    new_edges.append(new_edge)
                st.session_state.dp_edges = new_edges

                # Clear selection if we just deleted the selected step
                if st.session_state.get("dp_selected_step_index") == target_idx:
                    st.session_state.dp_selected_step_index = None
                elif (st.session_state.get("dp_selected_step_index") or 0) > target_idx:
                    st.session_state.dp_selected_step_index -= 1

                applied_actions.append(f"deleted Step {target_idx + 1} ({deleted_tool})")
            else:
                applied_actions.append("could not find matching step to delete")
            continue

        if action_name in ["move_step", "reorder_step", "move_tool"]:
            canvas = st.session_state.dp_canvas
            n = len(canvas)
            if n < 2:
                applied_actions.append("canvas has fewer than 2 steps — nothing to move")
                continue

            # ── Resolve source index ────────────────────────────────────
            src_idx = resolve_step_index(action.get("step"))
            if src_idx is None and action.get("tool"):
                resolved_src_tool = resolve_data_prep_tool_name(action.get("tool"))
                if resolved_src_tool:
                    for _i, _s in enumerate(canvas):
                        if _s.get("tool") == resolved_src_tool:
                            src_idx = _i
                            break
            if src_idx is None:
                applied_actions.append("could not identify source step to move")
                continue

            # ── Resolve destination index ───────────────────────────────
            dst_idx = None

            # Absolute position override: "to position N" (1-based)
            to_pos = action.get("to_position")
            if to_pos is not None:
                dst_idx = max(0, min(int(to_pos) - 1, n - 1))

            # Relative to another step/tool: "above/before <target>"
            if dst_idx is None and action.get("target_step"):
                dst_ref = resolve_step_index(action["target_step"])
                if dst_ref is not None:
                    relative = action.get("direction", "up")
                    dst_idx = dst_ref if relative in ("up", "above", "before") else dst_ref + 1

            if dst_idx is None and action.get("target_tool"):
                resolved_tgt = resolve_data_prep_tool_name(action["target_tool"])
                if resolved_tgt:
                    for _i, _s in enumerate(canvas):
                        if _s.get("tool") == resolved_tgt:
                            relative = action.get("direction", "up")
                            dst_idx = _i if relative in ("up", "above", "before") else _i + 1
                            break

            # Direction + N positions fallback
            if dst_idx is None:
                direction = str(action.get("direction", "up")).lower()
                n_positions = max(1, int(action.get("n_positions", 1) or 1))
                if direction in ("up", "above", "before"):
                    dst_idx = max(0, src_idx - n_positions)
                else:
                    dst_idx = min(n - 1, src_idx + n_positions)

            dst_idx = max(0, min(dst_idx, n - 1))
            if dst_idx == src_idx:
                applied_actions.append(f"Step {src_idx + 1} is already at that position")
                continue

            # ── Perform the move ───────────────────────────────────────
            step_label = canvas[src_idx].get("tool", f"Step {src_idx + 1}")
            canvas.insert(dst_idx, canvas.pop(src_idx))

            # ── Remap dp_edges ─────────────────────────────────────────
            def _remap_idx_after_move(v, src, dst):
                """Map an old index to its new position after pop(src)+insert(dst)."""
                if v == src:
                    return dst
                if src < dst:
                    # items (src,dst] shifted left
                    if src < v <= dst:
                        return v - 1
                else:
                    # items [dst,src) shifted right
                    if dst <= v < src:
                        return v + 1
                return v

            new_edges = []
            for _e in st.session_state.get("dp_edges", []):
                _ne = dict(_e)
                _ne["from_idx"] = _remap_idx_after_move(_e.get("from_idx", -1), src_idx, dst_idx)
                _ne["to_idx"] = _remap_idx_after_move(_e.get("to_idx", -1), src_idx, dst_idx)
                new_edges.append(_ne)
            st.session_state.dp_edges = new_edges

            # Update selected step pointer
            sel = st.session_state.get("dp_selected_step_index")
            if sel is not None:
                st.session_state.dp_selected_step_index = _remap_idx_after_move(sel, src_idx, dst_idx)

            applied_actions.append(
                f"moved '{step_label}' from position {src_idx + 1} → {dst_idx + 1}"
            )
            continue

        if action_name != "add_tool":
            continue

        resolved_tool_name = resolve_data_prep_tool_name(action.get("tool"))
        if not resolved_tool_name:
            return False, f"Unknown Data Preparation tool: {action.get('tool')}"

        step_config = build_data_prep_step_config(resolved_tool_name, action, dataset_registry, available_columns)
        new_step = {
            "tool": resolved_tool_name,
            "config": step_config,
            "id": f"copilot_{sanitize_dataset_id(resolved_tool_name)}_{time.time_ns()}"
        }

        insert_mode = str(action.get("position", "append")).strip().lower()
        active_idx = st.session_state.get("active_insert_index")
        if insert_mode in ["after_active", "after current"] and active_idx is not None and active_idx < len(
                st.session_state.dp_canvas):
            insert_index = active_idx + 1
            st.session_state.dp_canvas.insert(insert_index, new_step)
        else:
            st.session_state.dp_canvas.append(new_step)
            insert_index = len(st.session_state.dp_canvas) - 1

        st.session_state.active_insert_index = insert_index
        st.session_state.dp_selected_step_index = insert_index

        if resolved_tool_name == "Filter Tool":
            st.session_state[f"filter_tool_ds_{insert_index}"] = step_config.get("dataset_id", "home")
            st.session_state[f"f_canvas_text_widget_{insert_index}"] = step_config.get("expression", "")

        applied_actions.append(f"added {resolved_tool_name}")

    remember_page_runtime(
        "data_preparation",
        {
            "workflow_actions": workflow_actions,
            "canvas_tools": [step.get("tool") for step in st.session_state.get("dp_canvas", [])]
        },
        used_columns=available_columns,
        dataset_id="home"
    )
    st.session_state.dp_last_copilot_workflow_signature = workflow_signature

    return True, ", ".join(applied_actions) if applied_actions else "Workflow updated."


def apply_copilot_page_configuration(page_name, payload, available_columns, dataset_registry):
    page_key = PAGE_NAME_TO_KEY.get(page_name)
    if not page_key:
        return False, "This page is not mapped for Copilot automation."

    config_updates = copy.deepcopy(payload.get("config_updates", {}))
    dataset_id = payload.get("dataset_id")
    applied_changes = []

    if page_key == "data_preparation":
        return apply_data_prep_workflow_actions(payload, dataset_registry, available_columns)

    if dataset_id and dataset_id in dataset_registry:
        st.session_state[f"{page_key}_source"] = dataset_id
        applied_changes.append(f"dataset={dataset_registry[dataset_id]['label']}")
    elif dataset_id:
        available_dataset_ids = list(dataset_registry.keys())
        normalized_dataset_id = normalize_text_choice(dataset_id, available_dataset_ids)
        if normalized_dataset_id in dataset_registry:
            st.session_state[f"{page_key}_source"] = normalized_dataset_id
            dataset_id = normalized_dataset_id
            applied_changes.append(f"dataset={dataset_registry[dataset_id]['label']}")

    if page_key == "profile":
        cols = normalize_column_list(
            config_updates.get("profile_cols", available_columns),
            available_columns,
            fallback=available_columns,
            default_to_all=True
        )
        st.session_state["profile_cols"] = cols
        applied_changes.append(f"profile_cols={len(cols)}")
        remember_page_runtime(page_key, {"profile_cols": cols}, used_columns=cols, dataset_id=dataset_id or "home")

    elif page_key == "missing":
        key_cols = normalize_column_list(config_updates.get("missing_key_identifiers", []), available_columns)
        target_cols = normalize_column_list(
            config_updates.get("missing_cols", [c for c in available_columns if c not in key_cols]),
            available_columns,
            exclude=key_cols,
            fallback=[c for c in available_columns if c not in key_cols],
            default_to_all=True
        )
        export_candidates = key_cols + ["Variable Name", "Value", "Reason"]
        export_cols = normalize_column_list(
            config_updates.get("missing_export_cols", export_candidates),
            export_candidates,
            fallback=export_candidates,
            default_to_all=True
        )
        st.session_state["missing_key_identifiers"] = key_cols
        st.session_state["missing_cols"] = target_cols
        st.session_state["missing_export_cols"] = export_cols
        applied_changes.append(f"keys={len(key_cols)}")
        applied_changes.append(f"targets={len(target_cols)}")
        remember_page_runtime(
            page_key,
            {
                "missing_key_identifiers": key_cols,
                "missing_cols": target_cols,
                "missing_export_cols": export_cols
            },
            used_columns=key_cols + target_cols + export_cols,
            dataset_id=dataset_id or "home"
        )

    elif page_key == "duplicate":
        key_cols = normalize_column_list(config_updates.get("duplicate_key_cols", []), available_columns)
        remaining_cols = [c for c in available_columns if c not in key_cols]
        check_cols = normalize_column_list(
            config_updates.get("duplicate_check_cols", remaining_cols),
            remaining_cols,
            fallback=remaining_cols[:3] if remaining_cols else [],
            default_to_all=not key_cols
        )
        st.session_state["dup_keys_multiselect_component"] = key_cols
        st.session_state["dup_checks_multiselect_component"] = check_cols
        st.session_state.tool_config["duplicate_key_cols"] = key_cols
        st.session_state.tool_config["duplicate_check_cols"] = check_cols
        applied_changes.append(f"keys={len(key_cols)}")
        applied_changes.append(f"checks={len(check_cols)}")

    elif page_key == "invalid_format":
        key_cols = normalize_column_list(config_updates.get("format_key_cols", []), available_columns)
        remaining_cols = [c for c in available_columns if c not in key_cols]
        check_cols = normalize_column_list(
            config_updates.get("invalid_cols", remaining_cols),
            remaining_cols,
            fallback=remaining_cols[:3] if remaining_cols else []
        )
        st.session_state["format_key_cols_widget"] = key_cols
        st.session_state["invalid_cols_widget"] = check_cols
        st.session_state.tool_config["format_key_cols"] = key_cols
        st.session_state.tool_config["invalid_cols"] = check_cols
        applied_changes.append(f"keys={len(key_cols)}")
        applied_changes.append(f"checks={len(check_cols)}")

    elif page_key == "outlier":
        key_cols = normalize_column_list(config_updates.get("outlier_key_cols", []), available_columns)
        available_after_keys = [c for c in available_columns if c not in key_cols]
        mode = normalize_text_choice(
            config_updates.get("outlier_mode", "Without Category Wise Outliers"),
            ["Without Category Wise Outliers", "Category Wise Outliers"],
            "Without Category Wise Outliers"
        )
        category_candidates = [c for c in available_after_keys]
        category_cols = normalize_column_list(
            config_updates.get("outlier_category_cols", []),
            category_candidates
        ) if mode == "Category Wise Outliers" else []
        numeric_candidates = [c for c in available_after_keys if c not in category_cols]
        outlier_cols = normalize_column_list(
            config_updates.get("outlier_cols", numeric_candidates[:3]),
            numeric_candidates,
            fallback=numeric_candidates[:3]
        )
        method = normalize_text_choice(config_updates.get("outlier_method", "IQR"), ["IQR", "ZScore"], "IQR")
        outlier_range = normalize_text_choice(
            config_updates.get("outlier_range", "Normal Outliers"),
            ["Normal Outliers", "Extreme Outliers"],
            "Normal Outliers"
        )
        exclusion_query = str(config_updates.get("outlier_exclusion_query", "") or "")

        st.session_state["outlier_key_cols_widget"] = key_cols
        st.session_state["outlier_mode_widget"] = mode
        st.session_state["outlier_category_cols_widget"] = category_cols
        st.session_state["outlier_cols_widget"] = outlier_cols
        st.session_state["outlier_method_widget"] = method
        st.session_state["outlier_range_widget"] = outlier_range
        st.session_state["outlier_exclusion_query_widget"] = exclusion_query
        st.session_state.tool_config["outlier_key_cols"] = key_cols
        st.session_state.tool_config["outlier_mode"] = mode
        st.session_state.tool_config["outlier_category_cols"] = category_cols
        st.session_state.tool_config["outlier_cols"] = outlier_cols
        st.session_state.tool_config["outlier_method"] = method
        st.session_state.tool_config["outlier_range"] = outlier_range
        st.session_state.tool_config["outlier_exclusion_query"] = exclusion_query
        applied_changes.append(f"mode={mode}")
        applied_changes.append(f"columns={len(outlier_cols)}")

    elif page_key == "logical":
        display_cols = normalize_column_list(config_updates.get("logical_display_cols", []), available_columns)
        validation_type = normalize_text_choice(
            config_updates.get("logical_validation_type", "Single Variable Validation"),
            ["Single Variable Validation", "Multi Variable Validation", "Boolean Logic Validation"],
            "Single Variable Validation"
        )
        st.session_state["logical_display_cols_widget"] = display_cols
        st.session_state["logical_validation_type_widget"] = validation_type
        st.session_state.tool_config["logical_display_cols"] = display_cols
        st.session_state.tool_config["logical_validation_type"] = validation_type

        if validation_type == "Single Variable Validation":
            single_col = normalize_scalar_column(config_updates.get("single_col"), available_columns)
            single_condition = normalize_text_choice(config_updates.get("single_condition", ">"),
                                                     [">", ">=", "<", "<=", "=", "!="], ">")
            single_value = float(config_updates.get("single_val_input", 0.0) or 0.0)
            st.session_state["single_col_widget"] = single_col
            st.session_state["single_condition_widget"] = single_condition
            st.session_state["single_val_input_widget"] = single_value
            st.session_state.tool_config["single_col"] = single_col
            st.session_state.tool_config["single_condition"] = single_condition
            st.session_state.tool_config["single_val_input"] = single_value
            applied_changes.append(f"validation={validation_type}")
        elif validation_type == "Multi Variable Validation":
            logic_cols = normalize_column_list(config_updates.get("logic_cols", []), available_columns)
            math_operator = normalize_text_choice(config_updates.get("math_operator", "SUM"),
                                                  ["SUM", "SUBTRACT", "MULTIPLY", "DIVIDE"], "SUM")
            compare_col = normalize_scalar_column(config_updates.get("compare_col"), available_columns)
            comparison_operator = normalize_text_choice(config_updates.get("comparison_operator", ">"),
                                                        [">", "<", "=", "!=", ">=", "<="], ">")
            st.session_state["logic_cols_widget"] = logic_cols
            st.session_state["math_operator_widget"] = math_operator
            st.session_state["compare_col_widget"] = compare_col
            st.session_state["comparison_operator_widget"] = comparison_operator
            st.session_state.tool_config["logic_cols"] = logic_cols
            st.session_state.tool_config["math_operator"] = math_operator
            st.session_state.tool_config["compare_col"] = compare_col
            st.session_state.tool_config["comparison_operator"] = comparison_operator
            applied_changes.append(f"validation={validation_type}")
        else:
            applied_changes.append(f"validation={validation_type}")

    elif page_key == "comparison":
        comparison_type = normalize_text_choice(
            config_updates.get("comparison_type", "Sample Comparison Checks"),
            ["Sample Comparison Checks", "Historical Comparison Checks"],
            "Sample Comparison Checks"
        )
        compare_by_cols = normalize_column_list(config_updates.get("compare_by_cols", []), available_columns)
        compare_cols = normalize_column_list(
            config_updates.get("compare_cols", []),
            available_columns,
            exclude=compare_by_cols
        )
        rule_count = int(config_updates.get("comparison_rules", 1) or 1)
        st.session_state["comparison_type_widget"] = comparison_type
        st.session_state["compare_by_cols_widget"] = compare_by_cols
        st.session_state["compare_cols_widget"] = compare_cols
        st.session_state["comparison_rules_widget"] = max(1, min(rule_count, 50))
        st.session_state.tool_config["comparison_type"] = comparison_type
        st.session_state.tool_config["compare_by_cols"] = compare_by_cols
        st.session_state.tool_config["compare_cols"] = compare_cols
        st.session_state.tool_config["comparison_rules"] = max(1, min(rule_count, 50))
        if config_updates.get("comparison_dataset"):
            st.session_state.tool_config["comparison_dataset"] = config_updates.get("comparison_dataset")
        applied_changes.append(f"type={comparison_type}")
        applied_changes.append(f"keys={len(compare_by_cols)}")
        applied_changes.append(f"checks={len(compare_cols)}")

    elif page_key == "insights":
        available_checks = [
            "Missing Checks",
            "Duplicate Checks",
            "Invalid Format",
            "Outlier Checks",
            "Logical Checks",
            "Comparison Checks"
        ]
        requested_check = (
                config_updates.get("selected_check")
                or config_updates.get("check_name")
                or config_updates.get("open_check")
        )
        requested_view = str(config_updates.get("view", "") or "").strip().lower()

        if requested_view in ["overview", "home", "summary", "dashboard"]:
            st.session_state.selected_check = None
            applied_changes.append("opened insights overview")
        else:
            selected_check = normalize_text_choice(requested_check, available_checks, None) if requested_check else None
            if selected_check:
                st.session_state.selected_check = selected_check
                applied_changes.append(f"opened {selected_check}")
            else:
                st.session_state.selected_check = None
                applied_changes.append("opened insights overview")

        remember_page_runtime(
            page_key,
            {
                "selected_check": st.session_state.get("selected_check"),
                "view": "drilldown" if st.session_state.get("selected_check") else "overview"
            },
            used_columns=[],
            dataset_id=dataset_id or "home"
        )

    else:
        return False, "Copilot automation is not configured for this page yet."

    if page_key in ["duplicate", "invalid_format", "comparison"]:
        remember_page_runtime(
            page_key,
            copy.deepcopy(st.session_state.tool_config),
            used_columns=extract_used_columns_from_config(st.session_state.tool_config),
            dataset_id=dataset_id or st.session_state.get(f"{page_key}_source", "home")
        )

    if page_key == "logical":
        remember_page_runtime(
            page_key,
            copy.deepcopy(st.session_state.tool_config),
            used_columns=extract_used_columns_from_config(st.session_state.tool_config),
            dataset_id=dataset_id or st.session_state.get(f"{page_key}_source", "home")
        )

    return True, ", ".join(applied_changes) if applied_changes else "Configuration applied."


def build_workflow_dataset_catalog():
    catalog = copy.deepcopy(st.session_state.get("workflow_dataset_catalog", {}))
    raw_df = st.session_state.get("main_df")
    prepared_df = st.session_state.get("prepared_df")

    if isinstance(raw_df, pd.DataFrame):
        catalog["home"] = {
            "label": "Home - Raw Dataset",
            "page_name": "🏠 Home",
            "tool_name": "Data Loader",
            "columns": list(raw_df.columns),
            "row_count": len(raw_df)
        }

    if isinstance(prepared_df, pd.DataFrame):
        catalog["prepared"] = {
            "label": "Prepared Dataset",
            "page_name": "🔧 Data Preparation",
            "tool_name": "Prepared Dataset",
            "columns": list(prepared_df.columns),
            "row_count": len(prepared_df),
            "source_dataset_id": "home"
        }

    workflow_datasets = st.session_state.get("workflow_datasets", {})
    for dataset_id, metadata in workflow_datasets.items():
        if isinstance(metadata, pd.DataFrame):
            catalog[dataset_id] = {
                "label": dataset_id,
                "page_name": "Workflow",
                "tool_name": dataset_id,
                "columns": list(metadata.columns),
                "row_count": len(metadata)
            }
        elif isinstance(metadata, dict):
            frame = metadata.get("data")
            if isinstance(frame, pd.DataFrame):
                computed_label = metadata.get("label", dataset_id)
                if str(dataset_id).startswith("dp_step_"):
                    try:
                        step_index = int(str(dataset_id).split("_")[-1])
                    except (TypeError, ValueError):
                        step_index = None
                    if step_index:
                        computed_label = format_step_output_label(
                            step_index,
                            metadata.get("tool_name", metadata.get("label", "Tool")),
                            frame
                        )
                catalog[dataset_id] = {
                    "label": computed_label,
                    "page_name": metadata.get("page_name", "Workflow"),
                    "tool_name": metadata.get("tool_name", metadata.get("label", dataset_id)),
                    "columns": list(frame.columns),
                    "row_count": len(frame),
                    "source_dataset_id": metadata.get("source_dataset_id")
                }

    st.session_state.workflow_dataset_catalog = catalog
    return catalog


def format_step_output_label(step_index, tool_name, dataframe=None):
    tool_label = str(tool_name or "Tool").strip() or "Tool"
    base_label = f"Step {int(step_index)} Output ({tool_label})"
    if isinstance(dataframe, pd.DataFrame):
        return f"{base_label} - {len(dataframe):,} rows × {len(dataframe.columns):,} columns"
    return base_label


def register_dataset_output(dataset_id, label, dataframe, page_name, tool_name, source_dataset_id=None, duration_ms=0,
                            log_history=True):
    if not isinstance(dataframe, pd.DataFrame):
        return
    dataframe = stabilize_alteryx_mapping(dataframe)

    if "workflow_datasets" not in st.session_state:
        st.session_state.workflow_datasets = {}
    if "dp_selected_step_index" not in st.session_state:
        st.session_state.dp_selected_step_index = None
    if "dp_pending_connection_source" not in st.session_state:
        st.session_state.dp_pending_connection_source = None
    if "dp_connection_string" not in st.session_state:
        st.session_state.dp_connection_string = ""
    if "dp_output_preview_step_index" not in st.session_state:
        st.session_state.dp_output_preview_step_index = None
    if "dp_execute_step_index" not in st.session_state:
        st.session_state.dp_execute_step_index = None

    st.session_state.workflow_datasets[dataset_id] = {
        "data": dataframe.copy(),
        "label": label,
        "page_name": page_name,
        "tool_name": tool_name,
        "source_dataset_id": source_dataset_id,
        "updated_at": dt_datetime.now().isoformat()
    }

    enhanced_config_manager.tool_registry.register_output(
        step_id=dataset_id,
        tool_name=tool_name,
        output_columns=list(dataframe.columns),
        row_count=len(dataframe),
        source_step_id=source_dataset_id,
        output_data=dataframe.copy(),
        metadata={
            "label": label,
            "page_name": page_name
        }
    )
    if log_history and page_name != "🔧 Data Preparation":
        source_df = None
        if source_dataset_id:
            source_registry = get_dataset_registry(st.session_state.get("main_df"))
            if source_dataset_id in source_registry:
                source_candidate = source_registry[source_dataset_id].get("data")
                if isinstance(source_candidate, pd.DataFrame):
                    source_df = source_candidate
        if source_df is None:
            source_df = st.session_state.get("main_df")

        log_page_execution(
            page_name=page_name,
            tool_name=tool_name,
            execution_scope="page_result_dataset",
            input_df=source_df,
            output_df=dataframe,
            source_dataset_id=source_dataset_id,
            duration_ms=duration_ms,
            status="success",
            log_messages=[f"Registered dataset output '{dataset_id}' for page '{page_name}'."]
        )
    build_workflow_dataset_catalog()


def get_dataset_registry(base_df=None):
    dataset_registry = {}

    raw_df = base_df if isinstance(base_df, pd.DataFrame) else st.session_state.get("main_df")
    if isinstance(raw_df, pd.DataFrame):
        # Normalize to ensure column alignment (critical for Alteryx files)
        normalized_df = stabilize_alteryx_mapping(normalize_dataframe_alignment(raw_df.copy()))
        dataset_registry["home"] = {
            "data": normalized_df,
            "label": "Home - Raw Dataset",
            "page_name": "🏠 Home",
            "tool_name": "Data Loader"
        }

    prepared_df = st.session_state.get("prepared_df")
    if isinstance(prepared_df, pd.DataFrame):
        # Normalize to ensure column alignment
        normalized_df = stabilize_alteryx_mapping(normalize_dataframe_alignment(prepared_df.copy()))
        dataset_registry["prepared"] = {
            "data": normalized_df,
            "label": "Prepared Dataset",
            "page_name": "🔧 Data Preparation",
            "tool_name": "Prepared Dataset",
            "source_dataset_id": "home"
        }

    workflow_datasets = st.session_state.get("workflow_datasets", {})
    for dataset_id, metadata in workflow_datasets.items():
        if isinstance(metadata, pd.DataFrame):
            normalized_df = stabilize_alteryx_mapping(normalize_dataframe_alignment(metadata.copy()))
            dataset_registry[dataset_id] = {
                "data": normalized_df,
                "label": dataset_id,
                "page_name": "Workflow",
                "tool_name": dataset_id
            }
        elif isinstance(metadata, dict) and isinstance(metadata.get("data"), pd.DataFrame):
            normalized_df = stabilize_alteryx_mapping(normalize_dataframe_alignment(metadata["data"].copy()))
            dataset_registry[dataset_id] = {
                "data": normalized_df,
                "label": metadata.get("label", dataset_id),
                "page_name": metadata.get("page_name", "Workflow"),
                "tool_name": metadata.get("tool_name", metadata.get("label", dataset_id)),
                "source_dataset_id": metadata.get("source_dataset_id")
            }

    for idx0, step in enumerate(st.session_state.get("dp_canvas", [])):
        if not isinstance(step, dict):
            continue
        idx1 = idx0 + 1
        step_df = step.get("cached_output") if isinstance(step.get("cached_output"), pd.DataFrame) else step.get("data")
        if isinstance(step_df, pd.DataFrame):
            normalized_df = stabilize_alteryx_mapping(normalize_dataframe_alignment(step_df))
            label = format_step_output_label(idx1, step.get("tool", "Tool"), normalized_df)
            meta = {
                "data": normalized_df,
                "label": label,
                "page_name": "Data Preparation",
                "tool_name": step.get("tool", f"Step {idx1}"),
                "source_dataset_id": "home",
            }
            dataset_registry[f"dp_step_{idx1}"] = meta
            dataset_registry[f"step_{idx0}"] = {
                **meta,
                "label": f"{label} [True]" if step.get("tool") == "Filter Tool" else label,
            }
            if step.get("tool") == "Filter Tool":
                dataset_registry[f"step_{idx0}_true"] = dataset_registry[f"step_{idx0}"]

        false_df = (
            step.get("cached_output_false")
            if isinstance(step.get("cached_output_false"), pd.DataFrame)
            else step.get("data_false")
        )
        if isinstance(false_df, pd.DataFrame):
            normalized_false = stabilize_alteryx_mapping(normalize_dataframe_alignment(false_df))
            dataset_registry[f"step_{idx0}_false"] = {
                "data": normalized_false,
                "label": format_step_output_label(idx1, f"{step.get('tool', 'Tool')} False", normalized_false),
                "page_name": "Data Preparation",
                "tool_name": step.get("tool", f"Step {idx1}"),
                "source_dataset_id": f"step_{idx0}",
                "filter_port": "False",
            }

    build_workflow_dataset_catalog()
    return dataset_registry


def resolve_dataset_log_reference(dataset_id=None, base_df=None, fallback_label=None, fallback_tool_name=None):
    dataset_registry = get_dataset_registry(base_df)
    normalized_dataset_id = str(dataset_id).strip() if dataset_id not in [None, ""] else ""
    metadata = dataset_registry.get(normalized_dataset_id, {}) if normalized_dataset_id else {}

    dataset_label = (
            metadata.get("label")
            or fallback_label
            or normalized_dataset_id
            or "Manual Input Dataset"
    )
    tool_name = (
            metadata.get("tool_name")
            or fallback_tool_name
            or metadata.get("page_name")
            or "Unknown Tool"
    )
    dataset_key = normalized_dataset_id or sanitize_dataset_id(dataset_label) or "manual_input"
    dataset_name = f"{dataset_label} [{dataset_key}] - Tool: {tool_name}"

    return {
        "dataset_id": dataset_key,
        "dataset_name": dataset_name,
        "dataset_label": dataset_label,
        "tool_name": tool_name
    }


def resolve_step_input_log_reference(step, base_df=None):
    """Return a human-readable input source reference for single- and multi-input steps."""
    if not isinstance(step, dict):
        return resolve_dataset_log_reference(base_df=base_df)

    tool_name = str(step.get("tool", "Tool"))
    config = step.get("config", {}) if isinstance(step.get("config", {}), dict) else {}

    if tool_name == "Join Tool":
        left_id = config.get("left_id") or config.get("left_dataset") or config.get("dataset_id")
        right_id = config.get("right_id") or config.get("right_dataset")
        left_ref = resolve_dataset_log_reference(
            left_id,
            base_df=base_df,
            fallback_label="Left Input",
            fallback_tool_name=tool_name
        )
        right_ref = resolve_dataset_log_reference(
            right_id,
            base_df=base_df,
            fallback_label="Right Input",
            fallback_tool_name=tool_name
        )
        return {
            "dataset_id": f"{left_ref['dataset_id']}|{right_ref['dataset_id']}",
            "dataset_name": f"Left: {left_ref['dataset_name']} | Right: {right_ref['dataset_name']}",
            "dataset_label": f"{left_ref['dataset_label']} | {right_ref['dataset_label']}",
            "tool_name": tool_name
        }

    if tool_name == "Union Tool":
        selected_ids = config.get("selected_ids", [])
        if isinstance(selected_ids, str):
            selected_ids = [sid.strip() for sid in selected_ids.split(",") if sid.strip()]
        if isinstance(selected_ids, list) and selected_ids:
            refs = [
                resolve_dataset_log_reference(
                    sid,
                    base_df=base_df,
                    fallback_label=f"Input {idx + 1}",
                    fallback_tool_name=tool_name
                )
                for idx, sid in enumerate(selected_ids)
            ]
            combined_id = " + ".join([ref["dataset_id"] for ref in refs if ref.get("dataset_id")]) or "union_inputs"
            combined_name = " | ".join(
                [f"Input {idx + 1}: {ref['dataset_name']}" for idx, ref in enumerate(refs)]
            )
            combined_label = " | ".join(
                [f"Input {idx + 1}: {ref['dataset_label']}" for idx, ref in enumerate(refs)]
            )
            return {
                "dataset_id": combined_id,
                "dataset_name": combined_name,
                "dataset_label": combined_label,
                "tool_name": tool_name
            }

        fallback_ref = resolve_dataset_log_reference(
            config.get("dataset_id"),
            base_df=base_df,
            fallback_label="Union Input",
            fallback_tool_name=tool_name
        )
        return fallback_ref

    return resolve_dataset_log_reference(
        config.get("dataset_id"),
        base_df=base_df,
        fallback_label=config.get("input_dataset_name"),
        fallback_tool_name=tool_name
    )


def build_manual_step_identifier(page_name, tool_name, execution_scope, source_dataset_id=None):
    parts = [
        "manual",
        sanitize_dataset_id(page_name or "page"),
        sanitize_dataset_id(tool_name or "tool"),
        sanitize_dataset_id(execution_scope or "execution")
    ]
    if source_dataset_id not in [None, ""]:
        parts.append(sanitize_dataset_id(source_dataset_id))
    return "_".join([part for part in parts if part]) or "manual_step"


def resolve_dataset_selector_state(step_config, dataset_registry, preferred_dataset_id="home"):
    dataset_ids = list(dataset_registry.keys())
    if not dataset_ids:
        return [], None, None

    saved_dataset_id = step_config.get("dataset_id", preferred_dataset_id)
    if saved_dataset_id not in dataset_ids:
        saved_dataset_id = preferred_dataset_id if preferred_dataset_id in dataset_ids else dataset_ids[0]

    return dataset_ids, saved_dataset_id, dataset_ids.index(saved_dataset_id)


def sync_selectbox_state_to_options(widget_key, options, fallback_value=None):
    """Keep Streamlit selectbox state aligned with its current option list."""
    if not options:
        return
    current_value = st.session_state.get(widget_key)
    if current_value not in options:
        if fallback_value in options:
            st.session_state[widget_key] = fallback_value
        else:
            st.session_state[widget_key] = options[0]


@st.cache_resource(show_spinner=False)
def build_sqlalchemy_engine_from_config(cfg):
    db_type = (cfg.get("db_type") or "").strip().lower()

    if db_type == "sqlserver":
        host = cfg.get("host", "")
        port = cfg.get("port")
        host_part = f"{host},{port}" if port else host
        return create_engine(
            f"mssql+pyodbc://{cfg['user']}:{cfg['password']}"
            f"@{host_part}/{cfg['database']}"
            "?driver=ODBC+Driver+17+for+SQL+Server"
        )

    if db_type == "postgresql":
        return create_engine(
            f"postgresql+psycopg2://{cfg['user']}:{cfg['password']}"
            f"@{cfg['host']}:{cfg['port']}/{cfg['database']}"
        )

    if db_type == "mysql":
        return create_engine(
            f"mysql+pymysql://{cfg['user']}:{cfg['password']}"
            f"@{cfg['host']}:{cfg['port']}/{cfg['database']}"
        )

    if db_type == "oracle":
        port = cfg.get("port") or 1521
        return create_engine(
            f"oracle+oracledb://{cfg['user']}:{cfg['password']}"
            f"@{cfg['host']}:{port}/?service_name={cfg['database']}",
            pool_pre_ping=True
        )

    if db_type == "sqlite":
        db_path = cfg.get("db_path")
        if db_path:
            return create_engine(f"sqlite:///{db_path}")

    raise ValueError(f"Unsupported database type: {db_type or 'unknown'}")


def get_execution_log_db_path():
    base_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
    return os.path.join(base_dir, "execution_history.db")


def get_project_library_dir():
    base_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
    library_dir = os.path.join(base_dir, "saved_projects")
    os.makedirs(library_dir, exist_ok=True)
    return library_dir


def get_project_autosave_dir():
    base_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
    autosave_dir = os.path.join(base_dir, "local_workflow_backups", "autosave")
    os.makedirs(autosave_dir, exist_ok=True)
    return autosave_dir


def cleanup_project_autosaves(retention_days=10):
    """Delete autosave versions older than the retention window."""
    autosave_dir = get_project_autosave_dir()
    cutoff_ts = time.time() - (int(retention_days) * 86400)
    removed_files = []

    for file_name in os.listdir(autosave_dir):
        if not file_name.lower().endswith(".json"):
            continue
        file_path = os.path.join(autosave_dir, file_name)
        try:
            if os.path.getmtime(file_path) < cutoff_ts:
                os.remove(file_path)
                removed_files.append(file_path)
        except Exception:
            continue

    return removed_files


def get_project_library_file_path(project_name):
    safe_name = sanitize_dataset_id(project_name or "Untitled_Project") or "untitled_project"
    return os.path.join(get_project_library_dir(), f"{safe_name}.json")


def save_project_to_library(project_name, project_json):
    if not project_json:
        return None

    target_path = get_project_library_file_path(project_name)
    with open(target_path, "w", encoding="utf-8") as project_file:
        project_file.write(project_json)
    return target_path


def save_project_autosave(project_name, project_json):
    if not project_json:
        return None

    safe_name = sanitize_dataset_id(project_name or "Untitled_Project") or "untitled_project"
    timestamp = dt_datetime.now().strftime("%Y%m%d_%H%M%S")
    target_path = os.path.join(get_project_autosave_dir(), f"{safe_name}_autosave_{timestamp}.json")
    with open(target_path, "w", encoding="utf-8") as project_file:
        project_file.write(project_json)
    cleanup_project_autosaves(retention_days=10)
    return target_path


def strip_sensitive_db_fields(value):
    """Remove password-like fields while preserving queries and other connection settings."""
    if isinstance(value, dict):
        cleaned = {}
        for key, val in value.items():
            if "password" in str(key).lower() or "passphrase" in str(key).lower() or "pwd" in str(key).lower():
                continue
            cleaned[key] = strip_sensitive_db_fields(val)
        return cleaned
    if isinstance(value, list):
        return [strip_sensitive_db_fields(item) for item in value]
    return value


def list_saved_projects_in_library():
    library_dir = get_project_library_dir()
    project_rows = []
    for file_name in os.listdir(library_dir):
        if not file_name.lower().endswith(".json"):
            continue
        file_path = os.path.join(library_dir, file_name)
        project_name = os.path.splitext(file_name)[0]
        try:
            with open(file_path, "r", encoding="utf-8") as project_file:
                project_payload = json.load(project_file)
            project_name = (
                    project_payload.get("home_config", {}).get("project_name")
                    or project_payload.get("project_name")
                    or project_name
            )
        except Exception:
            pass
        updated_at = dt_datetime.fromtimestamp(os.path.getmtime(file_path)).isoformat()
        project_rows.append({
            "project_name": project_name,
            "file_name": file_name,
            "file_path": file_path,
            "updated_at": updated_at
        })

    return sorted(project_rows, key=lambda row: row["updated_at"], reverse=True)


def load_project_from_library(file_path):
    with open(file_path, "r", encoding="utf-8") as project_file:
        return json.load(project_file)


def initialize_execution_log_store():
    def ensure_columns(conn, table_name, expected_columns):
        existing_columns = {
            row[1]
            for row in conn.execute(f"PRAGMA table_info({table_name})").fetchall()
        }
        for column_name, column_type in expected_columns.items():
            if column_name not in existing_columns:
                conn.execute(f"ALTER TABLE {table_name} ADD COLUMN {column_name} {column_type}")

    with sqlite3.connect(get_execution_log_db_path()) as conn:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS execution_runs
            (
                run_id
                TEXT
                PRIMARY
                KEY,
                execution_id
                TEXT,
                project_name
                TEXT,
                user_name
                TEXT,
                page_name
                TEXT,
                tool_name
                TEXT,
                run_mode
                TEXT,
                execution_scope
                TEXT,
                status
                TEXT,
                requested_step_index
                INTEGER,
                step_count
                INTEGER,
                failed_steps
                INTEGER
                DEFAULT
                0,
                total_input_rows
                INTEGER
                DEFAULT
                0,
                total_output_rows
                INTEGER
                DEFAULT
                0,
                total_duration_ms
                REAL
                DEFAULT
                0,
                created_date
                TEXT,
                created_time
                TEXT,
                started_at
                TEXT,
                finished_at
                TEXT
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS execution_step_logs
            (
                log_id
                INTEGER
                PRIMARY
                KEY
                AUTOINCREMENT,
                run_id
                TEXT
                NOT
                NULL,
                activity_id
                TEXT,
                execution_id
                TEXT,
                project_name
                TEXT,
                user_name
                TEXT,
                page_name
                TEXT,
                execution_scope
                TEXT,
                event_type
                TEXT,
                step_index
                INTEGER,
                step_id
                TEXT,
                tool_name
                TEXT,
                input_dataset_id
                TEXT,
                input_dataset_name
                TEXT,
                input_rows
                INTEGER,
                input_columns
                INTEGER,
                output_rows
                INTEGER,
                output_columns
                INTEGER,
                duration_ms
                REAL,
                status
                TEXT,
                error_message
                TEXT,
                created_date
                TEXT,
                created_time
                TEXT,
                started_at
                TEXT,
                finished_at
                TEXT,
                log_messages_json
                TEXT,
                FOREIGN
                KEY
            (
                run_id
            ) REFERENCES execution_runs
            (
                run_id
            )
                )
            """
        )
        ensure_columns(conn, "execution_runs", {
            "execution_id": "TEXT",
            "tool_name": "TEXT",
            "execution_scope": "TEXT",
            "created_date": "TEXT",
            "created_time": "TEXT"
        })
        ensure_columns(conn, "execution_step_logs", {
            "activity_id": "TEXT",
            "execution_id": "TEXT",
            "execution_scope": "TEXT",
            "event_type": "TEXT",
            "input_dataset_name": "TEXT",
            "created_date": "TEXT",
            "created_time": "TEXT"
        })
        conn.execute("CREATE INDEX IF NOT EXISTS idx_execution_runs_project ON execution_runs(project_name)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_execution_runs_user ON execution_runs(user_name)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_execution_step_logs_run ON execution_step_logs(run_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_execution_step_logs_page ON execution_step_logs(page_name)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_execution_step_logs_activity ON execution_step_logs(activity_id)")
        conn.commit()


def count_dataframe_rows(dataframe):
    return int(len(dataframe)) if isinstance(dataframe, pd.DataFrame) else 0


def count_dataframe_columns(dataframe):
    return int(len(dataframe.columns)) if isinstance(dataframe, pd.DataFrame) else 0


def create_execution_run_context(page_name, run_mode, step_count, requested_step_index=None):
    initialize_execution_log_store()

    run_started_at = dt_datetime.now()
    execution_id = f"exec_{int(time.time() * 1000)}"
    run_context = {
        "run_id": f"run_{int(time.time() * 1000)}",
        "execution_id": execution_id,
        "project_name": str(st.session_state.get("project_name", "Untitled_Project")),
        "user_name": str(st.session_state.get("user") or "anonymous"),
        "page_name": page_name,
        "tool_name": "Workflow Builder" if page_name == "🔧 Data Preparation" else page_name,
        "run_mode": run_mode,
        "execution_scope": "data_preparation_flow",
        "requested_step_index": requested_step_index,
        "step_count": int(step_count),
        "created_date": run_started_at.strftime("%Y-%m-%d"),
        "created_time": run_started_at.strftime("%H:%M:%S"),
        "started_at": run_started_at.isoformat(),
        "started_at_dt": run_started_at
    }

    with sqlite3.connect(get_execution_log_db_path()) as conn:
        conn.execute(
            """
            INSERT OR REPLACE INTO execution_runs (
                run_id, execution_id, project_name, user_name, page_name, tool_name, run_mode,
                execution_scope, status, requested_step_index, step_count, created_date,
                created_time, started_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                run_context["run_id"],
                run_context["execution_id"],
                run_context["project_name"],
                run_context["user_name"],
                run_context["page_name"],
                run_context["tool_name"],
                run_context["run_mode"],
                run_context["execution_scope"],
                "running",
                run_context["requested_step_index"],
                run_context["step_count"],
                run_context["created_date"],
                run_context["created_time"],
                run_context["started_at"]
            )
        )
        conn.commit()

    st.session_state.dp_execution_step_logs = []
    st.session_state.dp_execution_run_context = {
        key: value for key, value in run_context.items() if key != "started_at_dt"
    }
    return run_context


def record_execution_step_log(run_context, step_index, step, input_df, output_df, status, duration_ms, log_messages,
                              error_message=None):
    initialize_execution_log_store()

    finished_at = dt_datetime.now()
    started_at = finished_at - datetime.timedelta(milliseconds=float(duration_ms or 0))
    activity_id = f"act_{int(time.time() * 1000)}_{step_index + 1}"
    input_dataset_ref = resolve_step_input_log_reference(step, base_df=input_df)
    log_entry = {
        "run_id": run_context["run_id"],
        "activity_id": activity_id,
        "execution_id": run_context.get("execution_id", run_context["run_id"]),
        "project_name": run_context["project_name"],
        "user_name": run_context["user_name"],
        "page_name": run_context["page_name"],
        "execution_scope": run_context.get("execution_scope", "data_preparation_flow"),
        "step_number": int(step_index) + 1,
        "step_id": str(
            step.get("id") or f"workflow_step_{step_index + 1}_{sanitize_dataset_id(step.get('tool', 'tool'))}"),
        "tool_name": str(step.get("tool", "Tool")),
        "input_dataset_id": input_dataset_ref["dataset_id"],
        "input_dataset_name": input_dataset_ref["dataset_name"],
        "input_rows": count_dataframe_rows(input_df),
        "input_columns": count_dataframe_columns(input_df),
        "output_rows": count_dataframe_rows(output_df),
        "output_columns": count_dataframe_columns(output_df),
        "duration_ms": round(float(duration_ms or 0), 2),
        "duration_seconds": round(float(duration_ms or 0) / 1000, 3),
        "status": status,
        "error_message": str(error_message or ""),
        "created_date": finished_at.strftime("%Y-%m-%d"),
        "created_time": finished_at.strftime("%H:%M:%S"),
        "started_at": started_at.isoformat(),
        "finished_at": finished_at.isoformat(),
        "log_message_count": len(log_messages or [])
    }

    st.session_state.dp_execution_step_logs.append(log_entry)

    with sqlite3.connect(get_execution_log_db_path()) as conn:
        conn.execute(
            """
            INSERT INTO execution_step_logs (run_id, activity_id, execution_id, project_name, user_name, page_name,
                                             execution_scope,
                                             event_type, step_index, step_id, tool_name, input_dataset_id,
                                             input_dataset_name, input_rows, input_columns,
                                             output_rows, output_columns, duration_ms, status, error_message,
                                             created_date, created_time,
                                             started_at, finished_at, log_messages_json)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                run_context["run_id"],
                log_entry["activity_id"],
                log_entry["execution_id"],
                run_context["project_name"],
                run_context["user_name"],
                run_context["page_name"],
                log_entry["execution_scope"],
                "step_execution",
                int(step_index) + 1,
                log_entry["step_id"],
                log_entry["tool_name"],
                log_entry["input_dataset_id"],
                log_entry["input_dataset_name"],
                log_entry["input_rows"],
                log_entry["input_columns"],
                log_entry["output_rows"],
                log_entry["output_columns"],
                log_entry["duration_ms"],
                status,
                log_entry["error_message"],
                log_entry["created_date"],
                log_entry["created_time"],
                log_entry["started_at"],
                log_entry["finished_at"],
                json.dumps(log_messages or [], ensure_ascii=False)
            )
        )
        conn.commit()


def classify_step_execution_status(output_df, log_messages, error_message=None):
    """Convert step runner outcomes into normalized log statuses."""
    if error_message:
        return "failed"

    messages_text = " ".join([str(msg) for msg in (log_messages or [])]).lower()
    unable_markers = [
        "skipped",
        "no data uploaded/configured",
        "missing upstream cached dataframe node connection",
        "missing upstream",
        "no target columns selected",
        "please select",
        "empty expression",
        "invalid columns",
        "cannot",
        "unable to process",
        "mismatch error",
        "required",
        "not found"
    ]
    if output_df is None or any(marker in messages_text for marker in unable_markers):
        return "Unable to process"

    failure_markers = ["failed", "error", "crash", "exception"]
    if any(marker in messages_text for marker in failure_markers):
        return "failed"

    return "success"


def finalize_execution_run_context(run_context):
    initialize_execution_log_store()

    current_logs = st.session_state.get("dp_execution_step_logs", [])
    finished_at = dt_datetime.now()
    total_duration_ms = (finished_at - run_context["started_at_dt"]).total_seconds() * 1000
    failed_steps = len([row for row in current_logs if str(row.get("status", "")).lower() != "success"])
    run_status = "failed" if failed_steps else "success"
    total_input_rows = sum(int(row.get("input_rows", 0) or 0) for row in current_logs)
    total_output_rows = sum(int(row.get("output_rows", 0) or 0) for row in current_logs)

    run_summary = {
        "run_id": run_context["run_id"],
        "project_name": run_context["project_name"],
        "user_name": run_context["user_name"],
        "page_name": run_context["page_name"],
        "tool_name": run_context.get("tool_name", ""),
        "run_mode": run_context["run_mode"],
        "execution_scope": run_context.get("execution_scope", "data_preparation_flow"),
        "requested_step_index": run_context["requested_step_index"],
        "step_count": run_context["step_count"],
        "failed_steps": failed_steps,
        "total_input_rows": total_input_rows,
        "total_output_rows": total_output_rows,
        "total_duration_ms": round(total_duration_ms, 2),
        "status": run_status,
        "created_date": run_context["created_date"],
        "created_time": run_context["created_time"],
        "started_at": run_context["started_at"],
        "finished_at": finished_at.isoformat()
    }

    with sqlite3.connect(get_execution_log_db_path()) as conn:
        conn.execute(
            """
            UPDATE execution_runs
            SET tool_name         = ?,
                execution_scope   = ?,
                status            = ?,
                failed_steps      = ?,
                total_input_rows  = ?,
                total_output_rows = ?,
                total_duration_ms = ?,
                finished_at       = ?
            WHERE run_id = ?
            """,
            (
                run_summary["tool_name"],
                run_summary["execution_scope"],
                run_status,
                failed_steps,
                total_input_rows,
                total_output_rows,
                run_summary["total_duration_ms"],
                run_summary["finished_at"],
                run_context["run_id"]
            )
        )
        conn.commit()

    st.session_state.dp_execution_run_summary = run_summary
    return run_summary


def get_current_execution_log_dataframe():
    log_rows = st.session_state.get("dp_execution_step_logs", [])
    if not log_rows:
        return pd.DataFrame()

    log_df = pd.DataFrame(log_rows)
    ordered_columns = [
        "activity_id", "execution_id", "run_id", "project_name", "user_name", "page_name", "tool_name",
        "execution_scope", "step_number", "step_id", "input_dataset_id", "input_dataset_name", "input_rows",
        "input_columns",
        "output_rows", "output_columns", "duration_ms", "duration_seconds", "status", "error_message",
        "created_date", "created_time", "started_at", "finished_at", "log_message_count"
    ]
    return log_df[[col for col in ordered_columns if col in log_df.columns]]


def get_current_run_summary_dataframe():
    run_summary = st.session_state.get("dp_execution_run_summary", {})
    if not run_summary:
        return pd.DataFrame()
    return pd.DataFrame([run_summary])


def create_page_execution_context(page_name, tool_name, execution_scope, input_df=None, source_dataset_id=None,
                                  run_mode="Page Execution"):
    initialize_execution_log_store()

    started_at = dt_datetime.now()
    run_id = f"run_{int(time.time() * 1000)}"
    execution_id = f"exec_{int(time.time() * 1000)}"
    input_dataset_ref = resolve_dataset_log_reference(
        source_dataset_id,
        base_df=input_df,
        fallback_label=f"{tool_name} Input Dataset",
        fallback_tool_name=tool_name
    )
    run_context = {
        "run_id": run_id,
        "execution_id": execution_id,
        "project_name": str(st.session_state.get("project_name", "Untitled_Project")),
        "user_name": str(st.session_state.get("user") or "anonymous"),
        "page_name": str(page_name),
        "tool_name": str(tool_name),
        "run_mode": run_mode,
        "execution_scope": str(execution_scope),
        "requested_step_index": None,
        "step_count": 1,
        "created_date": started_at.strftime("%Y-%m-%d"),
        "created_time": started_at.strftime("%H:%M:%S"),
        "started_at": started_at.isoformat(),
        "started_at_dt": started_at,
        "source_dataset_id": input_dataset_ref["dataset_id"],
        "input_dataset_name": input_dataset_ref["dataset_name"],
        "step_id": build_manual_step_identifier(
            page_name,
            tool_name,
            execution_scope,
            input_dataset_ref["dataset_id"]
        ),
        "input_rows": count_dataframe_rows(input_df),
        "input_columns": count_dataframe_columns(input_df)
    }

    with sqlite3.connect(get_execution_log_db_path()) as conn:
        conn.execute(
            """
            INSERT OR REPLACE INTO execution_runs (
                run_id, execution_id, project_name, user_name, page_name, tool_name, run_mode,
                execution_scope, status, requested_step_index, step_count, failed_steps,
                total_input_rows, total_output_rows, total_duration_ms, created_date, created_time, started_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                run_context["run_id"],
                run_context["execution_id"],
                run_context["project_name"],
                run_context["user_name"],
                run_context["page_name"],
                run_context["tool_name"],
                run_context["run_mode"],
                run_context["execution_scope"],
                "running",
                None,
                1,
                0,
                run_context["input_rows"],
                0,
                0,
                run_context["created_date"],
                run_context["created_time"],
                run_context["started_at"]
            )
        )
        conn.commit()

    return run_context


def finalize_page_execution_context(run_context, output_df=None, duration_ms=0, status="success", error_message="",
                                    log_messages=None):
    initialize_execution_log_store()

    finished_at = dt_datetime.now()
    output_rows = count_dataframe_rows(output_df)
    output_columns = count_dataframe_columns(output_df)
    activity_id = f"act_{int(time.time() * 1000)}"

    with sqlite3.connect(get_execution_log_db_path()) as conn:
        conn.execute(
            """
            INSERT INTO execution_step_logs (run_id, activity_id, execution_id, project_name, user_name, page_name,
                                             execution_scope,
                                             event_type, step_index, step_id, tool_name, input_dataset_id,
                                             input_dataset_name, input_rows, input_columns,
                                             output_rows, output_columns, duration_ms, status, error_message,
                                             created_date, created_time,
                                             started_at, finished_at, log_messages_json)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                run_context["run_id"],
                activity_id,
                run_context["execution_id"],
                run_context["project_name"],
                run_context["user_name"],
                run_context["page_name"],
                run_context["execution_scope"],
                "page_execution",
                1,
                str(run_context.get("step_id") or "manual_step"),
                run_context["tool_name"],
                str(run_context.get("source_dataset_id") or "manual_input"),
                str(run_context.get("input_dataset_name") or "Manual Input Dataset"),
                run_context["input_rows"],
                run_context["input_columns"],
                output_rows,
                output_columns,
                round(float(duration_ms or 0), 2),
                status,
                str(error_message or ""),
                run_context["created_date"],
                run_context["created_time"],
                run_context["started_at"],
                finished_at.isoformat(),
                json.dumps(log_messages or [], ensure_ascii=False)
            )
        )
        conn.execute(
            """
            UPDATE execution_runs
            SET status            = ?,
                failed_steps      = ?,
                total_output_rows = ?,
                total_duration_ms = ?,
                finished_at       = ?
            WHERE run_id = ?
            """,
            (
                status,
                0 if str(status).lower() == "success" else 1,
                output_rows,
                round(float(duration_ms or 0), 2),
                finished_at.isoformat(),
                run_context["run_id"]
            )
        )
        conn.commit()


def log_page_execution(page_name, tool_name, execution_scope, input_df, output_df, source_dataset_id=None,
                       duration_ms=0, status="success", error_message="", log_messages=None):
    run_context = create_page_execution_context(
        page_name=page_name,
        tool_name=tool_name,
        execution_scope=execution_scope,
        input_df=input_df,
        source_dataset_id=source_dataset_id
    )
    finalize_page_execution_context(
        run_context,
        output_df=output_df,
        duration_ms=duration_ms,
        status=status,
        error_message=error_message,
        log_messages=log_messages
    )


def load_execution_run_history_dataframe(project_name=None, user_name=None, page_name=None, status=None, limit=200):
    initialize_execution_log_store()

    filters = []
    params = []
    if project_name:
        filters.append("project_name = ?")
        params.append(project_name)
    if user_name:
        filters.append("user_name = ?")
        params.append(user_name)
    if page_name:
        filters.append("page_name = ?")
        params.append(page_name)
    if status:
        filters.append("status = ?")
        params.append(status)

    where_sql = f"WHERE {' AND '.join(filters)}" if filters else ""
    query = f"""
        SELECT
            run_id,
            execution_id,
            project_name,
            user_name,
            page_name,
            tool_name,
            run_mode,
            execution_scope,
            status,
            requested_step_index,
            step_count,
            failed_steps,
            total_input_rows,
            total_output_rows,
            total_duration_ms,
            created_date,
            created_time,
            started_at,
            finished_at
        FROM execution_runs
        {where_sql}
        ORDER BY started_at DESC
        LIMIT ?
    """
    params.append(int(limit))

    with sqlite3.connect(get_execution_log_db_path()) as conn:
        return pd.read_sql_query(query, conn, params=params)


def load_execution_history_dataframe(project_name=None, user_name=None, page_name=None, tool_name=None, status=None,
                                     run_id=None, limit=200):
    initialize_execution_log_store()

    filters = []
    params = []
    if project_name:
        filters.append("project_name = ?")
        params.append(project_name)
    if user_name:
        filters.append("user_name = ?")
        params.append(user_name)
    if page_name:
        filters.append("page_name = ?")
        params.append(page_name)
    if tool_name:
        filters.append("tool_name = ?")
        params.append(tool_name)
    if status:
        filters.append("status = ?")
        params.append(status)
    if run_id:
        filters.append("run_id = ?")
        params.append(run_id)

    where_sql = f"WHERE {' AND '.join(filters)}" if filters else ""
    query = f"""
        SELECT
            run_id,
            activity_id,
            execution_id,
            project_name,
            user_name,
            page_name,
            execution_scope,
            event_type,
            step_index AS step_number,
            step_id,
            tool_name,
            input_dataset_id,
            input_dataset_name,
            input_rows,
            input_columns,
            output_rows,
            output_columns,
            duration_ms,
            status,
            error_message,
            created_date,
            created_time,
            started_at,
            finished_at
        FROM execution_step_logs
        {where_sql}
        ORDER BY log_id DESC
        LIMIT ?
    """
    params.append(int(limit))

    with sqlite3.connect(get_execution_log_db_path()) as conn:
        return pd.read_sql_query(query, conn, params=params)


def summarize_execution_history_by_tool(history_df):
    if not isinstance(history_df, pd.DataFrame) or history_df.empty:
        return pd.DataFrame()

    summary_df = (
        history_df.groupby(["project_name", "user_name", "page_name", "tool_name"], dropna=False)
        .agg(
            execution_count=("tool_name", "size"),
            failed_count=("status", lambda series: int((series.astype(str).str.lower() != "success").sum())),
            total_input_rows=("input_rows", "sum"),
            total_output_rows=("output_rows", "sum"),
            avg_duration_ms=("duration_ms", "mean"),
            max_duration_ms=("duration_ms", "max")
        )
        .reset_index()
    )
    summary_df["avg_duration_ms"] = summary_df["avg_duration_ms"].round(2)
    summary_df["max_duration_ms"] = summary_df["max_duration_ms"].round(2)
    return summary_df.sort_values(
        by=["failed_count", "max_duration_ms", "execution_count"],
        ascending=[False, False, False]
    )


def upload_log_dataframe_to_database(log_df, upload_config):
    if not isinstance(log_df, pd.DataFrame) or log_df.empty:
        return False, "No execution log rows are available to upload."

    table_name = str(upload_config.get("table", "")).strip()
    if not table_name:
        return False, "Target table name is required."

    engine = build_sqlalchemy_engine_from_config(upload_config)
    log_df.to_sql(table_name, engine, if_exists=upload_config.get("write_mode", "append"), index=False)
    return True, f"Uploaded {len(log_df):,} execution log row(s) to table '{table_name}'."


def render_saved_configuration_catalog():
    manager = get_enhanced_config_manager()

    # ✅ Read-only: dataset catalog build must NOT mutate reconciliation state
    build_workflow_dataset_catalog()

    with st.expander("📚 Saved Configurations in Project", expanded=False):
        tab1, tab2, tab3 = st.tabs(["📄 Pages", "🗄️ Databases", "🔗 Datasets"])

        # --------------------------------------------------
        # 📄 Pages
        # --------------------------------------------------
        with tab1:
            page_configs = st.session_state.get("page_runtime_configs", {})

            if page_configs:
                for page_key, runtime in page_configs.items():
                    page_name = runtime.get("page_name") or page_key
                    tool_name = runtime.get("tool_name", page_key)

                    with st.expander(page_name, expanded=False):
                        st.caption(f"Tool: {tool_name}")

                        # ✅ Safe rendering of used columns
                        used_columns = runtime.get("used_columns", [])
                        safe_used_columns = [
                            str(c) for c in used_columns
                            if isinstance(c, str) and c.strip()
                        ]

                        st.caption(
                            "Columns: "
                            + (
                                ", ".join(safe_used_columns[:10])
                                if safe_used_columns
                                else "No column-specific settings"
                            )
                        )

                        # ✅ Safe rendering of migration report (NO mutation)
                        report = runtime.get("migration_report", {})
                        unmatched = report.get("unmatched", [])

                        safe_unmatched = [
                            str(x) for x in unmatched
                            if isinstance(x, str) and x.strip()
                        ]

                        if safe_unmatched:
                            st.warning(
                                "Columns needing review: "
                                + ", ".join(safe_unmatched[:10])
                            )
            else:
                st.info("No page configurations saved yet.")

        # --------------------------------------------------
        # 🗄️ Databases
        # --------------------------------------------------
        with tab2:
            db_manager = manager.db_manager

            if db_manager and db_manager.profiles:
                for profile_name in db_manager.list_profiles():
                    profile = db_manager.get_profile(profile_name)

                    with st.expander(profile_name, expanded=False):
                        st.caption(
                            f"{profile.db_type} | "
                            f"{profile.host}:{profile.port} | "
                            f"{profile.database}"
                        )

                        saved_query = profile.saved_queries.get("default")
                        if saved_query:
                            st.code(saved_query, language="sql")
            else:
                st.info("No saved database profiles yet.")

        # --------------------------------------------------
        # 🔗 Datasets
        # --------------------------------------------------
        with tab3:
            dataset_catalog = st.session_state.get("workflow_dataset_catalog", {})

            if dataset_catalog:
                dataset_rows = []

                for dataset_id, meta in dataset_catalog.items():
                    dataset_rows.append({
                        "Dataset": meta.get("label", dataset_id),
                        "Rows": meta.get("row_count", 0),
                        "Columns": len(meta.get("columns", [])),
                        "Page": meta.get("page_name", ""),
                        "Tool": meta.get("tool_name", "")
                    })

                st.dataframe(
                    pd.DataFrame(dataset_rows),
                    use_container_width=True,
                    hide_index=True
                )
            else:
                st.info("No reusable datasets registered yet.")


