# 1️⃣ Resolve active dataframe safely
def get_active_dataframe():
    """
    Safely resolve the active dataframe for Copilot across all pages.
    """
    if "main_df" in st.session_state and st.session_state["main_df"] is not None:
        return st.session_state["main_df"]

    if "current_df" in st.session_state and st.session_state["current_df"] is not None:
        return st.session_state["current_df"]

    return None


# 2️⃣ Prompt size guard
MAX_PROMPT_CHARS = 5000

def clamp_prompt(text: str) -> str:
    return text[:MAX_PROMPT_CHARS]


def ask_ai(prompt: str, model_name: str):
    model = normalize_ollama_model(model_name)
    payload = {
        "model": model,
        "prompt": clamp_prompt(prompt),
        "stream": True,          # ✅ critical
        "num_predict": 120,
        "temperature": 0.2,
        "num_ctx": 1024,
    }

    try:
        r = requests.post(
            OLLAMA_URL, json=payload, stream=True, timeout=120
        )
        tokens = []
        for line in r.iter_lines():
            if not line:
                continue
            try:
                chunk = json.loads(line.decode("utf-8"))
                if "response" in chunk:
                    tokens.append(chunk["response"])
            except Exception:
                pass
        return "".join(tokens).strip()

    except requests.exceptions.Timeout:
        return (
            "⚠️ The local AI model took too long to respond.\n\n"
            "Tip: Streaming is enabled; if this persists, see CPU/AV steps below."
        )


# 4️⃣ Lightweight prompt builder (small datasets friendly)
def build_light_ai_prompt(df, user_query):
    if df is None or df.empty:
        return f"""
You are an AI Data Assistant.

User question:
{user_query}

No dataset is currently loaded.
"""

    col_preview = ", ".join(df.columns[:15])
    if len(df.columns) > 15:
        col_preview += ", ..."

    return f"""
You are an AI Data Analyst.

Dataset overview:
- Rows: {len(df)}
- Columns ({len(df.columns)}): {col_preview}

User question:
{user_query}

Respond concisely in plain English.
"""

