@st.cache_data(show_spinner=False)
def profile_data(df):
    n = len(df)
    if n == 0:
        return pd.DataFrame(columns=["Column", "Datatype", "Missing %", "Unique %"])
    return pd.DataFrame({
        "Column": df.columns.tolist(),
        "Datatype": [str(df[c].dtype) for c in df.columns],
        "Missing %": [round(df[c].isna().mean() * 100, 2) for c in df.columns],
        "Unique %": [round(df[c].nunique() / n * 100, 2) for c in df.columns],
    })


