# CORE VALIDATION ENGINES (Requirement 1, 2, 3)
# =========================================================
def build_validation_summary(val_name, var_name, total, failed):
    passed = total - failed
    rate = round((failed / total) * 100, 2) if total > 0 else 0
    return {
        "VALIDATION_CHECKS": val_name, "VARIABLE_NAME": var_name,
        "TOTAL_DATA_POINTS_VALIDATED": total, "PASSED_DATA_POINTS": passed,
        "FAILED_DATA_POINTS": failed, "FAIL_RATE(%)": rate
    }


# ---------------------------------------------------------
# DATA QUALITY SCORECARD
# ---------------------------------------------------------
def calculate_dataset_completeness(df):
    """
    Dataset-level completeness based on missing CELLS.

    Completeness (%) = 100 - (Total missing cells / Total cells) * 100
    """
    if df is None or df.empty:
        return 100.0

    total_cells = df.size
    if total_cells == 0:
        return 100.0

    missing_cells = df.isna().sum().sum()
    completeness_pct = 100 - (missing_cells / total_cells) * 100

    return round(completeness_pct, 2)

def calculate_dataset_uniqueness_from_duplicates(df):
    """
    Dataset-level uniqueness based on duplicate CELLS.

    Uniqueness (%) = 100 - (Total duplicate cells / Total cells) * 100
    """
    if df is None or df.empty:
        return 100.0

    total_rows, total_cols = df.shape
    total_cells = total_rows * total_cols

    if total_cells == 0:
        return 100.0

    duplicate_cells = 0

    for col in df.columns:
        series = df[col]
        total_non_null = series.notna().sum()
        distinct_non_null = series.nunique(dropna=True)
        duplicate_cells += max(total_non_null - distinct_non_null, 0)

    duplication_pct = (duplicate_cells / total_cells) * 100
    return round(100 - duplication_pct, 2)

@st.cache_data(show_spinner=False)
def data_quality_scorecard(df, cols=None, rules_config=None):
    """
    Generates a Data Quality scorecard.
    - Column-wise logic remains unchanged (handled elsewhere).
    - Dataset Uniqueness = (duplicate cells / total cells) * 100
    """

    # -------------------------------
    # Apply column filter safely
    # -------------------------------
    if cols:
        df = df[cols]

    # -------------------------------
    # Guard clause
    # -------------------------------
    if df is None or df.empty:
        return pd.Data[cols]
    # -------------------------------
    total_cells = df.size
    missing = df.isna().sum().sum()
    row_duplicates = df.duplicated().sum()
    len_df = len(df)

    # ✅ Dataset-level completeness (cell-based)
    completeness = calculate_dataset_completeness(df)

    # ✅ Dataset-level uniqueness (cell-based)
    dataset_uniqueness = calculate_dataset_uniqueness_from_duplicates(df)

    # -------------------------------
    # Default baseline metrics
    # -------------------------------
    default_scores = {
        "Completeness": round(completeness, 2),
        "Consistency": round(completeness * 0.95, 2),
        "Validity": round(completeness * 0.95, 2),
        "Uniqueness": round(dataset_uniqueness, 2),
        "Accuracy": 90.0
    }

    # -------------------------------
    # Safe evaluation environment
    # -------------------------------
    local_env = {
        "completeness": completeness,
        "uniqueness": dataset_uniqueness,
        "missing": missing,
        "row_duplicates": row_duplicates,
        "total_cells": total_cells,
        "len_df": len_df
    }

    final_metrics = {}

    # -------------------------------
    # Apply rule overrides (if any)
    # -------------------------------
    for metric, base_value in default_scores.items():
        if rules_config and rules_config.get(metric):
            try:
                final_metrics[metric] = round(
                    float(eval(rules_config[metric], {"__builtins__": None}, local_env)),
                    2
                )
            except Exception:
                final_metrics[metric] = base_value
        else:
            final_metrics[metric] = base_value

    # -------------------------------
    # Add custom indicators (optional)
    # -------------------------------
    if rules_config:
        for metric, expr in rules_config.items():
            if metric not in default_scores and expr:
                try:
                    final_metrics[metric] = round(
                        float(eval(expr, {"__builtins__": None}, local_env)),
                        2
                    )
                except Exception:
                    final_metrics[metric] = 0.0

    # -------------------------------
    # Output scorecard
    # -------------------------------
    return pd.DataFrame({
        "Metric": list(final_metrics.keys()),
        "Score": list(final_metrics.values())
    })

    return scorecard


import numpy as np
import pandas as pd
import re
from io import BytesIO


# =========================================================
# MISSING CHECKS
# =========================================================

@st.cache_data(show_spinner=False)
def missing_checks(df, cols, key_cols=None):
    """
    Performs missing checks on specified columns.
    NOTE: For performance, only processes first 10,000 rows on large datasets.

    Returns:
    --------
    tuple (pd.DataFrame, pd.DataFrame)
        1. Summary Validation DataFrame
        2. Detailed Failures DataFrame containing key columns, 'Variable Name', 'Value', and 'Reason'.
    """
    # Row limiting for performance on large datasets
    MAX_ROWS_TO_CHECK = 10000
    total_records = len(df)
    rows_to_check = min(total_records, MAX_ROWS_TO_CHECK)

    # Inform user when sampling is applied
    if total_records > MAX_ROWS_TO_CHECK:
        st.info(
            f"ℹ️ For performance reasons, this validation was performed "
            f"on the first {rows_to_check:,} records "
            f"out of {total_records:,} total rows."
        )

    # Process only a sample for performance if dataset is large
    check_df = df.iloc[:rows_to_check].copy() if total_records > MAX_ROWS_TO_CHECK else df.copy()

    rows = []
    summary = []

    # Standardize tracking key columns to prevent index/slicing errors
    if key_cols is None:
        key_cols = []
    elif isinstance(key_cols, str):
        key_cols = [key_cols]

    for col in cols:
        # Verify column exists
        if col not in check_df.columns:
            continue

        # 1. Calculate and isolate failed records
        is_missing = check_df[col].isna()
        failed_count = is_missing.sum()

        if failed_count > 0:
            # Safely slice out only the user's requested identity key columns
            # Use .loc to ensure proper column and row selection
            # Preserve original column order from df
            cols_to_include = [c for c in check_df.columns if c in key_cols or c == col]
            detail_rows = check_df.loc[is_missing, cols_to_include].copy().reset_index(drop=True)

            # Map the evaluated validation features to dynamic rows
            detail_rows["Variable Name"] = col
            detail_rows["Value"] = detail_rows.loc[:, col]  # Capture missing values (NaN)
            detail_rows["Reason"] = f"Missing value detected in column '{col}'"

            rows.append(detail_rows)

        # 2. Append standard operational tracking stats
        summary.append(
            build_validation_summary(
                "Missing Check",
                col,
                total_records,
                failed_count
            )
        )

    # 3. Consolidate detailed failures matching requested layout
    ordered_cols = key_cols + ["Variable Name", "Value", "Reason"]
    if rows:
        detailed_df = pd.concat(rows, ignore_index=True)
        detailed_df = detailed_df[ordered_cols]
    else:
        detailed_df = pd.DataFrame(columns=ordered_cols)

    return pd.DataFrame(summary), detailed_df


# =========================================================
# DUPLICATE CHECKS (UPDATED FOR DASHBOARD COMPATIBILITY)
# =========================================================

@st.cache_data(show_spinner=False)
def duplicate_checks(df, key_cols, check_cols):
    """
    Checks for duplicates based ONLY on check columns.
    Key columns stay as columns (if provided) for context; check columns are transposed to rows.
    NOTE: For performance, only processes first 10,000 rows on large datasets.
    """
    # Row limiting for performance on large datasets
    MAX_ROWS_TO_CHECK = 10000
    total_records = len(df)
    rows_to_check = min(total_records, MAX_ROWS_TO_CHECK)

    # Inform user when sampling is applied
    if total_records > MAX_ROWS_TO_CHECK:
        st.info(
            f"ℹ️ For performance reasons, this validation was performed "
            f"on the first {rows_to_check:,} records "
            f"out of {total_records:,} total rows."
        )

    # Process only a sample for performance if dataset is large
    check_df = df.iloc[:rows_to_check].copy() if total_records > MAX_ROWS_TO_CHECK else df.copy()

    rows = []
    summary = []

    # Only check_cols is strictly required now; key_cols is fully optional
    if not check_cols:
        return pd.DataFrame(), pd.DataFrame()

    # Normalize key_cols to a list if None is passed
    if key_cols is None:
        key_cols = []

    # Isolate needed columns to avoid off-by-one errors with Alteryx files
    # CRITICAL: Preserve original column order from df, not from our list
    cols_needed = list(key_cols) + list(check_cols)
    cols_needed_set = set(cols_needed)

    # Select only columns that exist, but preserve their original order in df
    cols_to_select = [c for c in check_df.columns if c in cols_needed_set]

    # Create working subset with preserved column order
    working_subset = check_df[cols_to_select].copy().reset_index(drop=True)

    # Verify all check columns exist in the subset
    missing_check_cols = [c for c in check_cols if c not in working_subset.columns]
    if missing_check_cols:
        # If columns are missing, fall back to checking all available columns
        check_cols = [c for c in check_cols if c in working_subset.columns]
        if not check_cols:
            return pd.DataFrame(), pd.DataFrame()

    # -----------------------------------------------------
    # DUPLICATE DETECTION (UPDATED: Ignores key_cols for subset)
    # -----------------------------------------------------
    duplicate_mask = working_subset.duplicated(
        subset=check_cols,  # Only look for duplicates within the check variables
        keep=False
    )

    duplicate_rows = working_subset[duplicate_mask].copy()
    failed_count = len(duplicate_rows)

    # -----------------------------------------------------
    # DETAILS (Keeps key_cols as distinct columns if present)
    # -----------------------------------------------------
    ordered_cols = key_cols + ["Variable Name", "Value", "Reason"]

    if not duplicate_rows.empty:
        # Melt targeted check columns. If key_cols is empty, it melts globally across check_cols.
        melted_df = pd.melt(
            duplicate_rows,
            id_vars=key_cols if key_cols else None,
            value_vars=check_cols,
            var_name="Variable Name",
            value_name="Value"
        )

        # Build dynamic Reason column supporting optional or missing key configs
        if key_cols:
            melted_df["Reason"] = melted_df.apply(
                lambda row: (
                    f"Duplicate found for Variable check scope. Context keys: "
                    f"{', '.join([f'{k}={row[k]}' for k in key_cols])} | "
                    f"Variable: {row['Variable Name']}={row['Value']}"
                ),
                axis=1
            )
        else:
            melted_df["Reason"] = melted_df.apply(
                lambda row: f"Duplicate found for checked variables: {row['Variable Name']}={row['Value']}",
                axis=1
            )

        # Enforce exact column order: Keys first (if any), then standard fields
        details_df = melted_df[ordered_cols]
    else:
        details_df = pd.DataFrame(columns=ordered_cols)

    # -----------------------------------------------------
    # SUMMARY (SYNCHRONIZED WITH INSIGHTS METRICS & CHARTS)
    # -----------------------------------------------------
    summary.append(
        {
            "VALIDATION_CHECKS": "Duplicate Check",
            "KEY_COLUMNS": ", ".join(key_cols) if key_cols else "None Selected",
            "CHECKED_COLUMNS": ", ".join(check_cols),
            "TOTAL_DATA_POINTS_VALIDATED": total_records,
            "PASSED_DATA_POINTS": (total_records - failed_count),
            "FAILED_DATA_POINTS": failed_count,
            "FAIL_RATE(%)": round(
                (failed_count / total_records) * 100, 2
            ) if total_records > 0 else 0
        }
    )

    return pd.DataFrame(summary), details_df


