EMAIL_PATTERN = r"^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$"

PHONE_PATTERN = (
    r"^(\+971|971|0)?"
    r"((50|52|54|55|56|58)[0-9]{7}|"
    r"(2|3|4|6|7|9)[0-9]{7})$"
)

EMIRATES_ID_PATTERN = r"^784-\d{4}-\d{7}-\d$"

LICENSE_PATTERN = r"^[\w\-\/]{5,50}$"

# UAE bounding box (generous, includes all Emirates + offshore waters)
