# ---------------------------------------------------------
# EMAIL DETECTION  (detailed, user-friendly reasons)
# ---------------------------------------------------------

def detect_email_issue(email):
    """Returns a descriptive validation failure reason, or None if valid."""
    if pd.isna(email):
        return None

    raw = str(email).strip()
    lower = raw.lower()

    if not raw:
        return "Email Validation — Value is empty"

    if " " in raw:
        return "Email Validation — Contains spaces (spaces are not allowed in email addresses)"

    if raw.count("@") == 0:
        return "Email Validation — Missing '@' symbol (every email must contain exactly one @)"

    if raw.count("@") > 1:
        return "Email Validation — Multiple '@' symbols found (only one is allowed)"

    name, domain = lower.split("@", 1)

    if not name:
        return "Email Validation — Local part (before @) is empty"

    if name.startswith(".") or name.endswith("."):
        return "Email Validation — Local part starts or ends with a dot, which is not allowed"

    if ".." in name:
        return "Email Validation — Local part contains consecutive dots (..)"

    if not domain:
        return "Email Validation — Domain part (after @) is empty"

    if domain in EMAIL_TYPOS:
        suggestion = EMAIL_TYPOS[domain]
        return f"Email Validation — Likely domain typo: '{domain}' (did you mean '{suggestion}'?)"

    if "." not in domain:
        return "Email Validation — Domain has no top-level extension (e.g. missing '.com')"

    if domain.startswith(".") or domain.endswith("."):
        return "Email Validation — Domain starts or ends with a dot"

    if ".." in domain:
        return "Email Validation — Domain contains consecutive dots (..)"

    tld = domain.rsplit(".", 1)[-1]
    if len(tld) < 2:
        return f"Email Validation — Top-level domain '{tld}' is too short (minimum 2 characters)"

    if not re.match(EMAIL_PATTERN, lower):
        return f"Email Validation — Does not match expected email format (value: '{raw}')"

    return None


# ---------------------------------------------------------
# PHONE VALIDATION  (detailed reasons)
# ---------------------------------------------------------

def normalize_phone(phone):
    if pd.isna(phone):
        return phone
    phone = re.sub(r"\D", "", str(phone))
    if phone.startswith("971"):
        phone = "0" + phone[3:]
    if len(phone) == 9:
        phone = "0" + phone
    return phone


def detect_phone_issue(phone):
    """Returns a descriptive validation failure reason, or None if valid."""
    if pd.isna(phone):
        return None

    raw = str(phone).strip()

    if not raw:
        return "Phone Validation — Value is empty"

    # Handle decimal format: convert .0 to integer, reject .1-.9
    if '.' in raw:
        parts = raw.split('.')
        if len(parts) != 2:
            return f"Phone Validation — Invalid decimal format (value: '{raw}')"

        decimal_part = parts[1].strip()
        if not decimal_part:
            return f"Phone Validation — Invalid decimal format: no digits after decimal point (value: '{raw}')"

        # If decimal part contains only zeros (e.g., ".0", ".00"), convert to integer
        if all(c == '0' for c in decimal_part if c.isdigit()):
            raw = parts[0].strip()  # Use only the integer part
        else:
            # If decimal part has digits 1-9, reject it - phone numbers shouldn't have decimals
            return f"Phone Validation — Invalid format: phone numbers cannot have decimal digits (.1-.9) (value: '{raw}')"

    digits_raw = re.sub(r"\D", "", raw)

    # Check for letters mixed in
    if re.search(r"[A-Za-z]", raw):
        return f"Phone Validation — Contains letters which are not allowed in a phone number (value: '{raw}')"

    # Normalise
    norm = normalize_phone(raw)
    digits = re.sub(r"\D", "", str(norm))

    if len(digits) == 0:
        return "Phone Validation — No numeric digits found"

    # UAE mobile prefixes: 050, 052, 054, 055, 056, 058
    # UAE landline area codes: 02, 03, 04, 06, 07, 09
    mobile_prefixes = ("050", "052", "054", "055", "056", "058")
    landline_prefixes = ("02", "03", "04", "06", "07", "09")

    if len(digits) == 10:
        prefix3 = digits[:3]
        prefix2 = digits[:2]
        if prefix3 in mobile_prefixes:
            pass  # looks correct, fall through to full regex
        elif prefix2 in landline_prefixes:
            pass
        else:
            return (
                f"Phone Validation — Unrecognised UAE prefix '{prefix3}'. "
                f"Expected mobile (050/052/054/055/056/058) or landline (02/03/04/06/07/09)"
            )
    elif len(digits) < 9:
        return (
            f"Phone Validation — Too short ({len(digits)} digits). "
            f"UAE numbers require 9 digits (without country code) or 10 digits (with leading 0)"
        )
    elif len(digits) > 12:
        return (
            f"Phone Validation — Too long ({len(digits)} digits). "
            f"UAE numbers should not exceed 12 digits including country code"
        )

    if not re.match(PHONE_PATTERN, norm):
        return (
            f"Phone Validation — Does not match UAE phone format. "
            f"Valid formats: +971XXXXXXXXX, 971XXXXXXXXX, 0XXXXXXXXX (value: '{raw}')"
        )

    return None


# ---------------------------------------------------------
# EMIRATES ID VALIDATION  (pattern + Luhn Algorithm)
# ---------------------------------------------------------

def _luhn_check(digits_str):
    """
    Standard Luhn Algorithm.
    Returns True if the digit string satisfies the Luhn check.
    """
    total = 0
    reverse_digits = digits_str[::-1]
    for i, ch in enumerate(reverse_digits):
        n = int(ch)
        if i % 2 == 1:  # every second digit from the right (0-indexed)
            n *= 2
            if n > 9:
                n -= 9
        total += n
    return total % 10 == 0


def detect_emirates_id_issue(eid):
    """
    Validates Emirates ID with layered checks:
      1. Empty / null
      2. Format pattern: 784-YYYY-NNNNNNN-C
      3. Country code must be 784 (UAE)
      4. Luhn Algorithm check on all 15 digits
    Returns a descriptive reason string, or None if valid.
    """
    if pd.isna(eid):
        return None

    raw = str(eid).strip()

    if not raw:
        return "Emirates ID Validation — Value is empty"

    # Step 1: overall pattern
    if not re.match(EMIRATES_ID_PATTERN, raw):
        # Give specific guidance on which part is wrong
        parts = raw.split("-")
        if len(parts) != 4:
            return (
                f"Emirates ID Validation — Incorrect number of segments "
                f"(expected 4 separated by '-', got {len(parts)}) — value: '{raw}'"
            )
        cc, yr, num, chk = parts
        if cc != "784":
            return (
                f"Emirates ID Validation — Invalid country code '{cc}' "
                f"(UAE Emirates IDs must start with '784')"
            )
        if not yr.isdigit() or len(yr) != 4:
            return (
                f"Emirates ID Validation — Birth year segment '{yr}' must be exactly 4 digits"
            )
        if not num.isdigit() or len(num) != 7:
            return (
                f"Emirates ID Validation — Personal number segment '{num}' must be exactly 7 digits"
            )
        if not chk.isdigit() or len(chk) != 1:
            return (
                f"Emirates ID Validation — Check digit '{chk}' must be a single digit"
            )
        return (
            f"Emirates ID Validation — Does not match required format 784-YYYY-NNNNNNN-C "
            f"(value: '{raw}')"
        )

    # Step 2: extract all 15 digits for Luhn check
    digits_only = raw.replace("-", "")
    if not digits_only.isdigit() or len(digits_only) != 15:
        return (
            f"Emirates ID Validation — Expected 15 numeric digits after removing hyphens, "
            f"got '{digits_only}'"
        )

    # Step 3: Luhn Algorithm
    if not _luhn_check(digits_only):
        return (
            f"Emirates ID Validation — Failed Luhn Algorithm check digit verification "
            f"(the check digit '{digits_only[-1]}' is incorrect for the given ID number)"
        )

    return None


# ---------------------------------------------------------
# GEOGRAPHIC COORDINATE VALIDATION  (UAE region)
# ---------------------------------------------------------

def detect_coordinate_issue(value, coord_type):
    """
    Robust coordinate validator.
    Same functionality, but safe for large datasets and mixed types.
    """
    if value is None or pd.isna(value):
        return None

    try:
        # Normalize numeric strings safely
        if isinstance(value, str):
            value = value.strip().replace(",", "")
        v = float(value)
    except Exception:
        return "Coordinate is not numeric"

    if coord_type == "longitude":
        if not (UAE_LON_MIN <= v <= UAE_LON_MAX):
            return f"Longitude outside UAE bounds ({UAE_LON_MIN}–{UAE_LON_MAX})"

    if coord_type == "latitude":
        if not (UAE_LAT_MIN <= v <= UAE_LAT_MAX):
            return f"Latitude outside UAE bounds ({UAE_LAT_MIN}–{UAE_LAT_MAX})"

    return None


# ---------------------------------------------------------
# COLUMN-TYPE AUTO-DETECTOR
# (used to pre-select relevant columns in the UI)
# ---------------------------------------------------------

def _detect_validation_type(col_name):
    """
    Returns the validation type inferred from column name, or None.
    Order matters: check more-specific patterns first.
    """
    c = str(col_name).strip().lower()
    compact_c = c.replace(" ", "")
    if "email" in c or "e-mail" in c or "mail" in c:
        return "email"
    if "phone" in c or "mobile" in c or "tel" in c or "cell" in c:
        return "phone"
    if "emirates" in c or " eid" in c or c == "eid" or "national_id" in c:
        return "emirates_id"
    if (
            "license" in c
            or "licence" in c
            or c.endswith("_lic")
            or c.endswith("_license")
            or c.endswith("_licence")
    ):
        return "license"
    # Enterprise/Establishment prefixed identifiers and coordinates
    if compact_c.startswith("enterprise_") or compact_c.startswith("establishment_"):
        tail = compact_c.split("_", 1)[1] if "_" in compact_c else ""
        if tail.startswith(("id", "license", "licence", "lic")):
            return "license"
        if tail.startswith(("x", "lon", "long", "longitude", "xcoord", "x_coord", "easting")):
            return "longitude"
        if tail.startswith(("y", "lat", "latitude", "ycoord", "y_coord", "northing")):
            return "latitude"
    # Coordinate / geography detection
    if c in ("x", "lon", "longitude", "x_coord", "xcoord", "easting", "long", "establishment_x", "enterprise_x"):
        return "longitude"
    if c in ("y", "lat", "latitude", "y_coord", "ycoord", "northing", "establishment_y", "enterprise_y"):
        return "latitude"
    if "longitude" in c or "x_coord" in c or "easting" in c:
        return "longitude"
    if "latitude" in c or "y_coord" in c or "northing" in c:
        return "latitude"
    return None


def auto_detect_validation_columns(all_columns):
    """Returns list of column names that match a known validation type."""
    return [c for c in all_columns if _detect_validation_type(c) is not None]


# =========================================================
# INVALID FORMAT CHECKS
# =========================================================

@st.cache_data(show_spinner=False)
def invalid_format_checks(df, key_cols, check_cols):
    """
    Checks for structural / logical format issues across target columns.
    Supported validation types (auto-detected from column name):
      - Email               → pattern + domain typo check
      - Phone / Mobile      → UAE format + prefix + length check
      - Emirates ID         → pattern + Luhn Algorithm check
      - License / Licence   → alphanumeric length check
      - Longitude / X       → UAE bounding box (51.0 – 56.5° E)
      - Latitude  / Y       → UAE bounding box (22.5 – 26.5° N)
    Key columns stay intact as columns; check columns with issues become rows.
    NOTE: For performance, only processes first 10,000 rows on large datasets.
    """
    # Row limiting for performance on large datasets
    MAX_ROWS_TO_CHECK = 10000
    # 🔥 Numeric coercion once instead of per-row
    for col in check_cols:
        vtype = _detect_validation_type(col)
        if vtype in ("longitude", "latitude"):
            working_df[col] = pd.to_numeric(
                working_df[col].astype(str).str.replace(",", ""),
                errors="coerce"
            )
    total_records = len(df)
    rows_to_check = min(total_records, MAX_ROWS_TO_CHECK)

    # Inform user when sampling is applied
    if total_records > MAX_ROWS_TO_CHECK:
        st.info(
            f"ℹ️ For performance reasons, Invalid Format validation "
            f"was performed on the first {rows_to_check:,} records "
            f"out of {total_records:,} total rows."
        )

    # Process only a sample for performance if dataset is large
    check_df = df.iloc[:rows_to_check].copy() if total_records > MAX_ROWS_TO_CHECK else df.copy()
    check_df = stabilize_alteryx_mapping(normalize_dataframe_alignment(check_df))

    rows = []
    summary = []
    validated_columns = []

    if not check_cols:
        return pd.DataFrame(), pd.DataFrame(), validated_columns

    base_keys = list(key_cols) if key_cols else []
    available_columns = list(check_df.columns)
    resolved_base_keys = [k for k in base_keys if k in available_columns]
    final_cols = base_keys + ["Variable Name", "Value", "Reason", "Validation Type"]

    for col in check_cols:
        val_type = _detect_validation_type(col)
        if col not in available_columns:
            continue
        # Explicitly isolate a single resolved series (first match) to avoid duplicate-column ambiguity.
        selected_series = check_df.loc[:, col]
        if isinstance(selected_series, pd.DataFrame):
            selected_series = selected_series.iloc[:, 0]
        temp = check_df[resolved_base_keys].copy() if resolved_base_keys else pd.DataFrame(index=check_df.index)
        temp["__target_col__"] = selected_series
        has_issue = False

        # -------------------------------------------------
        # EMAIL
        # -------------------------------------------------
        if val_type == "email":
            validated_columns.append(col)
            temp["Reason"] = temp["__target_col__"].apply(detect_email_issue)
            invalid_rows = temp[temp["Reason"].notna()].copy()
            if not invalid_rows.empty:
                invalid_rows["Value"] = invalid_rows.loc[:, "__target_col__"].astype(str)
                invalid_rows["Validation Type"] = "Email Format"
                has_issue = True

        # -------------------------------------------------
        # PHONE / MOBILE
        # -------------------------------------------------
        elif val_type == "phone":
            validated_columns.append(col)
            temp["Reason"] = temp["__target_col__"].apply(detect_phone_issue)
            invalid_rows = temp[temp["Reason"].notna()].copy()
            if not invalid_rows.empty:
                invalid_rows["Value"] = invalid_rows.loc[:, "__target_col__"].astype(str)
                invalid_rows["Validation Type"] = "Phone Number (UAE)"
                has_issue = True

        # -------------------------------------------------
        # EMIRATES ID
        # -------------------------------------------------
        elif val_type == "emirates_id":
            validated_columns.append(col)
            temp["Reason"] = temp["__target_col__"].apply(detect_emirates_id_issue)
            invalid_rows = temp[temp["Reason"].notna()].copy()
            if not invalid_rows.empty:
                invalid_rows["Value"] = invalid_rows.loc[:, "__target_col__"].astype(str)
                invalid_rows["Validation Type"] = "Emirates ID (Pattern + Luhn)"
                has_issue = True

        # -------------------------------------------------
        # LICENSE
        # -------------------------------------------------
        elif val_type == "license":
            validated_columns.append(col)
            invalid_mask = temp["__target_col__"].notna() & ~temp["__target_col__"].astype(str).str.match(
                LICENSE_PATTERN)
            invalid_rows = temp[invalid_mask].copy()
            if not invalid_rows.empty:
                invalid_rows["Value"] = invalid_rows.loc[:, "__target_col__"].astype(str)
                invalid_rows["Reason"] = invalid_rows.loc[:, "__target_col__"].apply(
                    lambda x: (
                        f"License Validation — Value '{x}' does not match expected format. "
                        f"License codes must be 5–20 alphanumeric characters (hyphens allowed)."
                    )
                )
                invalid_rows["Validation Type"] = "License / Trade License"
                has_issue = True

        # -------------------------------------------------
        # LONGITUDE (X)
        # -------------------------------------------------
        elif val_type == "longitude":
            validated_columns.append(col)
            temp["Reason"] = temp["__target_col__"].apply(lambda v: detect_coordinate_issue(v, "longitude"))
            invalid_rows = temp[temp["Reason"].notna()].copy()
            if not invalid_rows.empty:
                invalid_rows["Value"] = invalid_rows.loc[:, "__target_col__"].astype(str)
                invalid_rows["Validation Type"] = "Longitude / X (UAE Region)"
                has_issue = True

        # -------------------------------------------------
        # LATITUDE (Y)
        # -------------------------------------------------
        elif val_type == "latitude":
            validated_columns.append(col)
            temp["Reason"] = temp["__target_col__"].apply(lambda v: detect_coordinate_issue(v, "latitude"))
            invalid_rows = temp[temp["Reason"].notna()].copy()
            if not invalid_rows.empty:
                invalid_rows["Value"] = invalid_rows.loc[:, "__target_col__"].astype(str)
                invalid_rows["Validation Type"] = "Latitude / Y (UAE Region)"
                has_issue = True

        # -------------------------------------------------
        # UNRECOGNISED — skip
        # -------------------------------------------------
        else:
            continue

        if not has_issue:
            continue

        # Initialize invalid_rows as empty DataFrame if no issues found
        invalid_rows = invalid_rows if has_issue else pd.DataFrame(columns=final_cols)
        failed_count = len(invalid_rows)

        if not invalid_rows.empty:
            invalid_rows["Variable Name"] = col
            invalid_rows = invalid_rows.drop(columns=["__target_col__"], errors="ignore")
            # Keep only columns that exist
            present_cols = [c for c in final_cols if c in invalid_rows.columns]
            rows.append(invalid_rows[present_cols])

        summary.append(
            build_validation_summary(
                "Invalid Format Check",
                col,
                total_records,
                failed_count
            )
        )

    # Combine collected issues into a single uniform details frame
    if rows:
        details_df = pd.concat(rows, ignore_index=True)
    else:
        details_df = pd.DataFrame(columns=final_cols)

    return (
        pd.DataFrame(summary),
        details_df,
        validated_columns
    )


# =========================================================
# LOGICAL CHECKS
# =========================================================

@st.cache_data(show_spinner=False)
def logical_checks(df, key_cols, cols, operator, compare_col, comparison):
    """
    Performs mathematical validation across multiple columns and compares the result.
    NOTE: For performance, only processes first 10,000 rows on large datasets.
    """
    # Row limiting for performance on large datasets
    MAX_ROWS_TO_CHECK = 10000
    total_records = len(df)
    rows_to_check = min(total_records, MAX_ROWS_TO_CHECK)

    # Inform user when sampling is applied
    if total_records > MAX_ROWS_TO_CHECK:
        st.info(
            f"ℹ️ For performance reasons, this validation was performed "
            f"on the first {rows_to_check:,} records "
            f"out of {total_records:,} total rows."
        )

    # Process only a sample for performance if dataset is large
    check_df = df.iloc[:rows_to_check].copy() if total_records > MAX_ROWS_TO_CHECK else df.copy()

    base_keys = list(key_cols) if key_cols else []
    ordered_cols = base_keys + ["Variable Name", "Value", "Status", "Reason"]

    # Isolate needed columns to avoid off-by-one errors with Alteryx files
    all_needed_cols = list(set(base_keys + cols + [compare_col]))
    # Filter to only existing columns
    all_needed_cols = [c for c in all_needed_cols if c in check_df.columns]

    # Verify all required columns exist
    missing_cols = [c for c in base_keys + cols + [compare_col] if c not in check_df.columns]
    if missing_cols:
        return pd.DataFrame(), pd.DataFrame()

    # Preserve original column order from df, not from our list
    all_needed_cols_ordered = [c for c in check_df.columns if c in set(all_needed_cols)]
    temp = check_df[all_needed_cols_ordered].copy().reset_index(drop=True)

    # -----------------------------------------------------
    # OPERATIONS LAYER
    # -----------------------------------------------------
    if operator == "SUM":
        temp["CALC"] = temp[cols].sum(axis=1)
    elif operator == "SUBTRACT":
        temp["CALC"] = temp[cols[0]]
        for c in cols[1:]:
            temp["CALC"] = temp["CALC"] - temp[c]
    elif operator == "MULTIPLY":
        temp["CALC"] = temp[cols].prod(axis=1)
    elif operator == "DIVIDE":
        temp["CALC"] = temp[cols[0]]
        for c in cols[1:]:
            denominator = temp[c].replace(0, np.nan)
            temp["CALC"] = temp["CALC"] / denominator
    else:
        temp["CALC"] = 0

    # -----------------------------------------------------
    # COMPARISON LAYER (Isolate records that pass/fail)
    # -----------------------------------------------------
    if comparison == ">":
        pass_mask = temp["CALC"] > temp[compare_col]
    elif comparison == "<":
        pass_mask = temp["CALC"] < temp[compare_col]
    elif comparison in ["=", "=="]:
        pass_mask = temp["CALC"] == temp[compare_col]
    elif comparison == "!=":
        pass_mask = temp["CALC"] != temp[compare_col]
    elif comparison == ">=":
        pass_mask = temp["CALC"] >= temp[compare_col]
    elif comparison == "<=":
        pass_mask = temp["CALC"] <= temp[compare_col]
    else:
        pass_mask = pd.Series(False, index=temp.index)

    valid = temp[pass_mask].copy()
    invalid = temp[~pass_mask].copy()

    total_records = len(df)
    failed_count = len(invalid)

    def safe_round(val):
        try:
            return round(float(val), 2)
        except (ValueError, TypeError):
            return val

    # -----------------------------------------------------
    # TRANSFORMATION FUNCTION FOR DETAILS
    # -----------------------------------------------------
    def generate_details(target_df, status_label, reason_template):
        if target_df.empty:
            return pd.DataFrame(columns=ordered_cols)

        rows_list = []
        all_involved_cols = cols + [compare_col]

        for idx, row in target_df.iterrows():
            for col in all_involved_cols:
                detail_row = {k: row[k] for k in base_keys}

                calc_val = safe_round(row['CALC'])
                comp_val = safe_round(row[compare_col])
                col_val = safe_round(row[col])

                detail_row["Variable Name"] = col
                detail_row["Value"] = col_val  # Setting the current evaluated variable value
                detail_row["Status"] = status_label
                detail_row["Reason"] = reason_template(calc_val, comp_val, col, col_val)
                rows_list.append(detail_row)

        out_df = pd.DataFrame(rows_list)
        return out_df[ordered_cols]

    # Generate details for failures
    fail_template = lambda calc, comp, c, c_val: (
        f"Logical Failure: Calculated {operator} result ({calc}) "
        f"violated constraint ({comparison}) against '{compare_col}' ({comp}). "
        f"Current value of '{c}' is {c_val}"
    )
    details_df = generate_details(invalid, "Failed", fail_template)

    # Generate details for successes
    pass_template = lambda calc, comp, c, c_val: (
        f"Logical Success: Calculated {operator} result ({calc}) "
        f"satisfied constraint ({comparison}) against '{compare_col}' ({comp}). "
        f"Current value of '{c}' is {c_val}"
    )
    pass_details_df = generate_details(valid, "Passed", pass_template)

    # -----------------------------------------------------
    # SUMMARY
    # -----------------------------------------------------
    summary = pd.DataFrame({
        "VALIDATION_CHECKS": ["Logical Check"],
        "SELECTED_COLUMNS": [", ".join(cols)],
        "OPERATION": [operator],
        "COMPARED_WITH": [compare_col],
        "COMPARISON": [comparison],
        "TOTAL_DATA_POINTS_VALIDATED": [total_records],
        "PASSED_DATA_POINTS": [total_records - failed_count],
        "FAILED_DATA_POINTS": [failed_count],
        "FAIL_RATE(%)": [round((failed_count / total_records) * 100, 2) if total_records > 0 else 0]
    })

    return summary, details_df, pass_details_df


# =========================================================
# OUTLIERS
# =========================================================

@st.cache_data(show_spinner=False)
def detect_iqr_outliers(df, key_cols, check_cols, multiplier=1.5, exclusion_query=""):
    """
    Detects outliers using the Interquartile Range (IQR) method.
    NOTE: For performance, only processes first 10,000 rows on large datasets.
    """
    # Row limiting for performance on large datasets
    MAX_ROWS_TO_CHECK = 10000
    total_records = len(df)
    rows_to_check = min(total_records, MAX_ROWS_TO_CHECK)

    # Inform user when sampling is applied
    if total_records > MAX_ROWS_TO_CHECK:
        st.info(
            f"ℹ️ For performance reasons, this validation was performed "
            f"on the first {rows_to_check:,} records "
            f"out of {total_records:,} total rows."
        )

    # Process only a sample for performance if dataset is large
    check_df = df.iloc[:rows_to_check].copy() if total_records > MAX_ROWS_TO_CHECK else df.copy()

    rows = []
    summary = []
    base_keys = list(key_cols) if key_cols else []
    ordered_cols = base_keys + ["Variable Name", "Value", "Reason"]

    for col in check_cols:
        if col not in check_df.columns or not pd.api.types.is_numeric_dtype(check_df[col]):
            continue

        Q1 = check_df[col].quantile(0.25)
        Q3 = check_df[col].quantile(0.75)
        IQR = Q3 - Q1

        lower = Q1 - multiplier * IQR
        upper = Q3 + multiplier * IQR

        # Preserve original column order from df
        cols_to_use = [c for c in check_df.columns if c in base_keys or c == col]
        temp = check_df[cols_to_use].copy().reset_index(drop=True)

        mask = (temp.loc[:, col] < lower) | (temp.loc[:, col] > upper)
        result = temp[mask].copy().reset_index(drop=True)

        if not result.empty and exclusion_query:
            try:
                exclusion_mask = result.eval(exclusion_query)
                result = result[~exclusion_mask].reset_index(drop=True)
            except Exception:
                pass

        failed_count = len(result)

        if not result.empty:
            result["Variable Name"] = col
            result["Value"] = result.loc[:, col]  # Capture the actual numerical outlier value
            result["Reason"] = result.loc[:, col].apply(
                lambda x: f"Value ({x}) is an outlier via IQR. Bounds: [{round(lower, 2)}, {round(upper, 2)}]"
            )
            rows.append(result[ordered_cols])

        # -------------------------------------------------
        # SUMMARY BLOCK
        # -------------------------------------------------
        summary.append({
            "VALIDATION_CHECKS": "IQR Outlier Check",
            "VARIABLE_NAME": col,
            "TOTAL_DATA_POINTS_VALIDATED": total_records,
            "PASSED_DATA_POINTS": total_records - failed_count,
            "FAILED_DATA_POINTS": failed_count,
            "FAIL_RATE(%)": round((failed_count / total_records) * 100, 2) if total_records > 0 else 0
        })

    details_df = pd.concat(rows, ignore_index=True) if rows else pd.DataFrame(columns=ordered_cols)
    return pd.DataFrame(summary), details_df


@st.cache_data(show_spinner=False)
def detect_zscore_outliers(df, key_cols, check_cols, threshold=3.0, exclusion_query=""):
    """
    Detects outliers using the Z-score method.
    NOTE: For performance, only processes first 10,000 rows on large datasets.
    """
    # Row limiting for performance on large datasets
    MAX_ROWS_TO_CHECK = 10000
    total_records = len(df)
    rows_to_check = min(total_records, MAX_ROWS_TO_CHECK)

    # Inform user when sampling is applied
    if total_records > MAX_ROWS_TO_CHECK:
        st.info(
            f"ℹ️ For performance reasons, this validation was performed "
            f"on the first {rows_to_check:,} records "
            f"out of {total_records:,} total rows."
        )

    # Process only a sample for performance if dataset is large
    check_df = df.iloc[:rows_to_check].copy() if total_records > MAX_ROWS_TO_CHECK else df.copy()

    rows = []
    summary = []
    base_keys = list(key_cols) if key_cols else []
    ordered_cols = base_keys + ["Variable Name", "Value", "Reason"]

    for col in check_cols:
        if col not in check_df.columns or not pd.api.types.is_numeric_dtype(check_df[col]):
            continue

        clean_series = check_df[col].dropna()
        if clean_series.empty or clean_series.std() == 0:
            summary.append({
                "VALIDATION_CHECKS": "Z-Score Outlier Check",
                "VARIABLE_NAME": col,
                "TOTAL_DATA_POINTS_VALIDATED": total_records,
                "PASSED_DATA_POINTS": total_records,
                "FAILED_DATA_POINTS": 0,
                "FAIL_RATE(%)": 0.0
            })
            continue

        z_scores_raw = (clean_series - clean_series.mean()) / clean_series.std()
        z_scores_abs = np.abs(z_scores_raw)

        # Preserve original column order from df
        cols_to_use = [c for c in df.columns if c in base_keys or c == col]
        temp = df.loc[clean_series.index, cols_to_use].copy().reset_index(drop=True)
        # Re-align z_scores with temp's reset index
        z_scores_raw_aligned = z_scores_raw.reset_index(drop=True)
        temp["_zscore"] = z_scores_raw_aligned
        z_scores_abs_aligned = z_scores_abs.reset_index(drop=True)

        mask = z_scores_abs_aligned > threshold
        result = temp[mask].copy().reset_index(drop=True)

        if not result.empty and exclusion_query:
            try:
                exclusion_mask = result.eval(exclusion_query)
                result = result[~exclusion_mask].reset_index(drop=True)
            except Exception:
                pass

        failed_count = len(result)

        if not result.empty:
            result["Variable Name"] = col
            result["Value"] = result.loc[:, col]  # Capture the numerical outlier value
            result["Reason"] = result.apply(
                lambda
                    row: f"Value ({row.loc[col]}) has an absolute Z-Score of {abs(round(row.loc['_zscore'], 2))} (Threshold: {threshold})",
                axis=1
            )
            rows.append(result[ordered_cols])

        # -------------------------------------------------
        # SUMMARY BLOCK
        # -------------------------------------------------
        summary.append({
            "VALIDATION_CHECKS": "Z-Score Outlier Check",
            "VARIABLE_NAME": col,
            "TOTAL_DATA_POINTS_VALIDATED": total_records,
            "PASSED_DATA_POINTS": total_records - failed_count,
            "FAILED_DATA_POINTS": failed_count,
            "FAIL_RATE(%)": round((failed_count / total_records) * 100, 2) if total_records > 0 else 0
        })

    details_df = pd.concat(rows, ignore_index=True) if rows else pd.DataFrame(columns=ordered_cols)
    return pd.DataFrame(summary), details_df


