# =========================================================
# COMPARISON CHECKS ENGINE
# =========================================================

def comparison_checks(
        current_df,
        comparison_df,
        compare_columns,
        right_compare_columns,
        compare_by,
        right_compare_by,
        variance_rules,
        comparison_name="Comparison Validation"
):
    rows = []
    summary_rows = []

    if not compare_by or not right_compare_by:
        return pd.DataFrame(), pd.DataFrame()

    # -----------------------------------------------------
    # SAFE CROSS-CASE INNER MERGE
    # -----------------------------------------------------
    merged = current_df.merge(
        comparison_df,
        left_on=compare_by,
        right_on=right_compare_by,
        how="inner",
        suffixes=("_CURRENT", "_REFERENCE")
    )

    total_records = len(merged)

    # -----------------------------------------------------
    # PROCESS VARIABLES
    # -----------------------------------------------------
    for col_left, col_right in zip(compare_columns, right_compare_columns):
        current_col = f"{col_left}_CURRENT"
        reference_col = f"{col_right}_REFERENCE"

        if current_col not in merged.columns or reference_col not in merged.columns:
            continue

        # -------------------------------------------------
        # CHARACTER / STRING VALIDATION
        # -------------------------------------------------
        if (
                pd.api.types.is_object_dtype(merged[current_col])
                or pd.api.types.is_string_dtype(merged[current_col])
        ):
            current_values = merged[current_col].fillna("").astype(str).str.strip().str.lower()
            reference_values = merged[reference_col].fillna("").astype(str).str.strip().str.lower()

            failed = merged[current_values != reference_values].copy()

            if not failed.empty:
                failed["VARIABLE_NAME"] = col_left
                failed["Value"] = failed[current_col]
                failed["Reason"] = failed.apply(
                    lambda row: f"Mismatch | Current='{row[current_col]}' | Reference='{row[reference_col]}'",
                    axis=1
                )

        # -------------------------------------------------
        # NUMERIC VALIDATION
        # -------------------------------------------------
        else:
            cutoff = variance_rules.get(col_left, 0.0)
            failed = merged.copy()

            failed["Variance"] = (failed[current_col] - failed[reference_col]).abs()
            failed["Variance_Percentage"] = np.where(
                failed[reference_col] != 0,
                (failed["Variance"] / failed[reference_col].abs()) * 100,
                0
            )

            failed = failed[failed["Variance"] > cutoff].copy()

            if not failed.empty:
                failed["VARIABLE_NAME"] = col_left
                failed["Value"] = failed[current_col]
                failed["Reason"] = failed.apply(
                    lambda row: f"Variance exceeded cutoff | Variance={round(row['Variance'], 2)} | "
                                f"Variance %={round(row['Variance_Percentage'], 2)}% | Cutoff={cutoff}",
                    axis=1
                )

        failed_count = len(failed)

        # -------------------------------------------------
        # COMPILING RESULTS METRICS
        # -------------------------------------------------
        summary_rows.append({
            "VALIDATION_CHECKS": comparison_name,
            "VARIABLE_NAME": col_left,
            "COMPARE_BY": ",".join(compare_by),
            "TOTAL_DATA_POINTS_VALIDATED": total_records,
            "PASSED_DATA_POINTS": total_records - failed_count,
            "FAILED_DATA_POINTS": failed_count,
            "FAIL_RATE(%)": round((failed_count / total_records) * 100, 2) if total_records > 0 else 0
        })

        if not failed.empty:
            ordered_cols = compare_by + ["VARIABLE_NAME", "Value", "Reason"]
            extra_cols = [c for c in failed.columns if
                          c not in ordered_cols and c in ["Variance", "Variance_Percentage"]]
            rows.append(failed[ordered_cols + extra_cols])

    if rows:
        details_df = pd.concat(rows, ignore_index=True)
    else:
        details_df = pd.DataFrame(columns=compare_by + ["VARIABLE_NAME", "Value", "Reason"])

    return pd.DataFrame(summary_rows), details_df


# ---------------------------------------------------------
# LOGICAL CHECKS
# ---------------------------------------------------------

def single_variable_check(
        df,
        col,
        condition,
        value=0,
        display_cols=None
):
    if display_cols is None:
        display_cols = []

    temp = df.copy()

    # Any record that SATISFIES the condition is captured as an invalid/failed record
    if condition == ">":
        invalid = temp[temp[col] > value].copy()
    elif condition == ">=":
        invalid = temp[temp[col] >= value].copy()
    elif condition == "<":
        invalid = temp[temp[col] < value].copy()
    elif condition == "<=":
        invalid = temp[temp[col] <= value].copy()
    elif condition == "=":
        invalid = temp[temp[col] == value].copy()
    elif condition == "!=":
        invalid = temp[temp[col] != value].copy()
    else:
        invalid = pd.DataFrame()

    ordered_cols = display_cols + ["Variable Name", "Value", "Reason"]

    # Restructure Details to output specific columns requested
    if not invalid.empty:
        invalid["Variable Name"] = col
        invalid["Value"] = invalid[col]
        invalid["Reason"] = f"{col} matched anomaly condition: {condition} {value}"
        invalid = invalid[ordered_cols]
    else:
        invalid = pd.DataFrame(columns=ordered_cols)

    summary = pd.DataFrame([
        build_validation_summary(
            "Single Variable Validation",
            col,
            len(df),
            len(invalid)
        )
    ])

    return summary, invalid


# ---------------------------------------------------------
# MULTI VARIABLE LOGIC
# ---------------------------------------------------------

def multi_variable_check(
        df,
        cols,
        operator,
        compare_col,
        comparison,
        display_cols=None
):
    if display_cols is None:
        display_cols = []

    temp = df.copy()

    operator = str(operator or "").upper()

    # ✅ FIX 1: Normalize operators
    comparison = (
        str(comparison or "").strip()
        .replace("&gt;", ">")
        .replace("&lt;", "<")
    )

    if not cols or not compare_col:
        ordered_cols = display_cols + ["Variable Name", "Value", "Reason"]
        summary = pd.DataFrame([
            build_validation_summary(
                "Multi Variable Validation",
                ",".join(cols) if cols else "",
                len(df),
                0
            )
        ])
        return summary, pd.DataFrame(columns=ordered_cols)

    # ✅ FIX 2: Numeric safety
    temp[cols + [compare_col]] = temp[cols + [compare_col]].apply(
        pd.to_numeric, errors="coerce"
    )

    # ✅ Calculation
    if operator in ("SUM", "ADD"):
        temp["CALC"] = temp[cols].sum(axis=1)
    elif operator == "SUBTRACT":
        temp["CALC"] = temp[cols[0]]
        for c in cols[1:]:
            temp["CALC"] -= temp[c]
    elif operator == "MULTIPLY":
        temp["CALC"] = temp[cols].prod(axis=1)
    elif operator == "DIVIDE":
        temp["CALC"] = temp[cols[0]]
        for c in cols[1:]:
            temp["CALC"] /= temp[c].replace(0, np.nan)

    # ✅ FIX 3: Select FAILED rows (not passed rows)
    if comparison == "<=":
        invalid = temp[temp["CALC"] <= temp[compare_col]].copy()
    elif comparison == ">=":
        invalid = temp[temp["CALC"] >= temp[compare_col]].copy()
    elif comparison == "!=":
        invalid = temp[temp["CALC"] != temp[compare_col]].copy()
    elif comparison in ("=", "=="):
        invalid = temp[temp["CALC"] == temp[compare_col]].copy()
    elif comparison == "<":
        invalid = temp[temp["CALC"] < temp[compare_col]].copy()
    elif comparison == ">":
        invalid = temp[temp["CALC"] > temp[compare_col]].copy()
    else:
        invalid = pd.DataFrame()

    ordered_cols = display_cols + ["Variable Name", "Value", "Reason"]

    if not invalid.empty:
        invalid["Variable Name"] = ",".join(cols)
        invalid["Value"] = invalid["CALC"]
        invalid["Reason"] = f"{operator} validation failed against {compare_col}"
        invalid = invalid[ordered_cols]
    else:
        invalid = pd.DataFrame(columns=ordered_cols)

    summary = pd.DataFrame([
        build_validation_summary(
            "Multi Variable Validation",
            ",".join(cols),
            len(df),
            len(invalid)
        )
    ])

    return summary, invalid


# ---------------------------------------------------------
# MULTI VARIABLE BOOLEAN LOGIC
# ---------------------------------------------------------

def evaluate_condition(value, operator, expected):
    operator = (
        str(operator or "").strip()
        .replace("&gt;", ">")
        .replace("&lt;", "<")
    )

    if operator == ">":
        return value > expected
    elif operator == "<":
        return value < expected
    elif operator in ["=", "=="]:
        return value == expected
    elif operator == "!=":
        return value != expected
    elif operator == ">=":
        return value >= expected
    elif operator == "<=":
        return value <= expected

    return False


def build_reason(row, conditions, logical_operator):
    failed_conditions = []
    passed_conditions = []

    for cond in conditions:
        actual = row[cond["column"]]
        expected = cond["value"]
        operator = cond["operator"]

        result = evaluate_condition(actual, operator, expected)
        text = f"{cond['column']} ({actual}) Should be {operator} {expected}"

        if result:
            passed_conditions.append(text)
        else:
            failed_conditions.append(text)

    if logical_operator == "AND":
        return "Failed conditions: " + "; ".join(failed_conditions)
    elif logical_operator == "OR":
        return "None of these conditions passed: " + "; ".join(failed_conditions)
    elif logical_operator == "NOT":
        return "Condition passed but expected to fail: " + "; ".join(passed_conditions)

    return "Validation Failed"


def multi_variable_boolean_check(
        df,
        conditions,
        logical_operator="AND",
        display_cols=None
):
    if display_cols is None:
        display_cols = []

    temp = df.copy()
    masks = []
    normalized_conditions = []

    for cond in conditions:
        col = cond["column"]
        op = (
            str(cond["operator"] or "").strip()
            .replace("&gt;", ">")
            .replace("&lt;", "<")
        )
        value = cond["value"]

        if op == ">":
            masks.append(temp[col] > value)
        elif op == "<":
            masks.append(temp[col] < value)
        elif op in ["=", "=="]:
            masks.append(temp[col] == value)
        elif op == "!=":
            masks.append(temp[col] != value)
        elif op == ">=":
            masks.append(temp[col] >= value)
        elif op == "<=":
            masks.append(temp[col] <= value)

        normalized_conditions.append({
            "column": col,
            "operator": "=" if op == "==" else op,
            "value": value
        })

    ordered_cols = display_cols + ["Variable Name", "Value", "Reason"]

    if not masks:
        summary = pd.DataFrame([
            build_validation_summary(
                "Boolean Logic Validation",
                ",".join([c["column"] for c in normalized_conditions]),
                len(df),
                0
            )
        ])
        return summary, pd.DataFrame(columns=ordered_cols)

    final_mask = masks[0]

    if logical_operator == "AND":
        for m in masks[1:]:
            final_mask &= m
    elif logical_operator == "OR":
        for m in masks[1:]:
            final_mask |= m
    elif logical_operator == "NOT":
        final_mask = ~final_mask

    invalid = temp[final_mask].copy()

    if not invalid.empty:
        invalid["Variable Name"] = ",".join([c["column"] for c in normalized_conditions])
        invalid["Value"] = invalid.apply(
            lambda row: ", ".join(
                [f"{c['column']}={row[c['column']]}" for c in normalized_conditions]
            ),
            axis=1
        )
        invalid["Reason"] = invalid.apply(
            lambda row: build_reason(row, normalized_conditions, logical_operator),
            axis=1
        )
        invalid = invalid[ordered_cols]
    else:
        invalid = pd.DataFrame(columns=ordered_cols)

    summary = pd.DataFrame([
        build_validation_summary(
            "Boolean Logic Validation",
            ",".join([c["column"] for c in normalized_conditions]),
            len(df),
            len(invalid)
        )
    ])

    return summary, invalid


# ---------------------------------------------------------
# INSIGHTS DASHBOARD (UPDATED)
# ---------------------------------------------------------

def calculate_validation_metrics(summary_df, details_df):
    failed_points = 0
    total_validation_points = 0
    num_variables = 0
    num_records = len(details_df)

    if not summary_df.empty and "VARIABLE_NAME" in summary_df.columns:
        num_variables = summary_df["VARIABLE_NAME"].nunique()
    elif not summary_df.empty:
        num_variables = len(summary_df)

    if not summary_df.empty and "FAILED_DATA_POINTS" in summary_df.columns:
        failed_points = int(summary_df["FAILED_DATA_POINTS"].sum())

    if not summary_df.empty and "TOTAL_DATA_POINTS_VALIDATED" in summary_df.columns:
        total_validation_points = int(summary_df["TOTAL_DATA_POINTS_VALIDATED"].sum())

    if total_validation_points <= 0:
        total_validation_points = failed_points

    passed_points = max(total_validation_points - failed_points, 0)

    failed_pct = round((failed_points / total_validation_points) * 100, 2) if total_validation_points else 0
    passed_pct = round((passed_points / total_validation_points) * 100, 2) if total_validation_points else 0

    return {
        "failed": failed_points,
        "passed": passed_points,
        "total": total_validation_points,
        "failed_pct": failed_pct,
        "passed_pct": passed_pct,
        "variables": num_variables,
        "records": num_records
    }


