def get_validation_dataframe(df, page_key):
    dataset_registry = get_dataset_registry(df)
    if not dataset_registry:
        return df, "Raw Data", "home"

    available_ids = list(dataset_registry.keys())
    runtime_config = get_saved_page_runtime(
        page_key,
        dataset_registry[available_ids[0]]["data"].columns if available_ids else []
    )
    saved_dataset_id = runtime_config.get("dataset_id")
    default_dataset_id = saved_dataset_id if saved_dataset_id in dataset_registry else (
        "prepared" if "prepared" in dataset_registry else available_ids[0]
    )

    selected_dataset_id = st.selectbox(
        "Validation Dataset",
        options=available_ids,
        index=available_ids.index(default_dataset_id),
        format_func=lambda dataset_id: dataset_registry[dataset_id]["label"],
        key=f"{page_key}_source"
    )

    selected_dataset = dataset_registry[selected_dataset_id]
    return selected_dataset["data"].copy(), selected_dataset["label"], selected_dataset_id


