# =========================================================
# NON-DESTRUCTIVE VALIDATION ENGINE (EXTENDED CONTEXT)
# =========================================================
def dynamic_validate_block(config_dict, valid_columns):
    """Ensures tool configurations match structural column schemas without dropping properties."""
    if not isinstance(config_dict, dict) or not valid_columns:
        return config_dict

    updated_config = {}
    for key, value in config_dict.items():
        # 1. Protect complex inner formatting dictionaries from getting stripped
        if key in ["formulas", "sort_orders", "rename_mappings"] and isinstance(value, dict):
            if key == "rename_mappings":
                updated_config[key] = {old_c: new_name for old_c, new_name in value.items() if old_c in valid_columns}
            else:
                updated_config[key] = value

        # 2. Protect multi-select column arrays (Cross Tab index, Transpose exclusions, Aggregate setups)
        elif isinstance(value, list) and key in ["index", "exclude_columns", "key_columns", "group_cols",
                                                 "agg_columns"]:
            if len(valid_columns) > 0:
                cleansed_list = [item for item in value if item in valid_columns]
                # Fallback: if stripping completely empties it, hold original loaded configuration until user interacts
                updated_config[key] = cleansed_list if cleansed_list else value
            else:
                updated_config[key] = value

        # 3. Protect single-select column targets (Cross Tab column & value targets)
        elif isinstance(value, str) and key in ["column", "value"]:
            if value in valid_columns:
                updated_config[key] = value
            elif valid_columns:
                # Instead of crashing downstream lookups, map safely to first index fallback
                updated_config[key] = valid_columns[0]
            else:
                updated_config[key] = value

        # 4. Protect non-column categorical properties (Aggregation strategies, flags)
        elif key in ["agg_func", "agg_function"] and isinstance(value, str):
            updated_config[key] = value

        # 5. Fallback standard check for legacy dynamic rules
        elif isinstance(value, str) and value in valid_columns:
            updated_config[key] = value

        elif isinstance(value, dict):
            updated_config[key] = dynamic_validate_block(value, valid_columns)
        else:
            updated_config[key] = value

    return updated_config


# 3. UTILITY ARCHITECTURE BLOCKS (Must be above UI functions)
def generate_current_snapshot():
    """Generates an internal evaluation state blueprint to track changes without copying heavy DataFrames."""
    # 1. Clean dataframes out of the pipeline canvas tracking block safely
    raw_canvas = st.session_state.get("dp_canvas", [])
    cleaned_canvas = []

    for step in raw_canvas:
        if isinstance(step, dict):
            # Create a copy of the step dictionary without the heavy data matrices
            step_blueprint = {k: copy.deepcopy(v) for k, v in step.items() if k != "data"}
            cleaned_canvas.append(step_blueprint)
        else:
            cleaned_canvas.append(copy.deepcopy(step))

    # 2. Extract active tool configurations without their internal 'data' keys if they exist
    raw_tool_config = st.session_state.get("tool_config", {})
    cleaned_tool_config = {}
    if isinstance(raw_tool_config, dict):
        cleaned_tool_config = {k: copy.deepcopy(v) for k, v in raw_tool_config.items() if k != "data"}

    cleaned_tool_containers = []
    for container in st.session_state.get("dp_tool_containers", []):
        if not isinstance(container, dict):
            continue
        container_steps = []
        for step in container.get("steps", []):
            if isinstance(step, dict):
                container_steps.append({k: copy.deepcopy(v) for k, v in step.items() if k != "data"})
        cleaned_tool_containers.append({
            "id": container.get("id"),
            "name": container.get("name"),
            "source_indices": copy.deepcopy(container.get("source_indices", [])),
            "steps": container_steps
        })

    return {
        "project_name": st.session_state.get("project_name", "Untitled_Project"),
        "pipeline": cleaned_canvas,
        "tool_containers": cleaned_tool_containers,
        "tool_configs": cleaned_tool_config,
        "dq_rules": copy.deepcopy(st.session_state.get("dq_rules_config", {})),
        "user_selections": {
            "selected_columns": list(st.session_state.get("selected_columns", [])),
            "join_columns": list(st.session_state.get("join_columns", [])),
            "key_column": st.session_state.get("key_column", None),
        }
    }


def push_to_history():
    """Pushes previous configuration states to history stack for Ctrl+Z processing safely."""
    snapshot = generate_current_snapshot()

    # --- FIXED: SAFE DEEP OBJECT COMPARISON ---
    def is_state_identical(state_a, state_b):
        try:
            # Quick structural evaluation via string/JSON signatures
            # to completely bypass element-wise array ambiguity errors
            return json.dumps(state_a, sort_keys=True, cls=CustomProjectEncoder) == \
                json.dumps(state_b, sort_keys=True, cls=CustomProjectEncoder)
        except Exception:
            # Fallback safe checking if serialization catches a raw un-serializable thread
            return False

    # Check the history stack buffer using our custom serializer check
    if not st.session_state.history_stack or not is_state_identical(st.session_state.history_stack[-1], snapshot):
        st.session_state.history_stack.append(snapshot)
        if len(st.session_state.history_stack) > 20:  # Restrict buffer depth
            st.session_state.history_stack.pop(0)


# =========================================================
# BOUND PIPELINE EXECUTION ENGINE
# =========================================================
def execute_output_tool(input_df, config):
    """
    Terminal Output Tool execution.
    Writes input_df to disk based on config and returns None.
    """
    if input_df is None or input_df.empty:
        return None

    output_folder = config.get("output_folder")
    output_format = config.get("output_format")
    file_name = config.get("file_name")
    sheet_name = config.get("sheet_name", "Sheet1")
    write_mode = config.get("write_mode", "Overwrite File")

    if not output_folder or not output_format or not file_name:
        raise ValueError("Output Tool configuration is incomplete")

    os.makedirs(output_folder, exist_ok=True)
    file_path = os.path.join(output_folder, f"{file_name}.{output_format}")

    if output_format == "csv":
        input_df.to_csv(file_path, index=False)

    elif output_format == "json":
        input_df.to_json(file_path, orient="records", indent=2)

    elif output_format == "parquet":
        input_df.to_parquet(file_path, index=False)

    elif output_format == "xlsx":
        file_exists = os.path.exists(file_path)

        if write_mode == "Overwrite File" or not file_exists:
            writer_mode = "w"
            sheet_behavior = None
        else:
            writer_mode = "a"
            sheet_behavior = "replace" if write_mode == "Overwrite Sheet" else "new"

        with pd.ExcelWriter(
            file_path,
            engine="openpyxl",
            mode=writer_mode,
            if_sheet_exists=sheet_behavior
        ) as writer:
            input_df.to_excel(writer, sheet_name=sheet_name, index=False)

    return None  # terminal node

def resolve_step_input(idx, canvas, fallback_df):
    """
    Resolves cached input for a step by walking upstream.
    Uses cached_output from previous steps if available.
    """
    for j in range(idx - 1, -1, -1):
        upstream_step = canvas[j]
        cached = upstream_step.get("cached_output")
        if isinstance(cached, pd.DataFrame):
            return cached
    return fallback_df

def run_pipeline(df):
    if df is None or df.empty:
        return None

    working_df = df.copy()
    pipeline_steps = st.session_state.get("dp_canvas", [])
    active_tool = st.session_state.get("active_tool", None)

    for step in pipeline_steps:
        tool = step.get("tool")

        # 1. DIRECT BINDING LINK: Force runtime to use live UI config if it's the active tool
        if tool == active_tool and st.session_state.get("tool_config"):
            config = st.session_state.tool_config
            step["config"] = copy.deepcopy(config)  # Keep canvas synced with code updates
        else:
            config = step.get("config", {})

        if not config:
            continue

        # Dynamic validation evaluates downstream metrics step-by-step
        config = dynamic_validate_block(config, list(working_df.columns))

        # --- TOOL ROUTE: FORMULA TOOL ---
        if tool == "Formula Tool":
            try:
                formulas = config.get("formulas", [])
                for f in formulas:
                    mode = f.get("mode")
                    out_col = f.get("output_column")
                    expr = f.get("expression")

                    if out_col and expr:
                        # Clean bracket definitions for safe pandas parsing
                        eval_expr = expr.replace("[", "working_df['").replace("]", "']")
                        working_df[out_col] = eval(eval_expr)
                step["data"] = working_df.copy()
            except Exception as e:
                st.error(f"Formula Engine failed: {e}")

        # =====================================================
        # OUTPUT TOOL (TERMINAL, NO DF MUTATION)
        # =====================================================
        elif tool == "Output Tool":
            try:
                # -------------------------------------------------
                # ✅ Resolve cached input exactly like other tools
                # -------------------------------------------------
                step_idx = idx - 1  # idx from enumerate(start=1)

                input_df = step.get("cached_input")
                if input_df is None:
                    input_df = resolve_step_input(
                        step_idx,
                        st.session_state.dp_canvas,
                        st.session_state.get("prepared_df")
                    )

                # -------------------------------------------------
                # ✅ Execute side‑effect only
                # -------------------------------------------------
                execute_output_tool(input_df, config)

                # -------------------------------------------------
                # ✅ Maintain cache semantics (terminal tool)
                # -------------------------------------------------
                step["cached_input"] = input_df  # ✅ important
                step["cached_output"] = None  # terminal
                step["data"] = None

            except Exception as e:
                st.error(f"Output Tool failed: {e}")

            continue

        # --- TOOL ROUTE: SORT TOOL (DIRECT STATE BINDING) ---
        elif tool == "Sort Tool":
            try:
                # Read properties explicitly from verified execution dictionary
                sort_columns = config.get("columns", [])
                sort_orders = config.get("sort_orders", {})

                # If columns are completely absent, fall back to matching data keys defensively
                if not sort_columns:
                    # Look inside sort_orders keys if columns array was stripped by validation
                    if sort_orders:
                        sort_columns = list(sort_orders.keys())
                    else:
                        continue

                # Clean and isolate column matches present in active workspace
                sort_columns = [col for col in sort_columns if col in working_df.columns]
                if not sort_columns:
                    continue

                # Type casting mechanics
                for col in sort_columns:
                    if working_df[col].dtype == "object":
                        try:
                            working_df[col] = pd.to_numeric(working_df[col])
                        except Exception:
                            pass
                        try:
                            working_df[col] = pd.to_datetime(working_df[col])
                        except Exception:
                            pass

                ascending_list = [
                    sort_orders.get(col, "Ascending") == "Ascending"
                    for col in sort_columns
                ]

                working_df = working_df.sort_values(
                    by=sort_columns,
                    ascending=ascending_list,
                    na_position="last"
                ).reset_index(drop=True)

                step["data"] = working_df.copy()
            except Exception as e:
                st.error(f"Sort tool execution breakdown: {e}")

        # --- TOOL ROUTE: FILTER ENGINE ---
        else:
            def apply_rules_recursively(current_df, rule_dict):
                col = rule_dict.get("column")
                op = rule_dict.get("operator")
                val = rule_dict.get("value")

                if col in current_df.columns and op and val is not None:
                    series = current_df[col]
                    try:
                        val_cast = float(val)
                    except Exception:
                        val_cast = val

                    if op in ["==", "=", "equals"]:
                        current_df = current_df[
                            current_df[col].astype(str).str.lower() == str(val_cast).lower()] if isinstance(val_cast,
                                                                                                            str) else \
                            current_df[series == val_cast]
                    elif op == ">":
                        current_df = current_df[series > val_cast]
                    elif op == "<":
                        current_df = current_df[series < val_cast]
                    # Standard fallback blocks...

                if "conditions" in rule_dict and isinstance(rule_dict["conditions"], list):
                    for sub_condition in rule_dict["conditions"]:
                        current_df = apply_rules_recursively(current_df, sub_condition)
                return current_df

            working_df = apply_rules_recursively(working_df, config)
            step["data"] = working_df.copy()

        # Shared downstream operations processing
        if "deduplicate" in config or tool == "Duplicate Tool":
            dup_col = config.get("column") or config.get("dedup_column")
            if dup_col in working_df.columns:
                working_df = working_df.drop_duplicates(subset=[dup_col])

    return working_df


# =========================================================
# CANVAS REFERENCE HELPERS
# =========================================================

def _seed_missing_upstream_links():
    """
    Auto-wire blank upstream inputs to the nearest prior step after insert/move.
    This keeps freshly inserted or reordered steps aligned with the visible DAG order.
    """
    canvas = st.session_state.get("dp_canvas", [])
    for idx, step_obj in enumerate(canvas):
        if not isinstance(step_obj, dict):
            continue
        cfg = step_obj.setdefault("config", {})
        tool_name = str(step_obj.get("tool", "")).strip()
        previous_ref = f"step_{idx - 1}" if idx > 0 else "home"

        if tool_name == "Join Tool":
            if cfg.get("left_id") in [None, "", "home"] and idx > 0:
                cfg["left_id"] = previous_ref
            if cfg.get("right_id") in [None, "", "home"]:
                cfg["right_id"] = f"step_{idx - 2}" if idx > 1 else "home"
            continue

        if tool_name == "Union Tool":
            continue

        if tool_name != "Input Tool" and cfg.get("dataset_id") in [None, "", "home"] and idx > 0:
            cfg["dataset_id"] = previous_ref

