# =========================================================
# SAFE JSON ENCODER FALLBACK (DATABASE COMPATIBLE)
# =========================================================
class CustomProjectEncoder(json.JSONEncoder):
    def default(self, obj):
        # Handle datetime, timestamps, and database date objects
        if isinstance(obj, (pd.Timestamp, dt_datetime, dt_module.datetime)):
            return obj.isoformat()
        if isinstance(obj, dt_module.date):
            return obj.isoformat()

        # Handle database high-precision numeric types (Decimal)
        if isinstance(obj, decimal.Decimal):
            return float(obj)

        # Handle integers and floating points
        if isinstance(obj, (np.integer, int)):
            return int(obj)
        if isinstance(obj, (np.floating, float)):
            return float(obj)
        if isinstance(obj, (np.bool_, bool)):
            return bool(obj)

        # Handle data structures
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        if isinstance(obj, pd.DataFrame):
            return obj.to_dict(orient="records")
        if isinstance(obj, pd.Series):
            return obj.tolist()

        # Handle binary objects or raw buffers sometimes left by DB drivers
        if isinstance(obj, (bytes, bytearray)):
            return obj.decode('utf-8', errors='ignore')

        try:
            return super().default(obj)
        except TypeError:
            return str(obj)


# =====================================================================
# GLOBAL TYPE-SAFE ENCODER FOR ORACLE / NUMPY WORKSPACE METADATA
# =====================================================================
class WorkspaceJsonEncoder(json.JSONEncoder):
    def default(self, obj):
        if isinstance(obj, (np.int64, np.int32, np.int16, np.int8)):
            return int(obj)
        if isinstance(obj, (np.float64, np.float32, np.float16)):
            return float(obj)
        if isinstance(obj, np.ndarray):
            return obj.tolist()
        if isinstance(obj, decimal.Decimal):
            return float(obj) if obj % 1 else int(obj)
        if isinstance(obj, (pd.Timestamp, pd.DatetimeIndex)):
            return str(obj)
        try:
            return super(WorkspaceJsonEncoder, self).default(obj)
        except TypeError:
            return str(obj)


# =========================================================
# TYPE-SAFE TRACKING SNAPSHOT GENERATOR
# =========================================================
def generate_current_snapshot():
    """Generates a type-safe minimal dictionary representation of the canvas state for dirty tracking."""
    snapshot = {
        "project_name": str(st.session_state.get("project_name", "Untitled_Project")),
        "pipeline": [],
        "user_selections": {
            "selected_columns": list(st.session_state.get("selected_columns", [])),
            "join_columns": list(st.session_state.get("join_columns", [])),
            "key_column": st.session_state.get("key_column", None)
        }
    }

    # Safely extract canvas configuration parameters without memory addresses
    if "dp_canvas" in st.session_state:
        for idx, step in enumerate(st.session_state.dp_canvas, start=1):
            if isinstance(step, dict):
                step_config = strip_sensitive_db_fields(copy.deepcopy(step.get("config", {})))
                source_dataset_id = step_config.get("dataset_id")
                if source_dataset_id in [None, "", "home"]:
                    step_config["input_dataset_name"] = "Home - Raw Dataset"
                else:
                    source_text = str(source_dataset_id).strip().lower()
                    resolved_label = str(source_dataset_id)
                    matched = re.search(r"(\d+)$", source_text)
                    if matched and (source_text.startswith("step_") or source_text.startswith(
                            "step_index_") or source_text.startswith("stepindex_")):
                        source_idx = int(matched.group(1))
                        if 0 <= source_idx < len(st.session_state.dp_canvas):
                            source_step = st.session_state.dp_canvas[source_idx]
                            resolved_label = f"Step {source_idx + 1} - {source_step.get('tool', 'Output')}"
                    step_config["input_dataset_name"] = resolved_label
                snapshot["pipeline"].append({
                    "id": step.get("id"),
                    "tool": step.get("tool"),
                    "config": step_config
                })
    return snapshot


def apply_snapshot(snapshot):
    """Restores structural application tracking attributes from target historical snapshot."""
    if not snapshot:
        return

    # Handle unified master template wrapper if available
    if "home_config" in snapshot or "pipeline_canvas" in snapshot:
        load_saved_project_blueprint(snapshot)
    else:
        st.session_state.project_name = snapshot.get("project_name", "Untitled_Project")
        st.session_state.dp_canvas = copy.deepcopy(snapshot.get("pipeline", []))
        st.session_state.tool_config = copy.deepcopy(snapshot.get("tool_configs", {}))
        st.session_state.dq_rules_config = copy.deepcopy(snapshot.get("dq_rules", {}))

        selections = snapshot.get("user_selections", {})
        st.session_state.selected_columns = list(selections.get("selected_columns", []))
        st.session_state.join_columns = list(selections.get("join_columns", []))
        st.session_state.key_column = selections.get("key_column", None)


def commit_save_action():
    """Performs state synchronization routine to update snapshot states and reset indicators."""
    st.session_state.last_saved_snapshot = generate_current_snapshot()
    st.session_state.is_dirty = False


def autosave_project_if_due(force=False):
    """Periodically persists the current project configuration without waiting for manual save."""
    autosave_enabled = bool(st.session_state.get("dp_autosave_enabled", True))
    if not autosave_enabled and not force:
        return False, None

    try:
        interval_seconds = int(st.session_state.get("dp_autosave_interval_seconds", 60))
    except Exception:
        interval_seconds = 30
    interval_seconds = max(5, interval_seconds)

    current_snapshot = generate_current_snapshot()
    current_snap_str = json.dumps(current_snapshot, cls=CustomProjectEncoder, sort_keys=True)
    last_saved_snapshot = st.session_state.get("last_saved_snapshot", {})
    last_saved_snap_str = json.dumps(last_saved_snapshot, cls=CustomProjectEncoder,
                                     sort_keys=True) if last_saved_snapshot else ""

    now_ts = time.time()
    last_autosave_ts = float(st.session_state.get("dp_last_autosave_ts", 0) or 0)
    is_changed = current_snap_str != last_saved_snap_str
    due = force or (is_changed and (now_ts - last_autosave_ts) >= interval_seconds)

    if not due:
        return False, None

    raw_blueprint_str = save_project()
    if not raw_blueprint_str or raw_blueprint_str == "{}":
        return False, None

    st.session_state.last_saved_snapshot = current_snapshot
    st.session_state.is_dirty = False
    st.session_state.dp_last_autosave_ts = now_ts
    st.session_state.saved_project_blueprint = json.loads(raw_blueprint_str)

    project_name = st.session_state.get("project_name", "Untitled_Project")
    autosave_path = save_project_autosave(project_name, raw_blueprint_str)
    return True, autosave_path


# =========================================================
# COMPREHENSIVE SAVING ENGINE (PRESERVES COMPLETE CONTEXT)
# =========================================================
def save_project():
    """Serializes the total operational state of the canvas and home configuration parameters

    while aggressively filtering out live connection pools and raw memory dataframes.
    """
    if "tool_config" not in st.session_state:
        st.session_state["tool_config"] = {}

    raw_configs = copy.deepcopy(st.session_state.get("tool_config", {}))
    cleaned_configs = {}

    for k, v in raw_configs.items():
        if any(x in str(k).lower() for x in ["schema", "engine", "conn", "password", "metadata"]):
            continue
        if isinstance(v, (pd.Index, pd.Series)):
            cleaned_configs[k] = v.tolist()
        else:
            cleaned_configs[k] = v

    db_meta_configs = {}
    for key in list(st.session_state.keys()):
        if "config_home_loader" in key or "config_db" in key:
            val = st.session_state[key]
            if isinstance(val, dict):
                db_meta_configs[key] = strip_sensitive_db_fields({
                    k: (str(v) if not isinstance(v, (str, int, float, bool, list)) else v)
                    for k, v in val.items()
                    if not any(x in str(k).lower() for x in ["engine", "conn", "password", "schema"])
                })

    # Extract Home Page Inputs cleanly (sanitizing types for all multi-source setups)
    home_page_config = {
        "project_name": str(st.session_state.get("project_name", "Untitled_Project")),
        "selected_database": str(st.session_state.get("selected_database", "")),
        "raw_query_input": str(st.session_state.get("raw_query_input", "")),
        "key_column": str(st.session_state.get("key_column", "")),
        "selected_columns": [str(c) for c in st.session_state.get("selected_columns", [])],
        "join_columns": [str(c) for c in st.session_state.get("join_columns", [])]
    }

    # Extract pipeline steps safely, wiping memory-heavy data cache representations
    cleaned_canvas = []
    if "dp_canvas" in st.session_state:
        for step in st.session_state.dp_canvas:
            if isinstance(step, dict):
                step_config = strip_sensitive_db_fields(copy.deepcopy(step.get("config", {})))
                source_dataset_id = step_config.get("dataset_id")
                if source_dataset_id in [None, "", "home"]:
                    step_config["input_dataset_name"] = "Home - Raw Dataset"
                else:
                    source_text = str(source_dataset_id).strip().lower()
                    resolved_label = str(source_dataset_id)
                    matched = re.search(r"(\d+)$", source_text)
                    if matched and (source_text.startswith("step_") or source_text.startswith(
                            "step_index_") or source_text.startswith("stepindex_")):
                        source_idx = int(matched.group(1))
                        if 0 <= source_idx < len(st.session_state.dp_canvas):
                            source_step = st.session_state.dp_canvas[source_idx]
                            resolved_label = f"Step {source_idx + 1} - {source_step.get('tool', 'Output')}"
                    step_config["input_dataset_name"] = resolved_label
                cleaned_canvas.append({
                    "id": step.get("id"),
                    "tool": step.get("tool"),
                    "config": step_config
                })

    cleaned_tool_containers = []
    for container in st.session_state.get("dp_tool_containers", []):
        if not isinstance(container, dict):
            continue
        container_name = str(container.get("name", "")).strip()
        container_steps = []
        for step in container.get("steps", []):
            if not isinstance(step, dict):
                continue
            step_tool = step.get("tool")
            if not step_tool:
                continue
            step_config = strip_sensitive_db_fields(copy.deepcopy(step.get("config", {})))
            container_steps.append({
                "id": step.get("id"),
                "tool": step_tool,
                "config": step_config
            })
        if not container_name or not container_steps:
            continue
        source_indices = []
        for idx in container.get("source_indices", []):
            if isinstance(idx, int):
                source_indices.append(idx)
        cleaned_tool_containers.append({
            "id": container.get("id") or f"container_{sanitize_dataset_id(container_name)}",
            "name": container_name,
            "source_indices": source_indices,
            "steps": container_steps,
            "created_at": container.get("created_at")
        })

    # Consolidate into a cross-compatible master configuration schema blueprint
    master_blueprint = {
        "home_config": home_page_config,
        "pipeline_canvas": cleaned_canvas,
        "dp_edges": copy.deepcopy(st.session_state.get("dp_edges", [])),
        "dp_tool_containers": cleaned_tool_containers,
        "version": "2.0",
        "saved_on": dt_datetime.now().isoformat(),
        "active_tool": st.session_state.get("active_tool", []),
        "tool_configs": cleaned_configs,
        "database_metadata_profiles": db_meta_configs,
        "dq_rules": st.session_state.get("dq_rules_config", {}),
        "discovered_operators": list(st.session_state.get("discovered_operators", []))
    }

    enhanced_config_manager.page_configs.clear_page_configs()
    for page_key, runtime in st.session_state.get("page_runtime_configs", {}).items():
        enhanced_config_manager.page_configs.save_page_config(
            page_name=runtime.get("page_name", page_key),
            tool_name=runtime.get("tool_name", page_key),
            config=copy.deepcopy(runtime.get("config", {})),
            used_columns=list(runtime.get("used_columns", []))
        )

    master_blueprint["page_runtime_configs"] = copy.deepcopy(st.session_state.get("page_runtime_configs", {}))
    master_blueprint["workflow_dataset_catalog"] = copy.deepcopy(build_workflow_dataset_catalog())
    master_blueprint["copilot_page_state"] = copy.deepcopy(st.session_state.get("copilot_page_state", {}))
    master_blueprint["saved_config_load_result"] = copy.deepcopy(st.session_state.get("saved_config_load_result", {}))
    master_blueprint["dp_execution_run_summary"] = copy.deepcopy(st.session_state.get("dp_execution_run_summary", {}))
    master_blueprint = enhanced_config_manager.enhance_project_blueprint(master_blueprint)

    try:
        return json.dumps(master_blueprint, indent=4, ensure_ascii=False, cls=CustomProjectEncoder)
    except Exception:
        try:
            brute_force_project = {}
            for k, v in master_blueprint.items():
                if isinstance(v, dict):
                    brute_force_project[k] = {subkey: str(subval) for subkey, subval in v.items()}
                elif isinstance(v, list):
                    brute_force_project[k] = [str(item) for item in v]
                else:
                    brute_force_project[k] = str(v)
            return json.dumps(brute_force_project, indent=4)
        except Exception:
            return None


# =========================================================
# GLOBAL KEYBOARD SHORTCUT INTERCEPTOR (JS ENGINE)
# =========================================================
components.html(
    """
    <script>
    const doc = window.parent.document;
    doc.removeAttribute('keydown'); 
    doc.addEventListener('keydown', function(e) {
        if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
            e.preventDefault();
            window.parent.location.search = "?shortcut=save&t=" + Date.now();
        }
        if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'z') {
            e.preventDefault();
            window.parent.location.search = "?shortcut=undo&t=" + Date.now();
        }
    }, true);
    </script>
    """,
    height=0,
    width=0
)

if "shortcut" in st.query_params:
    action = st.query_params["shortcut"]
    if action == "save":
        commit_save_action()
        st.toast("💾 Project configuration saved successfully via shortcut!")
    elif action == "undo" and st.session_state.history_stack:
        prior_state = st.session_state.history_stack.pop()
        apply_snapshot(prior_state)
        st.session_state.is_dirty = (generate_current_snapshot() != st.session_state.last_saved_snapshot)
        st.toast("↩️ Reversed last alteration.")
    st.query_params.clear()


# =========================================================
# DYNAMIC EXTRACTION ENGINE FOR EXTENDED METADATA
# =========================================================
def extract_custom_operators_recursively(config_block):
    if not isinstance(config_block, dict):
        return
    for key, value in config_block.items():
        if "operator" in key.lower() and isinstance(value, str):
            if value not in st.session_state.discovered_operators:
                st.session_state.discovered_operators.append(value)
        elif isinstance(value, dict):
            extract_custom_operators_recursively(value)
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict):
                    extract_custom_operators_recursively(item)


# =========================================================
# NESTED STRUCTURE FILTER & RECONCILIATION BLOCK
# =========================================================
def dynamic_validate_reconciliation_block(config_block, valid_columns):
    """Safely filters out column dependencies that no longer exist in the dataframe

    without corrupting structured parameters or dictionary lists.
    """
    if not isinstance(config_block, dict):
        return config_block

    cleaned_block = {}
    for key, val in config_block.items():
        if isinstance(val, list):
            # If list contains pure column names strings (e.g. Sampling groups)
            if all(isinstance(x, str) for x in val):
                cleaned_block[key] = [x for x in val if x in valid_columns]
            # If list contains nested tool layouts (e.g. Formula items block)
            elif all(isinstance(x, dict) for x in val):
                cleaned_formulas = []
                for f_item in val:
                    cleaned_formulas.append(f_item)
                cleaned_block[key] = cleaned_formulas
            else:
                cleaned_block[key] = val
        elif isinstance(val, dict):
            cleaned_block[key] = dynamic_validate_reconciliation_block(val, valid_columns)
        else:
            cleaned_block[key] = val
    return cleaned_block


# =========================================================
# LIVE DATA RECONCILIATION ROUTINE
# =========================================================
def _current_schema_signature(df):
    """
    Returns a stable, hashable signature of the active dataframe schema.
    Used to prevent repeated reconciliation on Streamlit reruns.
    """
    if df is None or df.empty:
        return None
    return tuple(map(str, df.columns))

def run_global_pipeline_reconciliation():
    """
    Aligns existing rules with current schema without wiping settings if empty.
    Guarded to run ONLY when dataframe schema changes.
    """

    df = st.session_state.current_df
    if df is None or df.empty:
        return

    # --------------------------------------------------
    # ✅ SCHEMA GUARD (prevents infinite reruns)
    # --------------------------------------------------
    current_signature = _current_schema_signature(df)
    last_signature = st.session_state.get("_last_reconciled_schema")

    if current_signature == last_signature:
        # Schema unchanged → do NOTHING (critical for Streamlit stability)
        return

    # Mark this schema as reconciled BEFORE doing work
    st.session_state["_last_reconciled_schema"] = current_signature

    # --------------------------------------------------
    # ✅ EXISTING LOGIC (UNCHANGED)
    # --------------------------------------------------
    valid_columns = [str(c) for c in df.columns]

    # Filter user selections safely
    st.session_state.selected_columns = [
        c for c in st.session_state.selected_columns
        if str(c) in valid_columns
    ]

    st.session_state.join_columns = [
        c for c in st.session_state.join_columns
        if str(c) in valid_columns
    ]

    if (
        st.session_state.key_column
        and str(st.session_state.key_column) not in valid_columns
    ):
        st.session_state.key_column = None

    # Reconcile tool-level configs
    st.session_state.tool_config = dynamic_validate_reconciliation_block(
        st.session_state.tool_config,
        valid_columns
    )

    st.session_state.dq_rules_config = dynamic_validate_reconciliation_block(
        st.session_state.dq_rules_config,
        valid_columns
    )

    # Reconcile per-page runtime configs
    migrated_runtime = {}

    for page_key, runtime in st.session_state.get(
        "page_runtime_configs", {}
    ).items():

        migrated = migrate_runtime_config(runtime, valid_columns)
        migrated_runtime[page_key] = migrated

        # Preserve existing behavior: merge page tool config
        st.session_state.tool_config.update(
            migrated.get("config", {})
        )

    if migrated_runtime:
        st.session_state.page_runtime_configs = migrated_runtime

    # --------------------------------------------------
    # ✅ DO NOT TOUCH DP CANVAS SEMANTICS (unchanged)
    # --------------------------------------------------
    # Canvas steps can legitimately reference derived columns
    st.session_state.dp_canvas = list(
        st.session_state.get("dp_canvas", [])
    )


# =====================================================================
# SYSTEM MASTER BLUEPRINT DECODER (UNIVERSAL LOAD HOOK)
# =====================================================================
def load_saved_project_blueprint(master_blueprint):
    if not isinstance(master_blueprint, dict):
        return False

    try:
        if "home_config" in master_blueprint or "pipeline_canvas" in master_blueprint:
            reset_project_runtime_outputs()
            for session_key in list(st.session_state.keys()):
                if str(session_key).startswith("pw_"):
                    st.session_state.pop(session_key, None)
            home_config = strip_sensitive_db_fields(master_blueprint.get("home_config", {}))

            # Repopulate Home state text keys exactly
            st.session_state["project_name"] = home_config.get("project_name", "Untitled_Project")
            st.session_state["selected_database"] = home_config.get("selected_database", "")
            st.session_state["raw_query_input"] = home_config.get("raw_query_input", "")
            st.session_state["key_column"] = home_config.get("key_column", "")
            st.session_state["selected_columns"] = home_config.get("selected_columns", [])
            st.session_state["join_columns"] = home_config.get("join_columns", [])

            # Repopulate Canvas steps
            pipeline_canvas = master_blueprint.get("pipeline_canvas", [])
            st.session_state.dp_canvas = []
            for step_index, step in enumerate(pipeline_canvas, start=1):
                tool_name = step.get("tool")
                step_config = strip_sensitive_db_fields(step.get("config", {}))

                # Dynamic Safety Hydration for Sampling and Tile Configs
                if tool_name == "Sampling Tool":
                    if "sample_type" not in step_config: step_config["sample_type"] = "First N Rows"
                    if "n_value" not in step_config: step_config["n_value"] = 100
                    if "group_cols" not in step_config: step_config["group_cols"] = []
                elif tool_name == "Output Tool":
                    if "output_folder" not in step_config:
                        step_config["output_folder"] = ""
                    if "output_format" not in step_config:
                        step_config["output_format"] = "csv"
                    if "file_name" not in step_config:
                        step_config["file_name"] = "output"
                    if "sheet_name" not in step_config:
                        step_config["sheet_name"] = "Sheet1"
                    if "write_mode" not in step_config:
                        step_config["write_mode"] = "Overwrite File"
                elif tool_name == "Random Sampling Tool":
                    if "sample_mode" not in step_config: step_config["sample_mode"] = "N Records"
                    if "n_value" not in step_config: step_config["n_value"] = 100
                    if "replacement" not in step_config: step_config["replacement"] = False
                    if "seed" not in step_config: step_config["seed"] = None
                    if "group_cols" not in step_config: step_config["group_cols"] = []
                elif tool_name == "Tile Tool":
                    if "method" not in step_config: step_config["method"] = "Equal Records"
                    if "target_col" not in step_config: step_config["target_col"] = ""
                    if "num_tiles" not in step_config: step_config["num_tiles"] = 5
                    if "tile_cutpoints" not in step_config: step_config["tile_cutpoints"] = ""
                    if "group_cols" not in step_config: step_config["group_cols"] = []
                elif tool_name == "Multi Row Formula Tool":
                    if "output_column" not in step_config: step_config["output_column"] = "NewColumn"
                    if "expression" not in step_config: step_config["expression"] = ""
                    if "group_cols" not in step_config: step_config["group_cols"] = []
                elif tool_name == "Multi Field Formula Tool":
                    if "fields" not in step_config: step_config["fields"] = ""
                    if "expression" not in step_config: step_config["expression"] = "[_CurrentField_]"
                    if "output_mode" not in step_config: step_config["output_mode"] = "Create New Fields with Suffix"
                    if "output_suffix" not in step_config: step_config["output_suffix"] = "_out"
                elif tool_name == "RecordID Tool":
                    if "id_column" not in step_config: step_config["id_column"] = "RecordID"
                    if "start_value" not in step_config: step_config["start_value"] = 1
                    if "increment" not in step_config: step_config["increment"] = 1
                    if "group_cols" not in step_config: step_config["group_cols"] = []
                elif tool_name == "Aggregate Tool":
                    if "group_cols" not in step_config: step_config["group_cols"] = []
                    if "agg_functions" not in step_config: step_config["agg_functions"] = {}
                    if "agg_columns" not in step_config: step_config["agg_columns"] = []
                elif tool_name == "Report Tool":
                    if "filename" not in step_config: step_config["filename"] = "Report"
                    if "sheets" not in step_config: step_config["sheets"] = []

                st.session_state.dp_canvas.append(
                    ensure_workflow_step_identity(
                        {
                            "id": step.get("id"),
                            "tool": tool_name,
                            "config": step_config,
                            "input": step.get("input", "auto"),  # ✅ preserve wiring
                            "data": None
                        },
                        step_index
                    )
                )

            restored_edges = []
            for edge in master_blueprint.get("dp_edges", []):
                if not isinstance(edge, dict):
                    continue
                try:
                    from_idx = int(edge.get("from_idx"))
                    to_idx = int(edge.get("to_idx"))
                except (TypeError, ValueError):
                    continue
                restored_edges.append({
                    "from_idx": from_idx,
                    "to_idx": to_idx,
                    "label": str(edge.get("label", "") or "")
                })
            st.session_state.dp_edges = restored_edges

            restored_containers = []
            for container in master_blueprint.get("dp_tool_containers", []):
                if not isinstance(container, dict):
                    continue
                container_name = str(container.get("name", "")).strip()
                if not container_name:
                    continue

                container_steps = []
                for step_index, step in enumerate(container.get("steps", []), start=1):
                    if not isinstance(step, dict):
                        continue
                    tool_name = step.get("tool")
                    if not tool_name:
                        continue
                    step_config = strip_sensitive_db_fields(step.get("config", {}))
                    container_steps.append(
                        ensure_workflow_step_identity(
                            {
                                "id": step.get("id"),
                                "tool": tool_name,
                                "config": step_config,
                                "input": step.get("input", "auto"),  # ✅ add
                                "data": None
                            },
                            step_index
                        )
                    )

                if not container_steps:
                    continue

                source_indices = []
                for source_idx in container.get("source_indices", []):
                    try:
                        source_indices.append(int(source_idx))
                    except (TypeError, ValueError):
                        continue

                restored_containers.append({
                    "id": container.get("id") or f"container_{sanitize_dataset_id(container_name)}_{time.time_ns()}",
                    "name": container_name,
                    "source_indices": source_indices,
                    "steps": container_steps,
                    "created_at": container.get("created_at")
                })
            st.session_state.dp_tool_containers = restored_containers

            # Seed Input Tool widget state from loaded JSON (source type + sheet name)
            for _step in st.session_state.get("dp_canvas", []):
                if str(_step.get("tool", "")).strip() != "Input Tool":
                    continue
                _sid = _step.get("id", "0")
                _cfg = _step.get("config") or {}
                _src_key = f"source_{_sid}"
                _saved_src = _cfg.get("source_type", "File")
                if _src_key not in st.session_state and _saved_src in ["File", "Database", "API"]:
                    st.session_state[_src_key] = _saved_src
                _saved_sheet = str(_cfg.get("sheet_name") or "").strip()
                if _saved_sheet:
                    for _sheet_key in (f"sheet_{_sid}", f"sheet_text_{_sid}", f"sheet_select_{_sid}"):
                        if _sheet_key not in st.session_state:
                            st.session_state[_sheet_key] = _saved_sheet

            st.session_state.tool_config = copy.deepcopy(master_blueprint.get("tool_configs", {}))
            st.session_state.dq_rules_config = copy.deepcopy(master_blueprint.get("dq_rules", {}))
            st.session_state.active_tool = master_blueprint.get("active_tool", [])
            st.session_state.page_runtime_configs = copy.deepcopy(master_blueprint.get("page_runtime_configs", {}))
            st.session_state.workflow_dataset_catalog = copy.deepcopy(
                master_blueprint.get("workflow_dataset_catalog", {}))
            st.session_state.copilot_page_state = copy.deepcopy(master_blueprint.get("copilot_page_state", {}))
            st.session_state.dp_execution_run_summary = copy.deepcopy(
                master_blueprint.get("dp_execution_run_summary", {}))
            st.session_state.saved_config_load_result = copy.deepcopy(
                master_blueprint.get("saved_config_load_result", {}))
            home_runtime = st.session_state.page_runtime_configs.get("home", {})
            if home_runtime.get("config"):
                st.session_state["config_home_loader"] = copy.deepcopy(home_runtime["config"])
                pending_home_loader_widget_state = {
                    "db_home_loader": home_runtime["config"].get(
                        "db_type",
                        st.session_state.get("db_home_loader", "sqlserver")
                    ),
                    "h_home_loader": home_runtime["config"].get(
                        "host",
                        st.session_state.get("h_home_loader", "localhost")
                    ),
                    "u_home_loader": home_runtime["config"].get(
                        "user",
                        st.session_state.get("u_home_loader", "")
                    ),
                    "d_home_loader": home_runtime["config"].get(
                        "database",
                        st.session_state.get("d_home_loader", "")
                    ),
                    "p_home_loader": int(home_runtime["config"].get("port") or 0)
                }
                if home_runtime["config"].get("query"):
                    pending_home_loader_widget_state["sql_editor_home_loader"] = home_runtime["config"]["query"]
                if home_runtime["config"].get("source_type"):
                    pending_home_loader_widget_state["source_type_home_loader"] = home_runtime["config"]["source_type"]
                if home_runtime["config"].get("sheet_name"):
                    pending_home_loader_widget_state["sheet_home_loader"] = home_runtime["config"]["sheet_name"]
                st.session_state["pending_home_loader_widget_state"] = pending_home_loader_widget_state
                for state_key, state_value in pending_home_loader_widget_state.items():
                    if state_key not in st.session_state:
                        st.session_state[state_key] = state_value

            active_df = st.session_state.get("current_df")
            available_columns = list(active_df.columns) if isinstance(active_df, pd.DataFrame) else []
            if any(
                    key in master_blueprint
                    for key in ["database_connections", "tool_output_registry", "page_configurations"]
            ):
                load_result = enhanced_config_manager.load_enhanced_blueprint(
                    master_blueprint,
                    available_columns
                )
                st.session_state.saved_config_load_result = load_result

            if available_columns:
                migrated_runtime = {}
                for page_key, runtime in st.session_state.page_runtime_configs.items():
                    migrated_runtime[page_key] = migrate_runtime_config(runtime, available_columns)
                    st.session_state.tool_config.update(migrated_runtime[page_key].get("config", {}))
                st.session_state.page_runtime_configs = migrated_runtime

            restore_saved_page_widget_states()
            build_workflow_dataset_catalog()

        return True
    except Exception as e:
        st.error(f"Error parsing blueprint: {e}")
        return False


# =========================================================
# IDEMPOTENT LOADING ENGINE (PREVENTS ACCIDENTAL DATA LOSS)
# =========================================================
def load_project(uploaded_file):
    """Safely ingests external JSON templates and locks configuration states."""
    try:
        cached_df = st.session_state.get("current_df", None)

        file_content = uploaded_file.read()
        uploaded_file.seek(0)
        project = json.loads(file_content)

        # Trigger unified blueprint loading structure logic
        load_success = load_saved_project_blueprint(project)

        if not load_success:
            # Native legacy execution sequence fallback strategy
            st.session_state.project_name = project.get("project_name", "Untitled_Project")
            st.session_state.active_tool = project.get("active_tool", [])
            st.session_state.dp_canvas = copy.deepcopy(project.get("pipeline", []))
            st.session_state.dq_rules_config = project.get("dq_rules", {})
            incoming_selections = project.get("user_selections", {})
            st.session_state.selected_columns = list(incoming_selections.get("selected_columns", []))
            st.session_state.join_columns = list(incoming_selections.get("join_columns", []))
            st.session_state.key_column = incoming_selections.get("key_column", None)
            st.session_state.tool_config = copy.deepcopy(project.get("tool_configs", {}))

        if "discovered_operators" in project:
            for op in project["discovered_operators"]:
                if op not in st.session_state.discovered_operators:
                    st.session_state.discovered_operators.append(op)

        extract_custom_operators_recursively(st.session_state.tool_config)
        extract_custom_operators_recursively(st.session_state.dp_canvas)

        if cached_df is not None:
            st.session_state.current_df = cached_df
            st.session_state.last_processed_columns = list(cached_df.columns)
            migrated_runtime = {}
            for page_key, runtime in st.session_state.get("page_runtime_configs", {}).items():
                migrated_runtime[page_key] = migrate_runtime_config(runtime, cached_df.columns)
                st.session_state.tool_config.update(migrated_runtime[page_key].get("config", {}))
            if migrated_runtime:
                st.session_state.page_runtime_configs = migrated_runtime
            restore_saved_page_widget_states()
            run_global_pipeline_reconciliation()

        commit_save_action()
        st.success("Project schema and tool parameters restored perfectly!")
        st.rerun()

    except Exception as ex:
        st.error(f"Unable to load project file safely: {ex}")


if "active_tool" not in st.session_state:
    st.session_state["active_tool"] = []

# =========================================================
